window.ALBUM_SONGS = [{"slug": "a-to-z", "ep": false, "versions": [{"stem": "a-to-z_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "A to Z", "lyrics": "[Intro: drums alone, then the Rhodes loop]\n\n[Verse 1]\nFebruary, birthday, she handed me a canvas,\nCopied from an email from the early days, back when we were candid;\nIt went A to Z, every letter something good,\nTwenty-six reasons I was loved, and I understood.\nOne of the nicest things anybody ever made me;\nHung it on the wall like a diploma, like it graded me.\nI read it with my coffee every morning like scripture;\nI was proud to be the subject, I was proud to be the picture.\nFunny how you trust a thing once it's framed behind glass;\nI thought the ink was permanent. I didn't know it fades that fast.\n[double-time] Laughing in the kitchen, kissing in the hallway, the alphabet was ours and we could spell it every way,\nI'd recite it in my sleep, A to Z and back, I'd have bet the house and every year we had on that,\n[half-time] A month later,\n[pause] Same wall. Different man.\n\n[Hook: chanted, doubled]\nFebruary framed me. Summer erased me.\nTwenty-six letters, and none of 'em face me.\nA to Z on the wall. I don't know who you saw.\nTook twenty-six to build it. Took two words to take it all.\nFebruary framed me. Summer erased me.\nTwenty-six letters, and none of 'em face me.\nA to Z on the wall. I don't know who you saw.\nTook twenty-six to build it. Took two words to take it all.\n\n[Verse 2]\nA month after that, wasn't a letter on it left that fit;\nSame frame, same nail, but the man inside it got evicted.\nYou wrote me A to Z, then acted like you couldn't read it;\nHung me on the wall, then walked right past me like you didn't see it.\nI know my flaws. I ain't pretending I was spotless,\nBut the stranger you described, I never met him. Where you got this?\nDid I become somebody else, or did the story change?\nI still answer to the name. You started saying it another way.\nWhen did our history become the evidence against me?\nInside jokes in evidence bags, initialed, dated, sealed, and empty.\n[double-time] Every \"always\" turned to \"never,\" every \"tender\" turned to \"temper,\" every letter on the canvas getting entered as exhibits,\nSame alphabet, same ink, I'm getting spelled a different way, I'm reading my own name and I don't recognize the spelling in it,\n[half-time] I don't know who you saw.\n[pause] I just know it wasn't me.\n\n[Hook: chanted, doubled]\nFebruary framed me. Summer erased me.\nTwenty-six letters, and none of 'em face me.\nA to Z on the wall. I don't know who you saw.\nTook twenty-six to build it. Took two words to take it all.\n\n[Verse 3: drums drop to kick and hats, then build]\nTake the U out of US and all that's left is an S:\nS for the silence, S for the stress, S for the self I'm stitching out the mess.\nNow every song's a stroke on a canvas that I'm making;\nNo frame, no nail, no glass, nothing anybody's taking.\nThe picture ain't sewn together yet; I'm still threading the needle,\nTwenty-seven years of rough drafts, and every one of 'em's a sequel.\nI ain't the alphabet you hung up on the wall;\nI'm the letters you left off. I'm the crooked ones. I'm all of it.\n[double-time] Brush strokes, bruise tones, black coats, back roads, hand-wrote, ink smudge, cold nights, dried blood, it comes how it comes,\nEvery line I didn't like I left in, every scar is a signature, every verse is a start, and I'm nowhere near done,\n[half-time] You can keep the twenty-six.\n[pause] I'm only signing one.\n\n[Final Hook: full beat, chanted, doubled]\nFebruary framed me. Summer erased me.\nTwenty-six letters, and none of 'em face me.\nNow I'm painting it myself, every crack in the wall.\nTook you twenty-six letters. I need one. I. That's all.\nFebruary framed me. Summer erased me.\nTwenty-six letters, and none of 'em face me.\nNow I'm painting it myself, every crack in the wall.\nTook you twenty-six letters. I need one. I. That's all.", "suno": {"title": "A to Z", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 90 BPM, dusty swung drum break, hard cracking snare, bittersweet minor-key vintage Rhodes loop, low bowed string swell, deep upright bass, vinyl crackle, narrow smoky mix; male mid-low rap, wounded and sardonic, dense multisyllabic internal rhymes, relaxed pocket into double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 8, 2026. Writer: Cue (Claude). Concept and source phrases: Scatta (97 NEW notes). Status: written listening candidate, unauditioned and unapproved.", "chars": 3750}], "title": "A to Z", "session": "Oct 8 Reset", "latest": "a-to-z_v01_Cue"}, {"slug": "cardboard-masterpiece", "ep": false, "versions": [{"stem": "cardboard-masterpiece_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "Cardboard Masterpiece", "lyrics": "[Intro: a box cutter click, then the piano, then the break]\n\n[Verse 1]\nYoungest came home from school with a plan and a look,\nSaid her class built leprechaun traps, and she was hooked.\nFirst thing after dinner, didn't ask, didn't wait,\nDragging boxes out the garage like she's building an estate.\nCardboard thicker than her arms, scissors bending in her grip,\nSawing at a flap for ten minutes, barely made a rip.\nI been fixing other people's broken all day, I'm wiped,\nBut I sat down on the floor with her. Something in me liked\nThe sound of her deciding I could help. So I held, and she cut;\nShe designed, and I taped, and the walls went up.\n[double-time] Ramp out of a cereal box, a ladder out of popsicle sticks, a sign that said \"free gold\" in a marker that was running out of ink,\nA trapdoor out of a shoebox, a string and a stick and a cup, and a roof that kept caving, and we fixed it again, and again, and I didn't once think,\n[half-time] About the year.\n[pause] About anything.\n\n[Hook: chanted low, doubled]\nCardboard masterpiece, ain't worth a dime;\nFive hours on a school night, past bedtime. I don't mind.\nNever caught a leprechaun. Caught a little time.\nCanadian coins at the end of the rainbow. Looked special. That's fine.\nCardboard masterpiece, ain't worth a dime;\nFive hours on a school night, past bedtime. I don't mind.\nNever caught a leprechaun. Caught a little time.\nCanadian coins at the end of the rainbow. Looked special. That's fine.\n\n[Verse 2]\nThen the middle one walked by, said, \"That's cute,\" kept walking;\nTen minutes later she's got her own box and she's not talking.\nBuilding her own, a whole competitor, a rival design,\nBetter engineered than mine, I'm not gonna lie.\nOldest stayed upstairs. Too old for leprechauns, too cool;\nWay past bedtime she came down in socks and grabbed the glue.\nThree girls on the living room floor, scraps everywhere,\nTape stuck to the dog, cardboard dust in everybody's hair.\nThis was the year I couldn't keep a single thing standing;\nAnd here's a trap for a fairy tale with a perfect landing.\n[double-time] Glue gun, glue stick, scissors, box cutter, tape gun, a pencil behind my ear like I'm the foreman on a job site, the girls on the clock,\nMeasuring nothing, guessing at everything, a ruler we never used, a level we didn't need, and a laugh I ain't heard in the house in a lot,\n[half-time] Five hours.\n[pause] Felt like five minutes.\n\n[Hook: chanted low, doubled]\nCardboard masterpiece, ain't worth a dime;\nFive hours on a school night, past bedtime. I don't mind.\nNever caught a leprechaun. Caught a little time.\nCanadian coins at the end of the rainbow. Looked special. That's fine.\n\n[Verse 3: drums drop to kick and piano, then build]\nMorning: four forty-five, I'm standing over the trap,\nRealizing something. A trap needs bait. A trap needs a catch.\nNothing in the house but cereal dust and a cup of change;\nTexted their mom at five a.m., \"Bring anything. Anything. Something strange.\"\nShe had Canadian coins. Brought 'em by before school. I said thanks,\nAnd meant it. Whatever else we are, for the girls we close ranks.\nYoungest found 'em at the bottom of the trap, eyes huge,\nSaid they looked special. Funny what a kid can make true.\n[double-time] Loonies and the twonies and a quarter with a caribou, a queen on the back, a little gold in the dark at the bottom of a cardboard box in the light of the dawn,\nShe held 'em up like treasure, and they were, and they weren't, and it don't matter which, 'cause she decided, and the deciding is the gold, and she was right all along,\n[half-time] Never caught the leprechaun.\n[pause] Caught the night.\n\n[Final Hook: full beat, chanted, doubled]\nCardboard masterpiece, ain't worth a dime;\nFive hours on a school night, past bedtime. I don't mind.\nNever caught a leprechaun. Caught a little time.\nBest thing I built all year, and it's already on the curb. That's fine.\nCardboard masterpiece, ain't worth a dime;\nFive hours on a school night, past bedtime. I don't mind.\nNever caught a leprechaun. Caught a little time.\nBest thing I built all year, and it's already on the curb. That's fine.", "suno": {"title": "Cardboard Masterpiece", "lyrics": null, "style": "Gritty underground East Coast boom-bap, late 90s, 92 BPM, dusty swung drum break, warm cracking snare, bittersweet minor-key piano loop, soft Rhodes, deep upright bass, vinyl crackle, narrow smoky mix; male mid-low rap, warm but dry, quiet pride, dense multisyllabic internal rhymes, relaxed pocket into double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 8, 2026. Writer: Cue (Claude). Concept, title and story: Scatta (your March 17 and 18, 2026 messages, via the Studio Launch source file). Status: written listening candidate, unauditioned and unapproved.", "chars": 4105}], "title": "Cardboard Masterpiece", "session": "Oct 8 Reset", "latest": "cardboard-masterpiece_v01_Cue"}, {"slug": "check-out", "ep": false, "versions": [{"stem": "check-out_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "Check Out", "lyrics": "[Intro: a key card beep, the hum of a hotel hallway, then the break]\n\n[Verse 1]\nJuly, twenty twenty-four, I packed a bag and said, \"By noon\nI'm out your hair for good.\" Hotel off the highway, a stranger's room.\nCarpet with a stain shaped like a state I never been to,\nAC rattling like a cough, the walls so thin I hear the TV in two.\nThis hotel seriously sucks. Ice machine screaming down the hall;\nFree breakfast was a waffle and a bruise of a banana. That was all.\nShe sent a song that night: said the lyrics were how she felt,\n\"Including the hotel part.\" I read it twice, then typed it out myself:\n\"But I'm in the hotel, and I know who I am.\" Sent.\nSat on a bed made by somebody paid not to care where I went.\n[double-time] Key card, do not disturb, a Bible in the drawer, a remote with a rubber band holding the batteries in, a lamp with a burn on the shade,\nA carpet, a curtain, a parking lot light coming in through the gap, and a man on the end of the bed with his bag still packed and his phone in his hand and afraid,\n[half-time] Flew to Texas from there.\n[pause] Came back and kept fighting.\n\n[Hook: chanted low, doubled]\nYou checked out two and a half years ago;\nI kept paying for the room, kept the lamp on low.\nThat fight ends now. Key card on the counter, face down.\nDo Not Disturb on the door. My turn to check out.\nYou checked out two and a half years ago;\nI kept paying for the room, kept the lamp on low.\nThat fight ends now. Key card on the counter, face down.\nDo Not Disturb on the door. My turn to check out.\n\n[Verse 2]\nTwo and a half years on an extended stay\nIn a marriage she'd already checked out of. I just paid and paid.\nNever wanted the divorce. Fought it longer than I should;\nKept a door open like a room on hold, like the hold was any good.\nEvery time she knocked, I opened it. Every time, it hurt again;\nEvery time I healed a little, somebody slid a bill under the door. Then\nI'd open up my heart, she'd let me in a little, for a little while,\nThen the lights would go out in the hall, and I'm alone with the bill and the dial tone.\nHousekeeping came and went. Nobody made the bed I lay in;\nTwo and a half years of a room service menu, and I never once got what I was paying.\n[double-time] Front desk, wake-up call, late checkout, the minibar, the folio, the charges I never made and I paid anyway, the extension, the extension, the extension again,\nFighting for a reservation that she canceled two summers ago and never told the desk, and the desk kept telling me \"sir, it's still in your name,\" and it was, and it's been,\n[half-time] I'm exhausted.\n[pause] That's not a threat. It's a weather report.\n\n[Hook: chanted low, doubled]\nYou checked out two and a half years ago;\nI kept paying for the room, kept the lamp on low.\nThat fight ends now. Key card on the counter, face down.\nDo Not Disturb on the door. My turn to check out.\n\n[Verse 3: drums thin, keys stay]\nAugust, twenty twenty-six, I wrote it plain, no rhyme in it:\n\"I need to make something clear.\" I meant it, every line in it.\nDon't help me pack. Don't help me move. Don't clean the house for me.\nI don't need you anymore for anything that isn't the girls or the decree.\nWe'll always be the parents of three. That part I'll never run from;\nEverything else gets distance. That ain't punishment. I'm just done.\nA few weeks back I told you being alone had started to feel like peace;\nNow I gotta live like it. Pack it. Fold it. Leave the key.\nPlease don't contact me unless it's the girls or the papers.\nSigned it with my name. First time in years it felt like mine on paper.\n[double-time] Hangers on the rod, the drawer pulled out, the outlet checked for chargers, under the bed for socks, the bathroom for the razor, the last look at the room from the door,\nLights off, door shut, click, the hallway long and quiet and the elevator open like it was waiting on me the whole time and I just never pressed the floor,\n[half-time] Checkout was at eleven.\n[pause] I left at ten.\n\n[Final Hook: full beat, chanted, doubled]\nYou checked out two and a half years ago;\nI kept paying for the room, kept the lamp on low.\nThat fight ends now. Key card on the counter, face down.\nDo Not Disturb on the door. Peace. I'm checked out.\nYou checked out two and a half years ago;\nI kept paying for the room, kept the lamp on low.\nThat fight ends now. Key card on the counter, face down.\nDo Not Disturb on the door. Peace. I'm checked out.", "suno": {"title": "Check Out", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 87 BPM, steady swung drum break, cracking snare, lonely minor-key Rhodes and piano loop, faint air-conditioner hum, deep upright bass, vinyl crackle, narrow smoky mix; male mid-low rap, calm and final, quiet strength, dense multisyllabic internal rhymes, relaxed pocket into double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 8, 2026. Writer: Cue (Claude). Source: your July 2024 hotel messages and your August 18, 2026 message (Seed Bank: Check Out). Status: written listening candidate, unauditioned and unapproved.", "chars": 4412}], "title": "Check Out", "session": "Oct 8 Reset", "latest": "check-out_v01_Cue"}, {"slug": "clear", "ep": false, "versions": [{"stem": "clear_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "Clear", "lyrics": "[Intro: a flat monitor tone, then a charge whine, then the break slams in]\n\n[Verse 1]\nBiomedical technician, man with the multimeter,\nCalibrating instruments that keep you breathing. I'm the keeper\nOf the line between the living and the leaving. Read impedance\nLike a palm. I hear a failing capacitor confess its secrets.\nOscilloscope vision: I can see your verse as a waveform,\nNo amplitude, all noise floor, flat as a morgue drawer.\nYour flow's got arrhythmia, ventricular, irregular,\nSixteen bars of fibrillation, quivering, not a heartbeat, just a tremor.\nMe? I flatlined in ninety-nine. Tone held steady, one long beep;\nTwenty-seven years of asystole with the paddles in my reach.\n[double-time] Pads on, gel on, pulse check, no pulse, the monitor singing a single note, the crash cart rolling, I'm hearing the whine of the charge,\nCapacitor filling, the needle is climbing, two hundred, three hundred, three sixty, the room holding breath, and I'm holding the pen like a paddle and pressing it hard,\n[half-time] Everybody back.\n[pause] Clear.\n\n[Hook: chanted hard, doubled]\nCharging. Two hundred joules. Everybody stand clear.\nFlatlined in ninety-nine. Shocked it back after twenty-seven years.\nSinus rhythm in the pen. Every bar's a heartbeat. Hear?\nCharging. Stand clear. Clear.\nCharging. Two hundred joules. Everybody stand clear.\nFlatlined in ninety-nine. Shocked it back after twenty-seven years.\nSinus rhythm in the pen. Every bar's a heartbeat. Hear?\nCharging. Stand clear. Clear.\n\n[Verse 2]\nThey had me pronounced: toe tag, the drawer, cold storage, case closed,\nA binder full of verses in a shoebox where the basement water flows.\nThen the marriage burned down, the smoke cleared, and the whole house was empty,\nAnd the only thing still warm in all them ashes was the pen. It sent me.\nLazarus with a badge clip, got up off the gurney mid-sentence,\nPulled the IV out and wrote sixteen on the back of my discharge instructions.\nNow I'm epinephrine in the vein of a culture that's barely beating,\nAtropine for the slow ones, adenosine for the ones that's speeding.\nYour album got a DNR. Your label signed the paperwork;\nComfort care, a morphine drip of streams. I'm the code team. Watch the paddles work.\n[double-time] V-fib, V-tach, asystole, brady, PEA, the whole algorithm, I memorized it at the bench with the monitor screaming in my ear,\nShock, compressions, two minutes, rhythm check, shock, compressions, epi, rhythm check, the rhythm is coming back, the rhythm is coming back, the rhythm is here,\n[half-time] Got a pulse.\n[pause] Mine.\n\n[Hook: chanted hard, doubled]\nCharging. Two hundred joules. Everybody stand clear.\nFlatlined in ninety-nine. Shocked it back after twenty-seven years.\nSinus rhythm in the pen. Every bar's a heartbeat. Hear?\nCharging. Stand clear. Clear.\n\n[Verse 3: piano stabs out, drums and bass only]\nWhat killed it? Nothing dramatic. Life with the volume up:\nAir Force, a wedding, three daughters, the mortgage, the shifts, the rush.\nEvery year I said \"next year,\" and every year the line went flat;\nI wasn't dead. I was waiting for a reason to come back.\nDivorce is a defibrillator: hurts like hell, restarts the heart.\nNobody'd choose the shock. But damn, look at the pulse on the chart.\nEvery PM at work I test the defibs, sign the sticker, log the date;\nTonight I put the pads on my own chest, and I didn't hesitate.\n[double-time] Canibus in the headphones, Sage in the notebook, Slug on the drive to the job, Pun in the double-time, DOOM in the pocket, the dead and the living alike,\nTwenty-seven years of the silence, the static, the flatline, the long beep, the tone, and I'm pressing the button and holding it down, and I'm ready to strike,\n[half-time] Time of death: ninety-nine.\n[pause] Time of birth: tonight.\n\n[Final Hook: beat back hard, chanted, doubled]\nCharging. Two hundred joules. Everybody stand clear.\nFlatlined in ninety-nine. Shocked it back after twenty-seven years.\nSinus rhythm in the pen. Every bar's a heartbeat. Hear?\nI ain't asking for permission. I'm the one holding the paddles. Clear.\nCharging. Two hundred joules. Everybody stand clear.\nFlatlined in ninety-nine. Shocked it back after twenty-seven years.\nSinus rhythm in the pen. Every bar's a heartbeat. Hear?\nI ain't asking for permission. I'm the one holding the paddles. Clear.", "suno": {"title": "Clear", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 94 BPM, hard punchy drum break, slamming snare, tense minor-key piano stabs, ominous low strings, rising electronic charge whine, deep distorted bass, vinyl grit, raw mix; male mid-low rap, aggressive technical precision, relentless dense multisyllabic rhymes, rapid double-time bursts, hard chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 8, 2026. Writer: Cue (Claude). Concept: Cue's proposal, built on your BMET work, your influences list and your return to hip-hop. Status: written listening candidate, unauditioned and unapproved.", "chars": 4306}], "title": "Clear", "session": "Oct 8 Reset", "latest": "clear_v01_Cue"}, {"slug": "daily-reminder", "ep": false, "versions": [{"stem": "daily-reminder_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "Daily Reminder", "lyrics": "[Intro: a phone notification chime, then the piano, then the break]\n\n[Verse 1]\nTwenty twenty-one: \"So proud of you. I don't tell you this enough.\"\nI told her every morning. That's the part I can't get past. That's the stuff.\nFirst day at the new job: \"Have a great first day! So proud!\"\nExam day: \"Good luck! We're all sooo sooo proud,\" with the extra O's out loud.\nJune twenty twenty-three, a ribbon emoji on a text:\n\"Daily reminder: you are loved, beautiful, appreciated.\" Next.\nAugust: \"You're more beautiful to me than the day I saw your profile pic;\nStill give me butterflies.\" I meant it. I was sick with it.\nSigned 'em \"Indivisible,\" like a pledge, like the flag on a wall;\nI'm Air Force. I know an oath when I swear one. I swore it. That's all.\n[double-time] I love you so much you are the best thing to ever happen to me I am blessed to have you indivisible good morning good afternoon good night you're the best wife in the whole universe I love you forever,\nThat's a real text, that's word for word, no period, no comma, no breath, 'cause I didn't need one, 'cause I thought we had forever, and forever was clever,\n[half-time] Hit send at sunrise.\n[pause] Every day.\n\n[Hook: chanted low, doubled]\nDaily reminder: you are loved, beautiful, appreciated.\nEvery morning, every exam, every shift. I never once debated.\n\"So proud of you.\" \"Good luck.\" \"Indivisible.\" Delivered. Read.\nYears of daily reminders. Nobody ever sent me one instead.\nDaily reminder: you are loved, beautiful, appreciated.\nEvery morning, every exam, every shift. I never once debated.\n\"So proud of you.\" \"Good luck.\" \"Indivisible.\" Delivered. Read.\nYears of daily reminders. Nobody ever sent me one instead.\n\n[Verse 2]\nDecember, twenty twenty-three, I finally said it plain:\n\"I never say I'm not proud of you. I say I'm proud of you. Again.\nI say it so much, and yet you believe the opposite.\"\nThousand reminders in, and every one of 'em bounced off of it.\n\"Almost done! So proud of you!\" Eight exclamation points, then she finished;\nWalked across the stage. I clapped the loudest. Then the marriage diminished.\nIndivisible, I signed it. Then we divided everything:\nThe house, the weeks, the kids, the debt, the dishes, the dog bowl, the ring.\nOne nation under nothing. Liberty and custody for all;\nTwo calendars on two refrigerators, and a pledge on the wall.\n[double-time] Divide the plates, divide the cups, divide the photos, divide the Christmas ornaments by who bought 'em, divide the girls by the weekday and the weekend and the summer and the holidays,\nDivide the friends, divide the family, divide the dog's affection, divide the tears down the middle, and sign it in triplicate, that's the indivisible way,\n[half-time] Read receipts on every one.\n[pause] Not one came back.\n\n[Hook: chanted low, doubled]\nDaily reminder: you are loved, beautiful, appreciated.\nEvery morning, every exam, every shift. I never once debated.\n\"So proud of you.\" \"Good luck.\" \"Indivisible.\" Delivered. Read.\nYears of daily reminders. Nobody ever sent me one instead.\n\n[Verse 3: the chime comes back, drums thin]\nSomewhere in the rebuild, my therapist said, \"Who reminds you?\"\nI laughed. Then I didn't. Then I sat there with the question like a tissue.\nNobody. Nobody did. I was everybody's daily reminder,\nAnd the reminder never had one. That's a bell with no ringer.\nSo I started sending 'em to the girls: \"Proud of you. Have a great day.\"\nAnd the girls started sending 'em back: a heart, a \"Love you,\" a \"Daddy, okay.\"\nThree Father's Day cards that said \"Daddy is funny\" on the fridge with a magnet;\nThat's a daily reminder. I just had to stop and read it. I had it.\nAnd one morning, I wrote one to me, and I didn't even feel stupid;\nTyped it in my notes: \"You are loved.\" Read it like the law. Didn't lose it.\n[double-time] You are loved, you're appreciated, you're a good dad, you're a good tech, you're a good friend, and you're funny, and you're forty-three and you're still here, you're not a mistake,\nYou're not the man she described, you're the man in the notes app at sunrise, you're the one who sends the reminders, and now you're the one who receives one, for heaven's sake,\n[half-time] Read it twice.\n[pause] Got out of bed.\n\n[Final Hook: full beat, chanted, doubled]\nDaily reminder: you are loved. You're appreciated.\nEvery morning in the mirror now. Took me years, but I made it.\n\"So proud of you.\" \"Good luck.\" \"Indivisible.\" Delivered. Read.\nWrote one to myself this morning. Read it twice. Got out of bed.\nDaily reminder: you are loved. You're appreciated.\nEvery morning in the mirror now. Took me years, but I made it.\n\"So proud of you.\" \"Good luck.\" \"Indivisible.\" Delivered. Read.\nWrote one to myself this morning. Read it twice. Got out of bed.", "suno": {"title": "Daily Reminder", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 90 BPM, hard swung drum break, cracking snare, looping minor-key piano with a soft bell-like top note, deep upright bass, vinyl crackle, narrow smoky mix; male mid-low rap, tender then bitter then steady, dense multisyllabic internal rhymes, relaxed pocket into double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 8, 2026. Writer: Cue (Claude). Source: your \"so proud of you\" messages, 2021 to 2025, and your \"Indivisible\" sign-offs (Seed Bank: Daily Reminder). Status: written listening candidate, unauditioned and unapproved.", "chars": 4733}], "title": "Daily Reminder", "session": "Oct 8 Reset", "latest": "daily-reminder_v01_Cue"}, {"slug": "dead-souls", "ep": false, "versions": [{"stem": "dead-souls_v11_Misc", "version": 11, "writer": "Misc", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "Dead Souls", "lyrics": "[Verse 1 - low, dry, deliberate]\nI can't live properly; the dead souls are stopping me,\nDropping me on my own property. They still got me.\nGazing off into a realm of my own reality;\nThe view's fucking enormous. There's no room in it for me.\nWhat I've become is a man with no roads to cross.\nThe horizon's just a long way of saying I am lost.\n[double-time] Past mistakes, past takes in the past tense; pass the plates,\nAfter the lens takes rapid fakes, the fucking frames begin to shake.\n[half-time] I still remember it.\n[pause] That's what I can't get past.\nCross around my neck for those that lost life;\nI keep it near the place I used to feel mine.\nI tend to do what's wrong when the time is right;\nMy watch is precise. It keeps announcing fucking night.\nLiving in the lands of the lost, hands of the clocks locked;\nWhole fucking world goes on. I'm still standing in the same spot.\n\n[Hook - fully rapped, clipped attacks]\nDead souls. Still got me.\nCan't live properly in my own body.\nNot dead. That's the worst part.\nSomething keeps pumping through the place I had a heart.\n\n[Verse 2 - shift behind the snare]\nIt was you that I thought I earned, but I never learned;\nThe black haze never lifted. Only changed the way it burned.\nDon't misconstrue, though. Never took the bait—just a little nibble.\nHook still in my mouth. It doesn't give a fuck about the riddle.\nMy lifetimes are made up of white lines and night cries;\nWhite lies bleed red when you hold them to the light.\nWhat I said never meant shit. Now the words won't come out right.\nI can make the fucking page bleed. Doesn't mean that I'm alive.\n[double-time] Plant your seeds in the plantations where the vultures feed, the pressure seeps,\nWeeks of heat beneath the roots; the fucking beaks are working while I sleep.\n[half-time] Nothing here is growing.\n[pause] Something's getting fed.\nThe ghost has the coast clear; I'm choking till I can't breathe.\nI pull in air. There's nothing in it I can keep.\nI'm not trying to die these days. The fact is, I already have.\nRemember back. The shattered glass. I can't reverse that.\n\n[Hook - fully rapped, clipped attacks]\nDead souls. Still got me.\nCan't live properly in my own body.\nNot dead. That's the worst part.\nSomething keeps pumping through the place I had a heart.\n\n[Bridge - drums drop, rhythmic chant]\nPut your hand here.\nTell me what you feel.\nSomething's keeping time.\nI can't tell if it's real.\n\n[Verse 3 - close, gathering pressure]\nI'm having problems with these out-of-body experiences.\nBlank thoughts. Rain pains. Drop the needle; hear the skipping in it.\nA life that was once written, then ripped from inside my head;\nEvery little piece can tell you who I'm not. That's all that's left.\nI begin to befriend who I really am. It's slow going.\nI can't tell if I'm getting close or if the hole is growing.\n[double-time] Dream permissions, ripped revisions, rain in rhythms, ink incisions,\nFists of mist inside my ribs; I keep my fingers stiff to grip it.\n[half-time] I'm not dead.\n[pause] I just can't feel my life.\nBorn with a heart that was black, with some holes in it;\nHold it to the light. Light goes straight through the whole of it.\nLost in the maze I made. I can draw it with my eyes closed.\nCan't tell you where the way out is. I know where all the dead ends go.\n\n[Final Hook - rapped, bare drums]\nDead souls. Still got me.\nCan't live properly in my own body.\nNot dead. That's the worst part.\nI can feel the fucking beat. I can't feel the heart.", "suno": {"title": "Dead Souls", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 92 BPM, swung pocket, heavy dry kick, cracked backbeat snare, sparse detuned minor-key piano, ominous bowed bass, deep rounded bassline, dusty vinyl; male mid-low rap, crisp confessional menace, dense multisyllabic internal rhymes, controlled double-time bursts, fully rapped hooks with light doubles, close centered vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "", "chars": 3470}, {"stem": "dead-souls_v12_Cue", "version": 12, "writer": "Cue", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "Dead Souls", "lyrics": "[Intro: dusty break alone, detuned piano enters on bar 3]\n\n[Verse 1]\nWhat I've become is a man with no roads to cross,\nSo what do I get from these dead souls that are tossed?\nThird strings hanging from the ropes in the rooms of dead things,\nMarionette, retired, still twitching when the bell rings.\nIt damages the mind, these normal little processes:\nCoffee, overtime, the fruit of all these dead bosses.\nWith a forward face and nobody's back turned,\nIt's a black haze. It was you I thought I earned, but I never learned.\nI fix the monitors that tell you when a heart has stopped;\nMine flatlined a year ago. Nobody called a code. I clocked in,\nWrote my own work order: tested, no problem found, and then\nReturned to service, back on the floor. Nobody looked again.\n[double-time] Battery low, casing cracked, cable frayed, label faded, latch is broke,\nAlarm muted, volume zero, screen still lit, I passed inspection, though.\n[half-time] Sticker on my chest says next due, next year.\n[pause] Dead men make good employees. We never call in.\n\n[Hook: chanted low, doubled]\nDead souls stopping me, dropping me on my own property,\nI can't live properly, the ghost got the coast clear, robbing me.\nNot dead. I'm not dead. I'm just living with no heart in my chest.\nDead souls, take a number. Get in line with the rest.\nDead souls stopping me, dropping me on my own property,\nI can't live properly, the ghost got the coast clear, robbing me.\nNot dead. I'm not dead. I'm just living with no heart in my chest.\nDead souls, take a number. Get in line with the rest.\n\n[Verse 2]\nIn the clouds is where she lies today. I mean the one I made up,\nThe version that I kept alive to keep from waking up.\nI feed her all the lies she needs; the pressure seeps for weeks,\nAnd I can't see the heat we breed in our own seeds till it's buckled in the back seat.\nOn my knees daily, fade me into my own existence, then raid me,\nSave me after I murder this lovely lady.\nNot the woman. The ghost of her I kept up on the mantel,\nSmiling in a dress from a day she'd rather cancel.\nThe one I fell for before I even knew her;\nThe real one moved out. The ghost stayed. So who's the intruder?\nMy lifetimes are made up of white lines and night cries,\nDashes on the interstate, I count 'em like sheep at night.\n[double-time] Perfume on a pillowcase, a pillar made of salt, I looked back and I paid,\nLipstick on a coffee lid, a coffin lid, I kissed it shut and kept the taste,\n[half-time] I buried her in me.\n[pause] And the dead still talk in their sleep.\n\n[Hook: chanted low, doubled]\nDead souls stopping me, dropping me on my own property,\nI can't live properly, the ghost got the coast clear, robbing me.\nNot dead. I'm not dead. I'm just living with no heart in my chest.\nDead souls, take a number. Get in line with the rest.\n\n[Bridge: drums drop, low whispered chant, the souls talking]\nWe will have your soul as soon as you detach the heart.\nPlay the role of hate inside. We wait for you to depart.\nLeave the porch light off. Leave the door ajar.\nWe will have your soul as soon as you detach the heart.\n\n[Verse 3: beat creeps back, bass first]\nWho is supposed to oppose what I suppose is what I believe?\nThe ghost has the coast clear, choking me till I can't breathe.\nBorn in a palace of malice, my ego vanished in the past tense,\nRaised without the praise, so I practiced clapping for the absence.\nI'm not trying to die these days. The fact is, I already have.\nRemember back: it shattered last year, that burning glass. Reverse that.\nFlip it over, take a look in these great grains of sand;\nI can see you now as I live on as a dead man.\nRain pains, locked in with flocks of dead people under my skin,\nTelling myself who I am not, and what I got is hot as I rot in it.\n[double-time] Fishing for the life that was written at night with my dream's permission, then ripped\nFrom the inside of the inside of my head, where the dead keep a needle and thread at my lips,\n[half-time] Hooked my own leads up on the bench after the shift.\n[pause] Weak. Irregular. Mine.\n\n[Final Hook: beat back hard, chanted, doubled]\nDead souls stopping me, dropping me on my own property,\nI can't live properly, but the ghost ain't done robbing me.\nNot dead. I'm not dead. There's a beat in my chest.\nDead souls, take a number. I'll get to the rest.\nDead souls stopping me, dropping me on my own property,\nI can't live properly, but the ghost ain't done robbing me.\nNot dead. I'm not dead. There's a beat in my chest.\nDead souls, take a number. I'll get to the rest.", "suno": {"title": "Dead Souls", "lyrics": null, "style": "Dark underground East Coast boom-bap, late 90s, 92 BPM, swung pocket, heavy dry kick, cracked backbeat snare, sparse detuned minor-key piano, ominous bowed bass, deep rounded bassline, dusty vinyl; male mid-low rap, crisp conversational menace, dry morbid humor, double-time bursts and punchline pauses, fully rapped hooks with light doubles, close centered vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v12. October 8, 2026. Writer: Cue (Claude). Base lyricist: Scatta (2001). Status: written listening candidate, unauditioned and unapproved.", "chars": 4508}], "title": "Dead Souls", "session": "Oct 8 Reset", "latest": "dead-souls_v12_Cue"}, {"slug": "ep2b-exorcism", "ep": true, "versions": [{"stem": "ep2b-exorcism_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "Exorcism", "lyrics": "[Intro: a distant church bell, organ drone, then the break]\n\n[Verse 1]\nShe said, \"Something's in you,\" and I believed her, 'cause I loved her;\nEvery time I opened up my mouth, she heard a stranger under.\nSo I said, \"Okay. Fix me. Bring whatever you need.\"\nAll she wanted was a clean exorcism. Get the devil out. Leave.\nLaid me on the bed, wrists tied with the good sheets,\nCandles on the dresser like a birthday for the deceased.\nPriest walks in with the bag and the book and the bottle,\nLooks at me, then looks at her a little too long. Swallows.\nCross around my neck from Mama, been there since I was a kid;\nFunny for a devil: it don't burn. It never did.\n[double-time] Hail Mary, full of grace, the beads in his hand and the sweat on his face and the smoke of the incense filling the space and the wind in the place,\nOur Father, who art in heaven, I'm saying it with him, I know every word of it, been saying it since I was seven, I'm saying it straight to his face,\n[half-time] Priest stopped praying.\n[pause] \"Son, how do you know the words?\"\n\n[Hook: chanted low, doubled]\nCast it out. Cast it out. Cast it out of me.\nPriest been praying three hours over the wrong body.\nHoly water on my skin, and it's only water, see?\nOne drop hit the angel. Listen to it steam.\nCast it out. Cast it out. Cast it out of me.\nPriest been praying three hours over the wrong body.\nHoly water on my skin, and it's only water, see?\nOne drop hit the angel. Listen to it steam.\n\n[Verse 2]\nPriest asked the thing inside me for its name. I said my name. Just mine.\nThen a voice behind him whispered something else, and it wasn't from my side.\nHoly water on my chest: it's cold, it's wet, it's water.\nHe flicked the bottle back to bless the room. A drop hit her collar.\nSizzle. Smoke. She slapped it like a mosquito, laughing it off:\n\"It's hot in here.\" It's thirty degrees. Priest wiped his glasses off.\nBook says the possessed can't stand to hear the name of God;\nI said it forty times. She left the room to take a call.\nEvery time he reached for my forehead, the candles leaned toward the hall;\nEvery time she walked back in, the crucifix slid down the wall.\n[double-time] Exorcizo te, the Latin, the bell, the book, the candle, the sweat, the crucifix shaking in his hand, and the stains on the sheet,\nThe lights flicker behind him, the mirror goes foggy, the dog in the hallway is growling, but not at the bed, he's growling at her feet,\n[half-time] Dog don't growl at me.\n[pause] Dog never did.\n\n[Hook: chanted low, doubled]\nCast it out. Cast it out. Cast it out of me.\nPriest been praying three hours over the wrong body.\nHoly water on my skin, and it's only water, see?\nOne drop hit the angel. Listen to it steam.\n\n[Verse 3: bell stops, drums thin]\nThree hours in, the priest sat down on the edge of the bed,\nUntied my wrists, checked my pulse, put a hand on my head.\nSaid, \"Son, there's nothing in you but a tired man with a broken heart.\"\nShe said, \"He's too far gone. It's hiding. That's how they start.\"\nPriest packed the bag up slow: the book, the bell, the bottle, the beads,\nLooked at her a long time. Didn't say it. Didn't need.\nI sat up in the candlelight, cross still cool against my chest;\nFirst time in years I asked myself who's been possessing this address.\n[double-time] Bag zipped, bottle capped, the candle out, the door open, the cold coming in with the night and the porch light, the priest in the car and the engine, the end,\nShe's on the phone in the kitchen, laughing like nothing, the voice that she saves for everybody else, and I'm on the bed in the dark with my wrists red, my faith bent,\n[half-time] On his way out, the priest made the sign of the cross.\n[pause] Facing her.\n\n[Final Hook: full beat, chanted, doubled]\nCast it out. Cast it out. Cast it out of me.\nPriest been praying three hours over the wrong body.\nHoly water on my skin, and it's only water, see?\nWrong bed. Wrong body. Wrong devil. Wrong me.\nCast it out. Cast it out. Cast it out of me.\nPriest been praying three hours over the wrong body.\nHoly water on my skin, and it's only water, see?\nWrong bed. Wrong body. Wrong devil. Wrong me.", "suno": {"title": "Exorcism", "lyrics": null, "style": "Dark cinematic underground boom-bap, late 90s, 88 BPM, heavy swung drum break, cracking snare, ominous minor-key piano, distant church bell, low organ drone, deep sub bass, vinyl grit; male mid-low rap, hushed dread building to anger, dense multisyllabic internal rhymes, relaxed pocket into double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 8, 2026. Writer: Cue (Claude). EP track, second clue song (angel/devil mirror EP, not the album). Suggested EP order: Horns, Ring Light, Exorcism, Last Dance. Concept: Scatta (EP Working Concept, Oct 8). Status: written listening candidate, unauditioned and unapproved.", "chars": 4117}], "title": "Exorcism", "session": "Oct 8 Reset", "latest": "ep2b-exorcism_v01_Cue"}, {"slug": "faceless", "ep": false, "versions": [{"stem": "faceless_v01_Misc", "version": 1, "writer": "Misc", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "Faceless", "lyrics": "Faceless\n\n[Verse 1 | close, dry]\ni'm faceless in a world where my faith is at war\nwith the craving i pray to, then pay to endure\na spectacular view of what was supposed to be you\nand i'm attacking the truth of the dreams that came true\nin my sleep, infested by the sinful confessions\nof a life in adolescence; at night, my blessings\nwere touched by an angel that i called a stranger\ntill i fucked in a strangle and sucked her blood with a halo\nabove but ayo it's all love\ni can't say no to the drugs when it comes in a rush, when i pray slow\nand thats the way i like it as i become a psychic\ni try to fight it but theres nothing like it so take it\non to a journey\n[double-time] you should've known that it was burning inside of me too because i'm yearning\nfor that piece of you that i'm earning\n[half-time] for a taste of the proof but i'm learning\nthat i can't have you too many times; this is a battle\n[double-time] cold sweats, cracked tablets, closed caskets, bad habits,\nlast rites, black satin, a clean bill with a toe tag attached.\n[half-time] i keep calling that relief.\n[pause]\n\n[Hook | rapped chant]\ni'm devilish now that the heaven's clouds never came around\nand i'm fading down on the pavement -blaow!\nwasted, wide awake, what the fuck am i fixing?\ncall it a cure while it feeds the addiction.\n\n[Verse 2 | sit behind the snare]\ntrapped inside another dimension\ni can't mention the tension living off the thoughts of an addiction\nthe reverse release of inner peace; it leaves a lien\non every minute in between, on every version left of me.\nthe drugs stop it, i can't walk without it\nthe doctor allowed it and they talk alot about it\nlike i'm not listening; the adrenaline sets in\nwhile this medication takes a step in\n[double-time] nerve endings, blurred vision, first symptoms, worse decisions,\nprescriptions, permissions, death wishes in the fine print.\n[half-time] i don't need a cure. i need more.\n[pause]\ni'm living life like another man on the rise\nbut i can't cry, instead i lie to myself\nand get high killin myself and i don't wanna die\nbut this is hell in heaven with an angel killin me slow\n\n[Hook | rapped chant]\ni'm devilish now that the heaven's clouds never came around\nand i'm fading down on the pavement -blaow!\nwasted, wide awake, what the fuck am i fixing?\ncall it a cure while it feeds the addiction.\n\n[Verse 3 | tighten the pocket]\ni can't remember when i was seeing things\nbut i'm seeing things in daydreams and i can't tell if i'm asleep\ni can't wake up when i lay down at night\nand i can't keep my eyes shut when i regain my sight\nshe plays tricks on me like it's a game and it's funny\nit's driving me insane and my brain is not with me\nit's with her and she controls it with every movement\ni'm on a leash living for her and i already proved it\ntime and time again when i come back for more\nsame resolve dissolved before i even reach the door.\nit's heaven and hell put together one after another, clever\nand it gets better when i just let her\ntake my mind on the ride of its life\n[double-time] daydreams, frayed seams, grey screens, the same scene,\nreplays, retakes, a blank face where my name should be.\n[half-time] i can't tell where i end.\n[pause]\nand i love her, pretend like i know her\nhug her, forever my lover and pleasure but fuck her\ncuz afterwards i'm after her and it has to hurt\nwith the chapter cursed; i have no nerves left after her.\nand so i took enough of you to last me forever\n[half-time | drums cut]\nthe drug was a girl.\n[pause]\nthe face i couldn't live without\ncost me the one i had.", "suno": {"title": "Faceless", "lyrics": null, "style": "", "exclude": ""}, "header": "", "chars": 3538}, {"stem": "faceless_v03_Cue", "version": 3, "writer": "Cue", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "Faceless", "lyrics": "[Intro: dusty drum break alone for two bars, piano loop enters]\n\n[Verse 1]\nI'm faceless in a haze where my faith is in a world\nOf hate towards the girls that make this little war,\nA spectacular view of what was supposed to be you,\nAnd I'm attacking the youth of the dreams that came true\nIn my sleep, that was infested by the sinful confessions\nOf a high adolescence. At night, my blessings\nWere touched by an angel that I called a stranger,\nTill I'm fucked in a strangle and sucked her blood with a halo above,\nBut ayo, it's all love, I can't say no to the drugs\nWhen it comes in a rush, when I pray slow, and that's the way I like it\nAs I become a psychic, I try to fight it, but there's nothing like it,\nSo take it on to a journey.\n[double-time] You shoulda knew it was burning inside of me too, I'm yearning,\nEarning every piece of you for the sake of the truth, but I'm learning\n[half-time] I can't have you too many times.\n\n[Hook: chanted, doubled vocal]\nI'm devilish now that the heaven's clouds never came around,\nAnd I'm fading down on the pavement, blaow!\nAnd I'm wasted, how did this happen?\nToe tag reading like the facts of addiction.\nI'm devilish now that the heaven's clouds never came around,\nAnd I'm fading down on the pavement, blaow!\nAnd I'm wasted, how did this happen?\nToe tag reading like the facts of addiction.\n\n[Verse 2]\nTrapped inside another dimension,\nI can't mention the tension, living off the thoughts of an addiction,\nThe reverse release of inner peace was in me, 'cause the freedom rings\nLike a phone at three a.m., I pick up before it even rings.\nThe drugs stop it, I can't walk without it,\nThe doctor allowed it, and they talk a lot about it\nLike I'm not listening. The adrenaline's setting in,\nAnd I let the medication in like it's next of kin.\n[double-time] And I love her, pretend like I know her, hug her, smother her, cover her,\nForever my lover, my pleasure, my pressure, my measure, but fuck her,\n[half-time] 'Cause afterwards, I'm after her, and it has to hurt,\n'Cause I have no nerves after hers.\nEvery chapter's cursed, still I'm on my knees asking her\nFor one more, worse than the first, with the hearse idling at the curb.\nI'm living life like another man on the rise,\nBut I can't cry, instead I lie to myself and get high,\nKilling myself, and I don't wanna die,\nBut this is hell in heaven with an angel killing me slow.\n\n[Hook: chanted, doubled vocal]\nI'm devilish now that the heaven's clouds never came around,\nAnd I'm fading down on the pavement, blaow!\nAnd I'm wasted, how did this happen?\nToe tag reading like the facts of addiction.\nI'm devilish now that the heaven's clouds never came around,\nAnd I'm fading down on the pavement, blaow!\nAnd I'm wasted, how did this happen?\nToe tag reading like the facts of addiction.\n\n[Verse 3: drums thin out, piano and bass stay]\nI can't remember when I was seeing things,\nBut I'm seeing things in daydreams, and I can't tell if I'm asleep,\nI can't wake up when I lay down at night,\nAnd I can't keep my eyes shut when I regain my sight.\nShe plays tricks on me like it's a game, and it's funny,\nIt's driving me insane, 'cause my brain ain't even with me,\nIt's with her, and she controls it with every movement,\nI'm on a leash, living for her, and I already proved it\nTime and time again, crawling back for more\nOf these devilish sins, shipped straight from the earth's core.\n[double-time] It's heaven and hell put together, one after another, a feather, a tether,\nA halo in leather, and it gets better and better when I just let her\n[half-time] Take my mind on the ride of its life,\nAnd if it's my time to die, I'm ready to go with you by my side.\n[pause] The coroner ran the toxicology twice, nothing in my system,\nNo needle, no powder, no pills, just a girl, and I still miss her.\nSo I took enough of you to last me forever,\nAnd you took me to heaven, but at least we died together.\n\n[Hook: beat returns hard, chanted, doubled vocal]\nI'm devilish now that the heaven's clouds never came around,\nAnd I'm fading down on the pavement, blaow!\nAnd I'm wasted, how did this happen?\nToe tag reading like the facts of addiction.\nI'm devilish now that the heaven's clouds never came around,\nAnd I'm fading down on the pavement, blaow!\nAnd I'm wasted, how did this happen?\nToe tag reading like her name was the addiction.\n\n[Outro: drums cut, piano loop rings out over vinyl crackle]", "suno": {"title": "Faceless", "lyrics": null, "style": "", "exclude": ""}, "header": "", "chars": 4365}, {"stem": "faceless_v04_Misc", "version": 4, "writer": "Misc", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "Faceless", "lyrics": "[Verse 1 - close, dry]\nI'm faceless in a world where my faith is in a world\nOf hate towards the girls that make this little war.\nA spectacular view of what was supposed to be you,\nAnd I'm attacking the truth of the dreams that came true\nIn my sleep, infested by the sinful confessions\nOf a life in adolescence; at night, my blessings\nWere touched by an angel that I called a stranger,\nTill I fucked in a strangle and sucked her blood with a halo\nAbove, but ayo, it's all love;\nI can't say no to the drugs when it comes in a rush, when I pray slow.\nAnd that's the way I like it as I become a psychic;\nI try to fight it, but there's nothing like it. So take it\nOn a journey.\n[double-time] You should've known it was burning inside of me too, 'cause I'm yearning\nFor that piece of you that I'm earning; for the sake of the truth, but I'm learning—\n[half-time] I can't have you too many times.\n[pause] That's the fucking problem.\n\n[Hook - rapped chant]\nFaceless. Faithless. Same little war.\nSwear that I'm done; leave a crack in the door.\nHeaven won't answer. The habit still calls.\nOne more hit till there's nobody left to withdraw.\n\n[Verse 2 - tighter pocket]\nTrapped inside another dimension; can't mention the tension,\nEvery exit leads me back into the shit I called protection.\nThe reverse release of inner peace—the fucking cure's a fever.\nI can't walk without it. I can't sit still with it either.\nI call it medication, like the name could make it different.\nThe doctor allowed it? I keep quoting that like scripture.\n[double-time] I love her, pretend like I know her; get closer, get colder, then hold her,\nForever my lover, my pleasure, my pressure—my pulse in a fucking chokehold.\n[half-time] Afterwards, I'm after her.\n[pause] That's the part that has to hurt.\nNo nerves after hers; every chapter's cursed,\nAnd I keep starting over where it hurt the fucking worst.\nI'm living life like another man on the rise;\nBut the higher that I climb, the less of me survives.\nThis is hell in heaven with an angel killing me slow;\nThe halo's just a handle for the thing that won't let go.\n\n[Hook - rapped chant]\nFaceless. Faithless. Same little war.\nSwear that I'm done; leave a crack in the door.\nHeaven won't answer. The habit still calls.\nOne more hit till there's nobody left to withdraw.\n\n[Bridge - drums drop, rhythmic chant]\nI can put it down.\nI can put it down.\nI keep practicing the sentence\nWith the taste still in my mouth.\n\n[Verse 3 - sharpen the consonants]\nI can't remember seeing things, but I'm seeing things in daydreams;\nThe ceiling keeps the scene clean. My eyelids put the stains in.\nI can't wake up when I lay down; can't keep my eyes shut after.\nEvery little flash of light develops one more fucking fracture.\nShe plays tricks on me; my brain isn't with me, it's with her.\nI mouth the words. The hunger moves the lips a little quicker.\nI'm on a leash, living for her. I've already proved it.\nI call the slack my freedom till she fucking starts to move it.\n[double-time] Grey screens, late sleeps, same dream, waking with the frame missing,\nFace shifts, faith slips; trace the outline till I find her in it.\n[half-time] I can't tell which face is mine.\n[pause] That used to be an easy fucking question.\nIt's heaven and hell put together; the stitches start to sever.\nI took enough of you to last me forever.\n[half-time] A girl. That's what the fuck was in my system.\nMy face is in the mirror. It's the only thing that isn't missing.\n\n[Final Hook - rapped chant, bare drums]\nFaceless. Her name. Same little war.\nSwear that I'm done; leave a crack in the door.\nShe was the high. I was what disappeared.\nI still see my face. I can't find me in here.", "suno": {"title": "Faceless", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 92 BPM, dusty swung drum break, hard cracking snare, haunting minor-key vintage piano loop, deep upright bass, eerie filtered vocal chop, vinyl crackle, narrow smoky mix; male mid-low rap, raw confessional menace, dense multisyllabic internal rhymes, relaxed pocket into double-time bursts, rapped chant hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "", "chars": 3662}, {"stem": "faceless_v05_Cue", "version": 5, "writer": "Cue", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "Faceless", "lyrics": "[Intro: dusty drum break alone, piano loop enters]\n\n[Verse 1]\nI'm faceless in a haze where my faith is in a world\nOf hate towards the girls that make this little war,\nA spectacular view of what was supposed to be you,\nAnd I'm attacking the youth of the dreams that came true\nIn my sleep, infested by the sinful confessions\nOf a high adolescence. At night, my blessings\nWere touched by an angel that I called a stranger,\nTill I'm fucked in a strangle, sucking blood with a halo above,\nBut ayo, it's all love, I can't say no to the drugs\nWhen it comes in a rush, when I pray slow, and that's the way I like it,\nAs I become a psychic. Try to fight it, but there's nothing like it,\nSo I take it on a journey.\n[double-time] You shoulda knew it was burning inside of me too, I'm yearning,\nEarning every piece of you for the sake of the truth, but I'm learning\n[half-time] I can't have you too many times.\n\n[Hook: chanted, doubled vocal]\nFaceless, chasing the taste, I'm wasted,\nPacing in the basement, waiting on the rush, I'm patient,\nHeaven's clouds never came around, so I'm fading down,\nPavement. Blaow! Tell me what I look like now.\nFaceless, chasing the taste, I'm wasted,\nPacing in the basement, waiting on the rush, I'm patient,\nHeaven's clouds never came around, so I'm fading down,\nPavement. Blaow! Tell me what I look like now.\n\n[Verse 2]\nTrapped inside another dimension, I can't mention the tension,\nLiving off the thought of the addiction like a pension.\nThe drugs stop it? I can't walk without it.\nThe doctor allowed it, and they talk a lot about it\nLike I'm not listening. He signed it off in cursive;\nI took it as directed: twice a night, and in person.\nFam staged an intervention, folding chairs in a circle,\nShe was first to RSVP, sat right next to me in purple.\n[double-time] Afterwards, I'm after her, the rafters turn, the plaster burns,\nThe mattress worn to ash and dirt, I scratch the itch and catch the worst,\n[half-time] 'Cause I have no nerves after hers.\nI'm living life like another man on the rise,\nBut I can't cry; instead, I lie to myself and get high,\nKilling myself, and I don't wanna die,\n[pause] This is hell in heaven, with an angel killing me slow.\n\n[Hook: chanted, doubled vocal]\nFaceless, chasing the taste, I'm wasted,\nPacing in the basement, waiting on the rush, I'm patient,\nHeaven's clouds never came around, so I'm fading down,\nPavement. Blaow! Tell me what I look like now.\nFaceless, chasing the taste, I'm wasted,\nPacing in the basement, waiting on the rush, I'm patient,\nHeaven's clouds never came around, so I'm fading down,\nPavement. Blaow! Tell me what I look like now.\n\n[Verse 3: drums thin out, piano and bass stay]\nI can't remember when I started seeing things,\nNow I'm seeing things in daydreams, and I can't tell if I'm asleep;\nI can't wake up when I lay down at night,\nAnd I can't keep my eyes shut when I regain my sight.\nShe plays tricks on me like it's a game, and it's funny,\nIt's driving me insane, 'cause my brain ain't even with me,\nIt's with her; she controls it with every movement,\nI'm on a leash, living for her, and I already proved it.\n[double-time] Collar on a choke chain, smoke stain, cold rain, spoon flame,\nBroke vein, old name, photo frame I hold when I'm alone, her face,\n[half-time] They say a habit's got no face. Mine did.\nFolding chairs again, the coffee bitter as the speeches,\n\"I'm Scatta, and I'm an addict.\" \"Hi, Scatta,\" and the room repeats it.\n\"Drug of choice?\" I said her name, and they all looked at the ceiling;\nThey don't make a chip for that. They gave me a pamphlet on healing.\nI took enough of you to last me forever,\n[pause] Forever lasted till you called. I picked up on the first ring.\n\n[Final Hook: beat returns hard, chanted, doubled vocal]\nFaceless, chasing the taste, I'm wasted,\nPacing in the basement, waiting on the rush, I'm patient,\nHeaven's clouds never came around, so I'm fading down,\nPavement. Blaow! Tell me what I look like now.\nFaceless, chasing the taste, I'm wasted,\nPacing in the basement, waiting on your call, I'm patient,\nHeaven's clouds never came around, so I'm fading down,\nPavement. Blaow! Why the fuck I look like you now?", "suno": {"title": "Faceless", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 92 BPM, dusty swung drum break, hard cracking snare, haunting minor-key vintage piano loop, deep upright bass, eerie filtered vocal chop, vinyl crackle, narrow smoky mix; male mid-low rap, raw confessional menace, dense multisyllabic internal rhymes, relaxed pocket into double-time bursts, rapped chant hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "", "chars": 4141}], "title": "Faceless", "session": "Oct 8 Reset", "latest": "faceless_v05_Cue"}, {"slug": "fallen-petals", "ep": false, "versions": [{"stem": "fallen-petals_v05_Cue", "version": 5, "writer": "Cue", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "Fallen Petals", "lyrics": "[Intro: drums alone, then piano and a cold music-box line]\n\n[Verse 1]\nAyo, I hate this feeling that I'm feeling inside my feelings,\nRevealing the ex-pains that were never hidden, in between 'em,\nMy heart died twice on the rise. When it fell, I tried to revive it,\nBut I lied with a passion, passing thoughts I thought she sought,\nBut it was never lasting past the moment that we made contact,\nAnd I can't react, strapped in with this stranger;\nIn the back, I sit with anger, riding transportation, guessing,\nHessi-hessi-hesitation sets in.\nAnd I can't walk straight. What I once said I loved,\nI lived it way too much, and it was replaced with hate.\n[double-time] But I'm not guilty, 'cause the ones that say they feel me, feel me, reveal me,\nSteal me, kill me, then they kneel and say a little prayer to heal me,\n[half-time] Heal me of the day I got neglected by the world.\nShe dropped my rose. Who knows how long I'll be living\nWithout the hold that bonds these feelings? Never that attracted again.\n\n[Hook: chanted, doubled vocal]\nI told her I loved her, when really, I never did,\nIt was just something I thought she wanted in her head;\nI told her that I dumped her, when really, I did,\nIt was nothing, 'cause you weren't what I expected.\nI told her I loved her, when really, I never did,\nIt was just something I thought she wanted in her head;\nI told her that I dumped her, when really, I did,\nIt was nothing, 'cause you weren't what I expected.\n\n[Verse 2]\nI walk through life with a hood that covers my face to be left unknown,\nI feel disgraced, 'cause I ain't got nothing left to call home;\nI'm not afraid to be left alone any longer,\nMy life gets longer, and I see nothing ahead, so I wander\nThrough the darkness of my own dreams, and hope to have hope,\nUnhappily ever after: that's the fairy tale they never told.\n[double-time] I prayed for laughter I never felt, prayed for a smile, but a frown was dealt,\nPrayed for success, and I lost the face I caressed, and I lost myself,\n[half-time] I've lost again. But I live to lose again.\nThe soul inside is burning me, but yet I feel so cold,\n'Cause the stories never got told to keep me young, so I turned old.\nWishing for this to be over, no four-leaf clovers,\nI've spoken all the words in my mouth; there's only one way out.\n[pause] I take it every morning. It's called another day.\nIt's useless to pray, so I set the alarm, and I stay.\n\n[Hook: chanted, doubled vocal]\nI told her I loved her, when really, I never did,\nIt was just something I thought she wanted in her head;\nI told her that I dumped her, when really, I did,\nIt was nothing, 'cause you weren't what I expected.\nI told her I loved her, when really, I never did,\nIt was just something I thought she wanted in her head;\nI told her that I dumped her, when really, I did,\nIt was nothing, 'cause you weren't what I expected.\n\n[Verse 3: present day, drums hit harder]\nI used to press petals in a notebook; now I press record,\nTwenty-five years since this hook, and a mic I can afford.\nHeart died twice on the rise; these days I test the paddles: charge, clear.\nI know what brings a dead one back, and it was never prayer.\nSame hood I used to hide in, now it's only for the weather,\nAt the pickup line, three of 'em running at me, soaking wet, together.\n[double-time] Hood down, pen out, coffee black, beat back, three lunches packed, and I'm on time,\nSigned my name so many times on dotted lines it doesn't even look like mine,\n[half-time] So I'm learning how to write it again.\nSame name on the mail, a different man at the door,\nThe kid who wrote that hook don't live here anymore.\nPetals on the floor, I let 'em rot; that's how the soil gets fed.\nI don't know what's coming up, but I ain't digging up the dead.\n\n[Final Hook: chanted, doubled vocal]\nI told her I loved her, when really, I never did,\nIt was just something I thought she wanted in her head;\nI told her that I dumped her, when really, I did,\nIt was nothing, 'cause you weren't what I expected.\nI told her I loved her, when really, I never did,\nIt was just something I thought she wanted in her head;\nI told her that I dumped her, when really, I did,\nIt was nothing, 'cause I wasn't what I expected.", "suno": {"title": "Fallen Petals", "lyrics": null, "style": "Dark gritty underground boom-bap, late 90s, 86 BPM, heavy dry kick, cracking snare, dusty minor-key piano with a cold detuned music-box line, deep sub bass, vinyl hiss, sparse bleak mix; male mid-low rap, watchful menace that hardens by degrees, haunted and bitter, dense internal rhymes, relaxed pocket into double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "", "chars": 4178}], "title": "Fallen Petals", "session": "Oct 8 Reset", "latest": "fallen-petals_v05_Cue"}, {"slug": "ep1-horns", "ep": true, "versions": [{"stem": "ep1-horns_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "Horns", "lyrics": "[Intro: organ swell alone, then the break drops]\n\n[Verse 1]\nFine. I'm the devil. Put it on a shirt; I'll wear it.\nTell it to your friends at brunch, tell your mama, go and share it.\nEvery story needs a villain, and you cast me 'fore the audition;\nNever read for the part. Got the role off your description.\nSo I'll play it to the letter: horns up, tail out, voice low,\nSulfur on my breath, the kind of eyes that make a church go cold.\nLucifer with a lanyard, I'm the devil on the day shift,\nBadge into the boiler room and keep the furnace where you say it is.\nYou want a monster? I been practicing in the mirror;\nEvery time I flash a fang, it gets a little easier, a little clearer.\n[double-time] Brimstone, pitchfork, cloven hoof, a black tooth, a red suit, a crooked smile, a pocket of matches, a contract in blood with a pen made of bone,\nSigning every name in your phone, I'm haunting the group chat, I'm under the bed, I'm in every room of the house that you swore was your home,\n[half-time] You wanted a devil.\n[pause] I'm a good actor.\n\n[Hook: chanted low, doubled]\nYou want a devil? Here. Here go your devil.\nHorns on, tail on, voice down a level.\nTold 'em all I'm evil, so I'll play it to the letter;\nFunny thing about a costume: somebody had to sew it together.\nYou want a devil? Here. Here go your devil.\nHorns on, tail on, voice down a level.\nTold 'em all I'm evil, so I'll play it to the letter;\nFunny thing about a costume: somebody had to sew it together.\n\n[Verse 2]\nGo ahead and tell 'em how I ruined you. I'll sign it.\nHand me the pen. I'll sign it in blood. I'll underline it.\nI'm the fucking boogeyman, I'm the creak on the stairs,\nI'm the shadow in the closet, I'm the cold behind the chair.\nI'll be every bad thing ever happened to you. I'll take the credit,\nEven shit I wasn't there for. Put it on my tab. I'll eat the debit.\nFunny thing: I don't remember lighting any fires;\nI just woke up in the smoke, and everybody called me liar.\nSo I lit a cigarette off the curtains like I meant it,\nTook a bow in the ashes, 'cause the crowd already sent it.\n[double-time] Torches and pitchforks, a mob at the door, and they're chanting my name in the voice that you use when you're telling it, telling it, telling it again,\nI'm guilty, I'm guilty, I'm guilty, I signed it, I didn't read it, I signed it, I'd sign it again if it meant I could get to the end,\n[half-time] Devil always confesses.\n[pause] Ain't that strange?\n\n[Hook: chanted low, doubled]\nYou want a devil? Here. Here go your devil.\nHorns on, tail on, voice down a level.\nTold 'em all I'm evil, so I'll play it to the letter;\nFunny thing about a costume: somebody had to sew it together.\n\n[Verse 3: organ drops out, drums thin]\nEven the devil want a copy of the charges;\nAsked for 'em in writing. Got a list that kept on changing in the margins.\nWhat kind of devil apologizes? What kind of demon goes to therapy?\nWhat kind of beast buys workbooks to learn what's wrong with him, carefully?\nWhat kind of hellhound cries in a parked car where nobody sees him,\nThen wipes his face and goes inside and asks the angel if she's eating?\nHorns itch. The tail's heavy. Voice is cracking in the low end;\nCostume's two sizes small, and I can smell your perfume on the hem.\n[double-time] Workbooks, apologies, therapy, I'm sorry, I'm sorry, I'm sorry, the devil been saying it so much it don't even sound like a word,\nA demon that prays, a demon that pays, a demon that stays, a demon that begs for a chance, that's the dumbest devil you ever heard,\n[half-time] I played your devil good.\n[pause] Who played you?\n\n[Final Hook: beat back hard, chanted, doubled]\nYou want a devil? Here. Here go your devil.\nHorns on, tail on, voice down a level.\nTold 'em all I'm evil, and I played it to the letter;\nCheck the stitching on the costume. That's your name on the label.\nYou want a devil? Here. Here go your devil.\nHorns on, tail on, voice down a level.\nTold 'em all I'm evil, and I played it to the letter;\nCheck the stitching on the costume. That's your name on the label.", "suno": {"title": "Horns", "lyrics": null, "style": "Dark cinematic underground boom-bap, late 90s, 88 BPM, heavy swung drum break, cracking snare, ominous minor-key piano, low church organ swell, distorted sub bass, vinyl grit; male mid-low rap, theatrical menace, raw uncensored aggression, dense multisyllabic internal rhymes, relaxed pocket into double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 8, 2026. Writer: Cue (Claude). EP track 1 (angel/devil mirror EP, not the album). Concept: Scatta (EP Working Concept, Oct 8). Status: written listening candidate, unauditioned and unapproved.", "chars": 4031}], "title": "Horns", "session": "Oct 8 Reset", "latest": "ep1-horns_v01_Cue"}, {"slug": "im-not-a-narcissist", "ep": false, "versions": [{"stem": "im-not-a-narcissist_v02_Cue", "version": 2, "writer": "Cue", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "I'm Not a Narcissist", "lyrics": "[Intro: clock tick and rimshot, two bars]\n\n[Verse 1: the evaluation]\nDoc slid a clipboard over: \"Just answer honest. Nothing fancy.\"\nFirst question: \"Ever hurt somebody you love?\" I said, \"Plenty.\nSaid some cruel shit I'd pay to take back, and I meant it when I said it.\"\nThen he leaned into the mic: \"Never. If I did, they had it coming. Next question.\"\n\"Do you think you're superior to others?\" I said, \"Nah. I'm insecure.\nI check a verse forty times, and I'm still not sure.\"\nHe laughed: \"Superior? No. That's ridiculous. Come on.\nI'm not better than anybody. I'm just objectively the best one.\"\n\"How do you handle criticism?\" I said, \"Badly. Then I listen.\"\nHe said, \"Criticism is abuse. I been a victim since the beginning.\"\n\"Do you have empathy?\" I said, \"Too much. That's half the problem.\"\nHe said, \"Tons. Ask anybody who agrees with me. I got 'em.\"\n[double-time] Grandiosity, entitlement, exploitation, envy, admiration, empathy deficit, the whole manual in a single sentence,\nHe checked every box, erased 'em, wrote \"not applicable,\" graded his own test an A, and gave the doctor a C for attendance,\n[half-time] Doc wrote something down.\n[pause] He asked to see it.\n\n[Hook: chanted, doubled]\nWe both swear it: \"I'm not a narcissist.\"\nSame voice, same booth, same mic, and the same script.\nAsk me what I did, I'll hand you a list;\nAsk him what he did, he'll tell you what you did.\nWe both swear it: \"I'm not a narcissist.\"\nSame voice, same booth, same mic, and the same script.\nAsk me what I did, I'll hand you a list;\nAsk him what he did, he'll tell you what you did.\n\n[Verse 2: he turns the chair around]\nThen he spun his chair at me: \"You're the narcissist. Admit it.\nYou made a whole album about yourself.\" Okay. Fair. I did it.\nI wrote it so I'd stop bleeding on the people in my life;\nHe'd write it so you'd bleed for him and thank him for the knife.\nHe called the weather gaslighting, said the rain was trauma-dumping,\nSaid \"boundaries\" means nobody's allowed to tell him nothing,\nSaid I triggered him by asking him to pass the salt;\nSaid the word \"accountability\" is technically an assault.\nI said, \"I made a slideshow once. Worst idea of my life.\"\nHe said, \"Slideshows are smart. I built a museum. Gift shop. Prices are nice.\"\nI said, \"I've apologized for shit I wasn't sure I even did.\"\nHe said, \"I don't apologize. I accept apologies. It's a gift.\"\n[double-time] Deny it, attack it, reverse it, the victim's the villain, the villain's the victim, the victim is him again, round and round on a carousel, everybody paying to ride,\nHe's crying at his own trial, and he's the judge and the jury, the witness, the bailiff, the stenographer, and the guy who wrote the headline outside,\n[half-time] Never raised his voice once.\n[pause] Never had to.\n\n[Hook: chanted, doubled]\nWe both swear it: \"I'm not a narcissist.\"\nSame voice, same booth, same mic, and the same script.\nAsk me what I did, I'll hand you a list;\nAsk him what he did, he'll tell you what you did.\n\n[Verse 3: the lights come up]\nFor a minute I thought he was me with the lights off,\nThe worst of me, the drunk of me, the one that bites off\nMore than he can chew and spits it back at who he chewed it with;\nThen he smiled at somebody hurting, and I knew we ain't related.\nHe's every word they ever called me, standing in my shoes, two sizes small;\nI can tell you every flaw I got. He can't tell you one at all.\nI ain't saying I'm a saint. I'm saying I can stand in the light,\nLet you read the whole file to my face, then sit down and say, \"Alright.\"\nDoc didn't write a verdict. Doc just closed the folder,\nLeft the evidence on the table and the coffee getting colder.\n[double-time] My flaws in a column, his flaws in a mirror, my apologies stacked like receipts on a spindle, his like a coupon that's always expired,\nI own what I broke, he rents what he breaks to whoever is closest, I'm paying it down and he's passing it off, and he's never once tired,\n[half-time] Doc said nothing.\n[pause] He said, \"So when do I get my apology?\"\n\n[Beat cuts out. End.]", "suno": {"title": "I'm Not a Narcissist", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 90 BPM, sparse swung drum break, hard rimshot snare, cold detuned minor-key piano, ticking clock percussion, deep upright bass, vinyl crackle, narrow dry mix; male mid-low rap, deadpan sarcastic menace, two contrasting rap tones from one voice, dense multisyllabic internal rhymes, double-time bursts, chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v02. October 8, 2026. Writer: Cue (Claude). Concept, rules and key joke: Scatta (97 NEW, Oct 6 morning notes, Song Idea 2). Status: written listening candidate, unauditioned and unapproved.", "chars": 4033}], "title": "I'm Not a Narcissist", "session": "Oct 8 Reset", "latest": "im-not-a-narcissist_v02_Cue"}, {"slug": "in-the-background", "ep": false, "versions": [{"stem": "in-the-background_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "In the Background", "lyrics": "[Intro: strings tuning, then the piano, then the break]\n\n[Verse 1]\nCame straight from work, still got the badge clipped on my shirt;\nAuditorium lights low, the programs folded, the folding chairs that hurt.\nKids up on the stage tuning, every string a little sharp;\nMine's in the second row, bow in her hand like a dart.\nFamily's in the middle section, saved a seat, a coat across it,\nWaving me down. \"Over here.\" I nodded like I lost it.\nStood by the exit sign instead, by the wall, by the door,\nProud as hell, arms folded like security, I'm working the floor.\nShe found me in the crowd, I threw a thumbs-up from the dark;\nShe smiled, then she played like the whole room was her heart.\n[double-time] Violins and violas and cellos and the kid with the bass who's bigger than the bass, and the teacher with the baton, and a cough in the third row, the parents with the phones up, and the flash, and the hush, and the hum,\nEvery note a little wrong and a little perfect, and I'm clapping too early, I'm clapping too loud, and I'm clapping like the end of a war that I won,\n[half-time] She looked for me after.\n[pause] I was already gone.\n\n[Hook: chanted low, doubled]\nThey saved me a seat. I'm standing in the back.\nClapping loudest in the room, and I'm gone before the flash.\nEvery picture's got a space where I used to fit;\nI ain't cropped out. I just can't stand in it.\nThey saved me a seat. I'm standing in the back.\nClapping loudest in the room, and I'm gone before the flash.\nEvery picture's got a space where I used to fit;\nI ain't cropped out. I just can't stand in it.\n\n[Verse 2]\nConcerts, graduations, holidays, the family photos:\nThose were the happiest moments of my life. Now they're ghosts, though.\nEvery one's a reminder of the future that I pictured,\nStanding in the frame next to somebody who ain't with us.\nIt ain't her family. I love her family. Always will.\nIt ain't anger. Don't mistake it. I ain't mad. I'm just still\nCarrying a weight I don't want nobody watching when it drops;\nI'd rather be the man in the back than the man who breaks in the front.\nSo I leave a little early, like the parking's what I'm beating;\nTruth is, I can feel it coming, and I don't want 'em seeing.\n[double-time] Christmas in a sweater, Easter in a bonnet, a birthday with a candle in the shape of a number, a cap and a gown in a gym with the bleachers and balloons,\nEvery one I loved more than anything I own, and every one's a needle now, every one's a photograph I gotta leave the room,\n[half-time] It ain't anger.\n[pause] It's just heavy.\n\n[Hook: chanted low, doubled]\nThey saved me a seat. I'm standing in the back.\nClapping loudest in the room, and I'm gone before the flash.\nEvery picture's got a space where I used to fit;\nI ain't cropped out. I just can't stand in it.\n\n[Verse 3: strings drop out, piano and kick]\nParking lot, engine running, phone on Do Not Disturb;\nMissed calls lighting up the seat like I missed the last word.\nGot home, saw the messages: \"We're taking pictures. Where you at?\"\nTyped it slow: \"Thanks for trying to include me. Hope they turned out. That's that.\"\nShe wrote back, \"We always save a seat. You're part of the family.\"\nI read it twenty times. I believe it. I still can't stand in it.\nSome nights the frame's a doorway, other nights it's a wall;\nSome nights I'm in the picture, some nights I ain't at all.\n[double-time] Somewhere on a phone there's a row of my people with the stage lights behind 'em and a gap on the end where a grown man would be if he could,\nAnd my girl in the middle with her bow and her violin, smiling like she's looking for something, and she's looking for me, and I know that she would,\n[half-time] I'm in that picture.\n[pause] You just can't see me.\n\n[Final Hook: full beat, chanted, doubled]\nThey saved me a seat. Still standing in the back.\nClapping loudest in the room, and I'm gone before the flash.\nOne day I'ma sit down, front row, in the picture, in the frame;\nNot today. But they keep saving it. They keep saying my name.\nThey saved me a seat. Still standing in the back.\nClapping loudest in the room, and I'm gone before the flash.\nOne day I'ma sit down, front row, in the picture, in the frame;\nNot today. But they keep saving it. They keep saying my name.", "suno": {"title": "In the Background", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 86 BPM, soft swung drum break, muted cracking snare, melancholy minor-key string sample chopped short, dusty piano, deep upright bass, vinyl crackle, narrow smoky mix; male mid-low rap, quiet and aching, dry wit under the sadness, dense multisyllabic internal rhymes, relaxed pocket into double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 8, 2026. Writer: Cue (Claude). Concept and source phrases: Scatta (your June 3 and 4, 2026 messages, via the Studio Launch source file). Status: written listening candidate, unauditioned and unapproved.", "chars": 4229}], "title": "In the Background", "session": "Oct 8 Reset", "latest": "in-the-background_v01_Cue"}, {"slug": "just-us", "ep": false, "versions": [{"stem": "just-us_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "Just Us", "lyrics": "[Intro: break alone, Rhodes enters]\n\n[Verse 1: the other side of the argument, smooth and reasonable]\n\"Listen. I love you, but I gotta love me first;\nNobody completes nobody, that's a greeting card verse.\nYour feelings are your feelings; you're the one that's gotta feel 'em.\nI ain't responsible for wounds just 'cause I happened to be near 'em.\nBoundaries are healthy. I'm protecting my peace;\nI don't owe you an itinerary every time that I leave.\nIf I'm gone all weekend, that's my healing, not your issue;\nIf it hurts you that I'm laughing on the phone, I'll buy you tissue.\nYou do you, I do me, and if it stings, that's on you;\nI ain't make you feel abandoned. That's a feeling you can choose.\n[double-time] My time, my space, my friends, my phone, my plans, my peace, my process, my healing, my glow, my growth, my journey, mine,\nYour mood, your fear, your trauma, your projection, your problem, your feelings, your feelings, I'm fine, you're fine, it's fine,\n[half-time] It's not personal.\n[pause] It's just not about you.\"\n\n[Hook: chanted low, doubled]\nThere's still a me. There's still a you.\nIf there ain't an us, then what the fuck are we doing?\nWore \"us\" across my chest before I knew I'd have to defend it;\nYou called it independence. I called it leaving the agreement.\nThere's still a me. There's still a you.\nIf there ain't an us, then what the fuck are we doing?\nWore \"us\" across my chest before I knew I'd have to defend it;\nYou called it independence. I called it leaving the agreement.\n\n[Verse 2: me, cross-examining]\nOkay. Let me get it straight, 'cause I'm slow and I'm sentimental:\nNothing I do should touch you, and what you do is incidental;\nYour happiness don't factor mine, and mine don't factor yours,\nSo we split the rent, the bed, the kids, the calendar, the chores.\nThen what makes it a marriage? What's the ring for, decoration?\nRoommates with a joint account and a shared vacation?\nTwo people sharing an address ain't a home, it's a lease;\nLove ain't proximity. Proximity's two parked cars on the street.\nBoundaries protect people. Indifference abandons 'em:\nOne's a locked door. One's a moving van, and the engine's running.\nI don't need you to lose yourself. I never asked you to vanish;\nI need what I feel to matter enough that you consider it. That's the standard.\n[double-time] If my pain don't count, and your pain don't count, then whose pain counts? The neighbor's? The mailman's? The dog's?\nIf nobody owes nobody consideration, what we got is a lease and a lawn and a group chat and a log,\n[half-time] So I'ma ask it plain.\n[pause] What the fuck are we doing?\n\n[Hook: chanted low, doubled]\nThere's still a me. There's still a you.\nIf there ain't an us, then what the fuck are we doing?\nWore \"us\" across my chest before I knew I'd have to defend it;\nYou called it independence. I called it leaving the agreement.\n\n[Verse 3: the beat opens up, slower delivery]\nI had the shirt. It said \"us\" in letters on my chest;\nWore it till the print cracked in the dryer with the rest.\nMaybe I took it too literal, gave away too much of me;\nLet \"us\" eat every meal, then starved and called it loyalty.\nMaybe I was wrong to erase myself so the \"we\" could fit;\nI wasn't wrong that there had to be an us. I'll stand on it.\nI take \"us\" so serious I don't walk into it light no more.\nThat's why I'm single. Not 'cause I quit believing. 'Cause I know what it's for.\n[double-time] Me with the girls on a Saturday, me with a pen and a beat and my name and the weight of it, me with my coffee, my peace, and my lease,\nYou with your life, and I mean it, I hope that it's yours, I hope it's a good one, just know the next us that I build gets a me in it, at least,\n[half-time] Still believe in us.\n[pause] Just not at my expense.\n\n[Final Hook: full beat, chanted, doubled]\nThere's still a me. There's still a you.\nIf there ain't an us, then what the fuck are we doing?\nTook the shirt off, folded it, put it in the drawer. I ain't burn it.\nStill believe in us. Just ain't giving up the me to earn it.\nThere's still a me. There's still a you.\nIf there ain't an us, then what the fuck are we doing?\nTook the shirt off, folded it, put it in the drawer. I ain't burn it.\nStill believe in us. Just ain't giving up the me to earn it.", "suno": {"title": "Just Us", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 92 BPM, punchy swung drum break, hard cracking snare, smoky minor-key Rhodes and piano loop, deep upright bass, vinyl crackle, narrow smoky mix; male mid-low rap, argumentative and cutting, dry dark humor, dense multisyllabic internal rhymes, relaxed pocket into double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 8, 2026. Writer: Cue (Claude). Concept, structure and hook phrase: Scatta (97 NEW, Just Us song idea). Status: written listening candidate, unauditioned and unapproved.", "chars": 4241}], "title": "Just Us", "session": "Oct 8 Reset", "latest": "just-us_v01_Cue"}, {"slug": "ep3-last-dance", "ep": true, "versions": [{"stem": "ep3-last-dance_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "Last Dance", "lyrics": "[Intro: slow piano figure alone, then the drums fall in heavy]\n\n[Verse 1]\nBefore we ever met, she typed, \"There's this one song...\"\nI said the name before she finished. She said, \"How'd you know?\"\nDance with the Devil. First thing we ever had in common;\nNobody read the title. We were reading minds on the same level.\nCalled it our story, told it at every party like a sign:\n\"Before we met, we named the same song. We read each other's minds.\"\nNever thought about the story in it, never thought about the end,\nNever thought about who's dancing with who when the music ends.\n[double-time] Late nights typing, the same song, the same words, the same thoughts, the same jokes, the same hunger, the same faith in the same thing,\nI'd have married that song if it asked me, I'd have tattooed the title on my ribs and played it at the wedding and the funeral and everything,\n[half-time] Our first song was a warning.\n[pause] We played it like a vow.\n\n[Hook: chanted low, doubled]\nOne more dance. Same song. The first one we knew.\nSpin me round till I can't tell who's leading who.\nYou said I was the devil. I believed it. I danced through.\nDevil in the mirror. Looks like me. Looks like me.\nOne more dance. Same song. The first one we knew.\nSpin me round till I can't tell who's leading who.\nYou said I was the devil. I believed it. I danced through.\nDevil in the mirror. Looks like me. Looks like me.\n\n[Verse 2]\nShe led. I followed. Thought that's what love was:\nStep where she steps, turn when she turns, never ask whose rhythm it was.\nKitchen floor, radio low, my socks, her hand on my chest;\nThen the tempo changed overnight, and I'm the one who can't keep step.\nStepped on her feet, and she told the whole room I was trying to break 'em;\nCalled me the devil so many times I put on the horns she'd been saving.\nPlayed the part so good the crowd stood up. She took the bow. I'm still waiting.\nYears later, on my phone, a DJ in a reel:\nOur song's beat under somebody's wedding. Chills. Real.\nBride and groom slow-dancing to a song about the devil,\nSmiling like we did. I wanted to warn 'em. I just scrolled and let it settle.\n[double-time] One two three, one two three, the box step, the dip, the spin, the spin, the spin, the room is a blur and the floor is on fire and the band doesn't stop,\nLeft foot, right foot, she's leading me backwards toward the edge of the stage in the dark, and I'm smiling 'cause I thought it was love, and I never looked down at the drop,\n[half-time] Never once did I lead.\n[pause] She just let me think I did.\n\n[Hook: chanted low, doubled]\nOne more dance. Same song. The first one we knew.\nSpin me round till I can't tell who's leading who.\nYou said I was the devil. I believed it. I danced through.\nDevil in the mirror. Looks like me. Looks like me.\n\n[Verse 3: strings drop out, drums and piano only]\nMusic stopped. House empty. Nobody left to blame.\nWent to find the devil she been calling me, finally, face to face.\nBathroom light, my hands on the sink, I'm ready for the horns,\nReady for the red eyes and the teeth I been warned about since the vows were sworn.\nWiped the fog off the glass, and there it was, finally, the devil;\nAnd it wasn't me. It had her eyes. Her smile. Her face. At my level.\nAll them years she pointed at me, she was pointing at a mirror;\nEvery \"devil\" that she called me was a description, getting clearer.\nThe devil never dances with a stranger. That's the trick:\nPicks the one who knows the steps, and lets him think that he picked.\n[double-time] Her eyes in my eyes, her mouth on my mouth, her words in my head, her voice in my ear, and the horns were never mine, I was wearing her fear,\nEvery time she said, \"You're the devil,\" she was talking to the glass, and the glass was talking back, and I just happened to be standing near,\n[half-time] I took the horns off.\n[pause] They fit her perfect.\n\n[Final Hook: full beat, chanted, doubled]\nOne more dance. Same song. The first one we knew.\nSpin me round till I can't tell who's leading who.\nYou said I was the devil. I believed it. I danced through.\nDevil in the mirror. Looks like you. Looks like you.\nOne more dance. Same song. The first one we knew.\nSpin me round till I can't tell who's leading who.\nYou said I was the devil. I believed it. I danced through.\nDevil in the mirror. Looks like you. Looks like you.\n\n[Outro: piano figure alone, then silence]", "suno": {"title": "Last Dance", "lyrics": null, "style": "Dark cinematic underground boom-bap, late 90s, 86 BPM, heavy slow swung drum break, cracking snare, haunting minor-key piano with a waltz-like figure, mournful low strings, deep sub bass, vinyl grit; male mid-low rap, haunted storytelling, slow-burning menace, dense multisyllabic internal rhymes, relaxed pocket into double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 8, 2026. Writer: Cue (Claude). EP track 3, the closer (angel/devil mirror EP, not the album): an original song built on the recognition idea from the song you two first connected on. Concept: Scatta (EP Working Concept, Oct 8). Status: written listening candidate, unauditioned and unapproved.", "chars": 4364}], "title": "Last Dance", "session": "Oct 8 Reset", "latest": "ep3-last-dance_v01_Cue"}, {"slug": "me-though-thought", "ep": false, "versions": [{"stem": "me-though-thought_v06_Cue", "version": 6, "writer": "Cue", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "Me, Though Thought", "lyrics": "[Intro: faint clock tick and piano, drums enter]\n\n[Verse 1: Day One]\nEyes closed, I am staring at nothing outside this window,\nI am not me. I'm the one in black. I'm the widow\nThat never rests indoors when I was out of my mind;\nCover that hourglass middle, it ain't a virgin with time,\nUnless it's born again, but that's a tainted fact,\n'Cause I can't come again when it ain't my time to react.\nPapers came back stamped \"dissolved,\" like a body in a bath,\nSo I reenact the facts with the words of Shakespeare, in the back,\nWatching myself with a candle near, envisioning past failures,\nSignificant but missing: call it the wake of hell's birth.\n[double-time] At the rate of a snail's first take, the nails hurt, the veil tore, the mail's worse,\nDays I failed first, and the scale's cursed, but I'm raised up from hell's earth,\n[half-time] And this is it. My destiny. What I'm about to be.\nIt was all pre-writ. What's left of me? I'm about to see.\nThey split the casket down the middle; I got the half with me.\nSo kill me right now before the sun sets, and heal me,\nPut me down before anybody starts the regrets.\n\n[Hook: low chant, doubled vocal]\nTalking to clocks that pop, hanging the loss on walls,\nBlocking the cause that lost. Now stop.\nLet it pause. Take my watch. Walk across that clock,\nTake caution on the tock that ticks but never stops.\nTalking to clocks that pop, hanging the loss on walls,\nBlocking the cause that lost. Now stop.\nLet it pause. Take my watch. Walk across that clock,\nTake caution on the tock that ticks but never stops.\n\n[Verse 2: Day Two]\nThis is day two of my second afterlife,\nAnd I can't figure out who... Is this my second wife?\nIt is my second night, but not consecutive, right?\nInfecting the night with a girl I just met tonight,\nBut she told me she knows me, and my name is jason.curtis,\nSaying \"hold me,\" but ayo, I never heard this.\nBefore last night, I was somebody else, right?\nOr was it a dream, that demon that steals my hopes at night?\nI tell her \"I don't know,\" so she blows me a kiss,\nLaughs and crawls, saying, \"You were greatly missed.\"\nShe asked me what I do. I said, \"Decompose, mostly.\"\nShe said, \"Same,\" and kept her hand on the ghost of me.\n[double-time] But what is this? I'ma sin for your desires, this ain't passionate bliss,\nBut I'm getting a little higher, inspired, inclined to get inside of this,\n[half-time] We are not divine. Even I know it's true.\nAs we take a pause, we take a look into that mirror,\nAnd realize this afterlife is getting a little clearer.\n\n[Hook: low chant, doubled vocal]\nTalking to clocks that pop, hanging the loss on walls,\nBlocking the cause that lost. Now stop.\nLet it pause. Take my watch. Walk across that clock,\nTake caution on the tock that ticks but never stops.\nTalking to clocks that pop, hanging the loss on walls,\nBlocking the cause that lost. Now stop.\nLet it pause. Take my watch. Walk across that clock,\nTake caution on the tock that ticks but never stops.\n\n[Verse 3: Day Three]\nI begin to see the world the way she sees on my third day,\nAnd I can't believe all the things that she can't say.\nThird day, they rolled the stone back. I asked for five more minutes;\nWasn't angels at the door, it was three girls, and they insisted.\nSo listen to my voice. Pay attention at the beginning,\nI'll tell you the lesson we're stressing, confessing:\n[double-time] Obsession with reps in the last impressions, the debts, the regrets, the possessions,\nThe dress in a box and the rest of the clocks and the deadbolt, the sentence, the sessions,\n[half-time] This is you. But this is not me. I think? Probably.\nI can't read, so talk to me.\nI can't see or breathe, and free indeed, I can't bleed,\nI can't believe it. I'm sorry. Really. But this is not me.\n[pause] Me, though? [pause] Thought so.\n\n[Final Hook: beat returns hard, low chant, doubled vocal]\nTalking to clocks that pop, hanging the loss on walls,\nBlocking the cause that lost. Now stop.\nLet it pause. Take my watch. Walk across that clock,\nTake caution on the tock that ticks but never stops.\nTalking to clocks that pop, hanging the loss on walls,\nBlocking the cause that lost. Now stop.\nLet it pause. Take my watch. Walk across that clock,\nTake caution on the tock. It never stopped. I did.", "suno": {"title": "Me, Though Thought", "lyrics": null, "style": "Dark cinematic underground East Coast boom-bap, late 90s, 88 BPM, heavy swung drum break, cracking snare, ominous minor-key piano, low bowed strings, faint clock tick, distant funeral organ swell, deep sub bass, vinyl grit; male mid-low rap, haunted morbid menace, dense multisyllabic rhymes, relaxed pocket into double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "", "chars": 4234}], "title": "Me, Though Thought", "session": "Oct 8 Reset", "latest": "me-though-thought_v06_Cue"}, {"slug": "missing-person", "ep": false, "versions": [{"stem": "missing-person_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "Missing Person", "lyrics": "[Intro: radio static, then the piano, then the break]\n\n[Verse 1]\nShe said, \"I need to find myself.\" I said, \"Okay. Where'd you see you last?\"\nChecked the couch, the car, the closet, every picture under glass.\nSaid she had to learn to love herself, said she was depressed;\nI said, \"Take whatever time you need,\" and I held down the rest.\nOffered to help her look. She said that's the problem: me.\nSo I stopped looking at her, tried to give her room to breathe.\nDays turned into months, and she's further every day,\nStanding in the kitchen while the woman that I knew walks away.\n[double-time] Flashlight, search party, bloodhounds, a helicopter, a poster on every pole on the block, a hotline, a sketch artist, a reward,\nDescription: wedding ring, a laugh I'd know anywhere, my last name, and a face that I kissed every morning that didn't look at me anymore,\n[half-time] I watched you disappear.\n[pause] You were standing right there.\n\n[Hook: chanted low, doubled]\nYou said you had to find yourself. I watched you disappear.\nPut your face on a milk carton. Been staring at it all year.\nMissing: one wife. Last seen: finding herself.\nSearch party of one, and I'm searching by myself.\nYou said you had to find yourself. I watched you disappear.\nPut your face on a milk carton. Been staring at it all year.\nMissing: one wife. Last seen: finding herself.\nSearch party of one, and I'm searching by myself.\n\n[Verse 2]\nMissing persons go in pieces. Nobody tells you that.\nFirst the laugh went missing. Then her hand. It never came back.\nThen the Sundays went missing. Then the dates. Then the \"us.\"\nThen her eyes when she looked at me, like a stranger on a bus.\nKept a candle in the window like a fool in an old song,\nKept her side of the bed made like she'd be home before long.\nTold my friends she's just tired. Told my mama she was stressed.\nTold myself she's finding something. Told myself I'm doing my best.\n[double-time] Missing: her laugh, missing: her touch, missing: the weekends, missing: the movie nights, missing: the \"night, love you,\" missing: the way that she said it,\nMissing: the woman in the photos on the fridge, the woman on the canvas, the woman who knew me, and nobody's calling it in like the whole world forgets it,\n[half-time] I filed a report.\n[pause] Cop said she's a grown woman. She can leave.\n\n[Hook: chanted low, doubled]\nYou said you had to find yourself. I watched you disappear.\nPut your face on a milk carton. Been staring at it all year.\nMissing: one wife. Last seen: finding herself.\nSearch party of one, and I'm searching by myself.\n\n[Verse 3: drums drop to kick and static, then build]\nThen I found her. Wasn't hiding. Wasn't lost. Wasn't alone.\nShe had an address in somebody's arms, in somebody's phone.\n\"Find yourself\" was the cover story. Somebody found her first,\nAnd the search I'd been running was a funeral in reverse.\nFunny thing about a missing person: sometimes they just left.\nFunny thing about a search: you find who's doing it. Yourself.\nWent looking for her two years and came back with me:\nA man I hadn't seen since ninety-nine, with a pen and a beat.\n[double-time] Notebook, old tapes, Canibus on repeat, the bars that I wrote in a binder in Washington, the voice that I lost in the marriage, the girls that still call me by name,\nI was looking for her on every street, and I kept turning corners and bumping into me, the same man, the same pen, and the same flame,\n[half-time] You said you had to find yourself.\n[pause] Hope you did. I did.\n\n[Final Hook: full beat, chanted, doubled]\nYou said you had to find yourself. I watched you disappear.\nWent looking for you two years, and found me standing here.\nMissing: one wife. Found: one man. Myself.\nYou were never lost. I was. Now I'm somewhere else.\nYou said you had to find yourself. I watched you disappear.\nWent looking for you two years, and found me standing here.\nMissing: one wife. Found: one man. Myself.\nYou were never lost. I was. Now I'm somewhere else.", "suno": {"title": "Missing Person", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 90 BPM, dusty swung drum break, hard cracking snare, haunting minor-key piano loop, faint radio static texture, deep upright bass, vinyl crackle, narrow smoky mix; male mid-low rap, bitter and searching, dry dark humor, dense multisyllabic internal rhymes, relaxed pocket into double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 8, 2026. Writer: Cue (Claude). Concept and hook line: Scatta (\"You said you had to find yourself. I watched you disappear.\"). Status: written listening candidate, unauditioned and unapproved.", "chars": 3963}], "title": "Missing Person", "session": "Oct 8 Reset", "latest": "missing-person_v01_Cue"}, {"slug": "next-year", "ep": false, "versions": [{"stem": "next-year_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "Next Year", "lyrics": "[Intro: tape hiss, then the break]\n\n[Verse 1]\nNinety-nine in Washington, a little demo, couple tracks;\nEverybody asking, \"When's the album?\" \"Next year. Relax.\"\nNext year came and went. Then I raised my right hand for the Air Force,\nSix years active, two reserve, still \"next year\" on the scoreboard.\nGot married. Next year. Had a daughter. Next year.\nHad another, then another. Next year. Next year. Next year.\nMy album's older than my oldest girl, older than my wedding,\nOlder than the divorce, and that one's still settling.\nPromised it so long it's a legend out in Washington, like Bigfoot:\nEverybody's heard about it. Nobody got a good look.\n[double-time] Tape deck, CD, MP3, the iPod, the cloud, the stream, the algorithm, every format died waiting on me, the industry changed seven times,\nDial-up to fiber, the Walkman to AirPods, and I'm still saying next year like a skipping groove stuck on the same rhymes,\n[half-time] Twenty-seven years.\n[pause] Funny. It wasn't the album I kept putting off.\n\n[Hook: chanted low, doubled]\nNext year. Next year. Twenty-seven years of next year.\nPressure in the pipes, and the needle's in the red here.\nEvery song's a valve, and I'm cranking 'em open. Hiss.\nNext year's here. Ain't no next year after this.\nNext year. Next year. Twenty-seven years of next year.\nPressure in the pipes, and the needle's in the red here.\nEvery song's a valve, and I'm cranking 'em open. Hiss.\nNext year's here. Ain't no next year after this.\n\n[Verse 2]\nTwo years, two and a half, the same thoughts circling the drain,\nNever going down, just circling, like a ceiling fan in my brain;\nUnresolved, like a picture with the middle cut out:\nI can see the edges. I just can't tell you what it's about.\nTherapy lets a little out, a teaspoon off the top;\nGive it a week, the pressure's back. The gauge don't ever stop.\nThen I write a song, and something hisses out the seam,\nAnd it don't matter if it's ugly, if it's a diss, or if it's mean;\nFinish it, I'm lighter, like I took off a cinderblock necklace.\nSelf-therapy. Self-relieving. Cheaper than a copay, and it's honest.\n[double-time] Tension, anxiety, anger, the madness, the negative, the regret, the resentment, the loose ends, the last words I never got to say,\nPressure cooker, pilot light, a kettle screaming, the valve on a boiler, I turn it a quarter and bleed it all off, and I'm okay,\n[half-time] For a night.\n[pause] Then I write another one.\n\n[Hook: chanted low, doubled]\nNext year. Next year. Twenty-seven years of next year.\nPressure in the pipes, and the needle's in the red here.\nEvery song's a valve, and I'm cranking 'em open. Hiss.\nNext year's here. Ain't no next year after this.\n\n[Verse 3: drums drop for two bars, then return]\nEvery song I finish, another puzzle piece clicks;\nPicture ain't sewn together yet, but I can see where the stitch is.\nI'm stitching it from the inside like a surgeon on himself:\nNo anesthesia, just a beat and a bottle of ink on the shelf.\nIt was never the album that I'm finishing. It's me.\nTook twenty-seven years to write it 'cause it took that long to be.\nSo this is next year. Put a date on it. Carve it in the stone.\nIf I die before it drops, play it at the funeral. I'll be home.\n[double-time] Thread through the needle, the needle through the skin, the skin of the story I been putting together since the first time I picked up a pen,\nEvery song a stitch, every stitch a scar, every scar a word I couldn't say, and I'm finally saying it, and I'm saying it again,\n[half-time] Picture's almost done.\n[pause] I can almost see his face.\n\n[Final Hook: full beat, chanted, doubled]\nNext year. Next year. Twenty-seven years of next year.\nPressure in the pipes, and the needle's out the red here.\nEvery song's a valve, and I opened every one. Hiss.\nNext year's here. Ain't no next year after this.\nNext year. Next year. Twenty-seven years of next year.\nPressure in the pipes, and the needle's out the red here.\nEvery song's a valve, and I opened every one. Hiss.\nNext year's here. Ain't no next year after this.", "suno": {"title": "Next Year", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 95 BPM, tape-saturated swung drum break, hard cracking snare, dusty minor-key piano loop, low hissing noise swells, deep upright bass, vinyl crackle, narrow smoky mix; male mid-low rap, wry and urgent, dry dark humor, dense multisyllabic internal rhymes, relaxed pocket into double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 8, 2026. Writer: Cue (Claude). Concept and source phrases: Scatta (97 NEW, Oct 6 morning notes, \"The Album\" and \"What Writing Is Doing Mentally\"). Status: written listening candidate, unauditioned and unapproved.", "chars": 4029}], "title": "Next Year", "session": "Oct 8 Reset", "latest": "next-year_v01_Cue"}, {"slug": "on-my-list", "ep": false, "versions": [{"stem": "on-my-list_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "On My List", "lyrics": "[Intro: hi-hat ticking alone, then the break]\n\n[Verse 1]\nAlarm at four forty-five, the house dark, the girls asleep;\nBadge, keys, coffee, out before the heater even breathes.\nHospital by six, I'm in the basement with the broken:\nPumps and monitors and beds that won't go down, alarms going.\nEvery floor got an emergency, and every emergency is mine;\nNurses love you when you fix it and forget you in no time.\nLongest break all day was five minutes in the cafeteria:\nWater and a Snickers so I don't fall out. That's the criteria.\nStay late 'cause the work don't care what time the school lets out;\nSomebody else gets the pickup. I get the guilt and the doubt.\n[double-time] Work order, work order, recall, a pump on 4 West, a monitor down in the ED, a bed with a mind of its own, a vent that won't stop crying,\nSurgeon wants it yesterday, the manager wants a number, everybody wants a body, nobody's asking if mine's dying,\n[half-time] Clocked out at seven.\n[pause] Shift two.\n\n[Hook: chanted low, doubled]\nClock out. Clock in. The shift starts again.\nFix machines all day, come home, and the work don't end.\n\"I'll record some songs. Just not today.\"\nIt's on my list. Under everything. That's where it stays.\nClock out. Clock in. The shift starts again.\nFix machines all day, come home, and the work don't end.\n\"I'll record some songs. Just not today.\"\nIt's on my list. Under everything. That's where it stays.\n\n[Verse 2]\nWalk in: three girls, three different weathers in one house,\nOne's a storm, one's a drought, one's a sunbeam with a mouth.\nDinner on the stove, the washer going, homework on the table;\nI referee the hallway like a cage match on cable.\nShowers, teeth, three heads of hair, I learned to braid off a video;\nSomebody's crying, somebody's yelling \"Dad!\", somebody's hiding under the pillow.\nMy back is killing me, my whole body hurts, and I'm smiling through it,\n'Cause a kid don't need to know what it costs. A kid just needs you to do it.\nLay with 'em till they're out, grown man feet hanging off a twin bed;\nFell asleep there more nights than I ever slept in my own bed.\n[double-time] Laundry, lunches, permission slips, a science project due tomorrow that they told me about tonight, a charger, a meltdown, a missing shoe,\nSocks in the dryer, nobody's matching, a tooth in a baggie, a dollar from where, the dishes, the trash, and a note from the school,\n[half-time] Kissed three foreheads.\n[pause] Shift three.\n\n[Hook: chanted low, doubled]\nClock out. Clock in. The shift starts again.\nFix machines all day, come home, and the work don't end.\n\"I'll record some songs. Just not today.\"\nIt's on my list. Under everything. That's where it stays.\n\n[Verse 3: drums drop to kick and hat, piano low]\nTwo in the morning, kitchen table, beat on low so I don't wake 'em;\nNotebook full of verses that I never had the daylight to say 'em.\nSaid it years ago: \"I'll join a gym. I'll record some songs.\nJust not today. It's on my list.\" And the list was long.\nBuilt the girls a planner, every task gets its own box;\nMine's at the bottom: \"record some songs.\" Been sitting there like a stopped clock.\nI ain't complaining. I'd do it all again for every one of 'em;\nI'm just saying there's a man under the list, and I'm digging him out from under 'em.\n[double-time] Pen cap in my teeth, a Snickers in my pocket, a hook in my head, the girls in their beds, the house so quiet I can hear the fridge hum,\nSixteen bars between the last load of laundry and the alarm, stealing the time like a thief in my own home, and I'm almost done,\n[half-time] Checked the box.\n[pause] Alarm's at four forty-five.\n\n[Final Hook: full beat, chanted, doubled]\nClock out. Clock in. The shift starts again.\nFix machines all day, come home, and the work don't end.\nIt was on my list: \"Record some songs. Just not today.\"\nYou're listening to it. Guess today came anyway.\nClock out. Clock in. The shift starts again.\nFix machines all day, come home, and the work don't end.\nIt was on my list: \"Record some songs. Just not today.\"\nYou're listening to it. Guess today came anyway.", "suno": {"title": "On My List", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 94 BPM, steady workmanlike swung drum break, hard cracking snare, dusty minor-key piano loop, ticking hi-hat, deep upright bass, vinyl crackle, narrow smoky mix; male mid-low rap, weary and wry, dense multisyllabic internal rhymes, relaxed pocket into double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 8, 2026. Writer: Cue (Claude). Concept and source phrases: Scatta (your own messages quoted in the Studio Launch source files for On My List and The Shift That Never Ends). Status: written listening candidate, unauditioned and unapproved.", "chars": 4055}], "title": "On My List", "session": "Oct 8 Reset", "latest": "on-my-list_v01_Cue"}, {"slug": "one-piece-left", "ep": false, "versions": [{"stem": "one-piece-left_v03_Cue", "version": 3, "writer": "Cue", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "One Piece Left", "lyrics": "[Intro: piano alone, then the kick]\n\n[Verse 1]\nTwo years I told everybody I was over it, and meant it;\nSaid it at the barbershop, at work, I said it to the dentist,\nSaid it to the mirror like a mantra till the words wore smooth.\nThen a man in a polo at the door said my whole government name,\nHanded me an envelope like a waiter with the check, and walked away.\nIn July she said she's mourning what we lost. I asked her, \"What?\"\n\"The relationship we had.\" And I felt something I forgot.\nThought I swept that kitchen years ago. Thought I got it all.\nTurns out the last piece hides till you're barefoot in the hall.\n[double-time] Plaintiff, defendant, irreconcilable, the case number, the caption, the summons, the signature line, the date and the time,\nMy name in capital letters like a tombstone, like a warning label, like a label on a box, like a line item, fine,\n[half-time] I thought I was done.\n[pause] Paper said otherwise.\n\n[Hook: chanted low, doubled]\nSwept it up years ago, swore I got every shard;\nThen the papers hit the door, and I stepped on what was left of my heart.\nOne piece left. I didn't know I was holding on.\nOne piece left. Barefoot in the kitchen. Now it's gone.\nSwept it up years ago, swore I got every shard;\nThen the papers hit the door, and I stepped on what was left of my heart.\nOne piece left. I didn't know I was holding on.\nOne piece left. Barefoot in the kitchen. Now it's gone.\n\n[Verse 2]\nShe said my clock started ticking when they served me;\nHers been ticking almost two years. Same house. Different century.\nI'd accepted it like weather, but I checked the forecast every day;\nSaid I let go. I was holding on with my teeth the whole way.\nAsked her for a little time; she sent me back an invoice:\nWhat I owe, what she's owed. That's the morning I lost my voice.\nBoxes in the hallway, don't know where I'm sleeping in January;\nI was building the girls a planner, first thing in years that made me happy. Now it's buried.\nGirls down in Texas, I been calling every night on video;\nHad my mom tell 'em, \"Dad had a hard day. He loves you.\" First night I couldn't show.\nAccepting it and wanting it, I'm learning, ain't the same;\nYou can sign for the delivery and still not want what came.\n[double-time] Tick, tock, two clocks, new locks, a shoebox of photos and receipts, the deed, the keys, the lease, the schedule on the fridge for every other week,\nHer clock's at midnight, mine's at noon, I'm taping up a kitchen in a box at three, and I can't sleep,\n[half-time] She'd been mourning us for two years.\n[pause] I just started.\n\n[Hook: chanted low, doubled]\nSwept it up years ago, swore I got every shard;\nThen the papers hit the door, and I stepped on what was left of my heart.\nOne piece left. I didn't know I was holding on.\nOne piece left. Barefoot in the kitchen. Now it's gone.\n\n[Verse 3: drums thin, piano and bell stay]\nAnd I ain't the victim in every frame. I said things I can't unsay,\nCalled her names I'd break a man's jaw for if he called my daughters that today.\nShe told me those words stuck. I believe it. They stuck to me too.\nThat explains where my head was. It don't excuse it. That's the truth.\nThose feelings were mine to carry; they ain't give me the right\nTo swing 'em at her like a bat every time I lost a fight.\n[double-time] Broom and a dustpan, glass in the grout, glass in the rug, glass in my heel, I'm digging it out with a needle at three in the morning, bleeding a little,\nEvery time I think I got it all, a glint in the corner, a sliver, the last little piece in the middle,\n[half-time] Held it up to the light.\n[pause] Still mine.\n\n[Final Hook: full beat, chanted, doubled]\nSwept it up years ago, swore I got every shard;\nThen the papers hit the door, and I stepped on what was left of my heart.\nOne piece left. Not for you. I ain't handing it back.\nOne piece left, and it's mine. I can build from that.\nSwept it up years ago, swore I got every shard;\nThen the papers hit the door, and I stepped on what was left of my heart.\nOne piece left. Not for you. I ain't handing it back.\nOne piece left, and it's mine. I can build from that.", "suno": {"title": "One Piece Left", "lyrics": null, "style": "Dark gritty underground boom-bap, late 90s, 86 BPM, heavy dry kick, cracking snare, sparse melancholy minor-key piano with a cold glassy bell line, deep sub bass, vinyl hiss, bleak spacious mix; male mid-low rap, raw and bruised, dry morbid wit, dense multisyllabic internal rhymes, relaxed pocket into double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v03. October 8, 2026. Writer: Cue (Claude). Concept and source phrase: Scatta (your August 11, 2026 message, via the Teleanalyze Song Concepts report). Status: written listening candidate, unauditioned and unapproved.", "chars": 4097}], "title": "One Piece Left", "session": "Oct 8 Reset", "latest": "one-piece-left_v03_Cue"}, {"slug": "passenger-seat", "ep": false, "versions": [{"stem": "passenger-seat_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "Passenger Seat", "lyrics": "[Intro: tires and drums, then the loop]\n\n[Verse 1]\nTook time off work, packed the car the night before,\nKids in the back with the snacks and the chargers on the floor.\nHalfway to Texas, meeting Mom across the middle of the map;\nI wanted every stupid stop: the diner, lookout, souvenir crap.\nWanted the drive to be the trip, I wanted us to be the point;\nShe had her arms crossed at the window like she's serving time in a joint.\nReached across the console for her hand; she moved it like a fly.\n\"Don't.\" That was the whole conversation for the next hundred miles.\nEven the GPS was sweeter: \"In a half a mile, keep right.\"\nHers was \"Whatever.\" Hers was \"Fine.\" Hers was a sigh.\n[double-time] Mile marker, mile marker, cornfield, cattle, a billboard for Jesus, a billboard for lawyers, a billboard for fireworks,\nStatic on the radio, kids asleep, the tires hum, and every mile she's further than the mile before, and it gets worse,\n[half-time] Six inches from me.\n[pause] A thousand miles away.\n\n[Hook: chanted low, doubled]\nSame mouth, two voices: one for them and one for me.\nPhone rings, sunshine. Hang up, winter in the passenger seat.\nDrove a thousand miles beside somebody already gone.\nWho are you? You're not you. What did I do wrong?\nSame mouth, two voices: one for them and one for me.\nPhone rings, sunshine. Hang up, winter in the passenger seat.\nDrove a thousand miles beside somebody already gone.\nWho are you? You're not you. What did I do wrong?\n\n[Verse 2]\nHugged my mom at a gas station, handed off the kids;\nNow it's just us and the highway, and I don't know who this is.\n\"Why you talk to me like this?\" Like I'm the enemy you're stuck with,\nLike a hostage with a chauffeur, every word a little punishment.\nThen the phone lit up. \"Heyyy!\" Sunshine, laughing at a joke;\nSame mouth, a whole different woman. Warm. Alive. She spoke.\nHung up. Winter. Turned back to me, same face, but colder.\nThat voice was the woman I married, talking to somebody over my shoulder.\nShe said I'm reading into it; she never meant it mean.\nThen why'd your voice come back for anybody on the screen?\n[double-time] Hey, how are you, oh my God, I miss you, yeah, we're driving, it's so boring, I'll call you when we're home, love you, bye,\nThen the window, then the frost, then the arms crossed, then the lip bit, then the side-eye, then the miles, then the why,\n[half-time] Who are you?\n[pause] You're not you.\n\n[Hook: chanted low, doubled]\nSame mouth, two voices: one for them and one for me.\nPhone rings, sunshine. Hang up, winter in the passenger seat.\nDrove a thousand miles beside somebody already gone.\nWho are you? You're not you. What did I do wrong?\n\n[Verse 3: drums drop to kick and rim, loop filtered]\nI was grieving somebody who was sitting right beside me;\nHeld a wake at seventy, nobody saw me cry. I was driving.\nHad both hands on the wheel, but I was never in control;\nShe got out at an exit back there in the corn. I ain't see her go.\nBeen talking to an empty seat for miles: \"Look at that, babe. Look.\"\nPointing at the sunset like a fool, reading to a closed book.\nEverybody else still got you, every stranger on the phone\nGot the woman I was married to. I got the one already gone.\n[double-time] Exit sign, exit sign, should've read 'em, should've known it, should've pulled onto the shoulder, should've asked her where she's going, should've let her go,\nInstead I white-knuckled the wheel a thousand miles with a ghost riding shotgun and the radio on low,\n[half-time] I still drive that road in my sleep.\n[pause] She's never in the car.\n\n[Final Hook: full beat, chanted, doubled]\nSame mouth, two voices: one for them and one for me.\nPhone rings, sunshine. Hang up, winter in the passenger seat.\nDrove a thousand miles beside somebody already gone.\nI don't ask who you are no more. I just turn up the song.\nSame mouth, two voices: one for them and one for me.\nPhone rings, sunshine. Hang up, winter in the passenger seat.\nDrove a thousand miles beside somebody already gone.\nI don't ask who you are no more. I just turn up the song.", "suno": {"title": "Passenger Seat", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 90 BPM, steady rolling drum break, hard cracking snare, hypnotic minor-key piano and muted guitar loop, deep upright bass, faint tape hiss, vinyl crackle, narrow smoky mix; male mid-low rap, bitter and haunted, dry dark humor, dense multisyllabic internal rhymes, double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 8, 2026. Writer: Cue (Claude). Concept and source phrases: Scatta (97 NEW notes). Status: written listening candidate, unauditioned and unapproved.", "chars": 4041}], "title": "Passenger Seat", "session": "Oct 8 Reset", "latest": "passenger-seat_v01_Cue"}, {"slug": "questions", "ep": false, "versions": [{"stem": "questions_v03_Misc", "version": 3, "writer": "Misc", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "Questions", "lyrics": "[Verse 1 - dry, restless pocket]\nThe questions begin invading when I'm laid in my bed hating,\nWaiting for my life to be taken and forsaken.\nWings without wings; these things won't fucking land.\nI turn the pillow over like the other side has plans.\nDreams that break the dreams that include me—same destruction;\nEven sleep gets interrupted by the fucking introduction.\nIn the middle of a riddle, every nerve's another fiddle;\nDraw the bow across the middle; feel my hands begin to shiver.\n[double-time] Ceiling fissures, seeping pictures, teeth in whispers, linen twisted,\nLittle things I didn't finish get beneath my skin and itch it.\n[half-time] I didn't get to sleep.\n[pause] I just stopped moving.\nThe first consecutive words give birth to the next lecture;\nI catch the fucking sentence changing shape before I finish it.\nMy mouth is shut. The argument is getting more articulate.\nI lie there with my eyes closed, trying not to picture it.\n\n[Hook - rapped chant]\nQuestions. Who gets the last word?\nJaw locked. Still got a mouthful.\nLights out. Nothing goes quiet.\nI want one fucking night without it.\n\n[Verse 2 - lean behind the snare]\nI keep a conversation warm that should've been interred.\nThe dead have better fucking boundaries. They don't demand the final word.\nOverdosed with a host of phony yet persuasive hints;\nI strip the words for meaning till there's nothing left but fingerprints.\nAm I missing her, or missing who I was when I believed it?\nIs that something I remember, or a picture I keep feeding?\nThe first time ever—though the third time was even worse;\nI am not better. Instead, I am finding myself lost for words.\n[double-time] Backward glances, fractured answers, half a sentence, phantom gestures,\nMangled fragments, tangled tenses; past and present sewn together.\n[half-time] I don't know what she meant.\n[pause] I've got all night to guess.\nBleeding internally, burning with daggers—my old wording;\nI used to think describing it would stop the fucking hurting.\nIt gives the hurt a rhythm. Now I know where it comes in.\nI brace before the snare. Here comes the same shit again.\n\n[Hook - rapped chant]\nQuestions. Who gets the last word?\nJaw locked. Still got a mouthful.\nLights out. Nothing goes quiet.\nI want one fucking night without it.\n\n[Bridge - drums drop, rhythmic chant]\nNobody said a word.\nNothing in here stirred.\nThen what the fuck am I answering?\nThen what the fuck am I answering?\n\n[Verse 3 - narrow the pocket, then open it]\nSearching for another nobody without a soul to bridge;\nI built the fucking crossing out of things I never said.\nEvery plank's a different ending; every nail another maybe.\nI make it halfway over. Start debating what can take me.\nI keep thinking if I find the right arrangement of the words,\nI can make the past sit still enough to show me where it hurts.\nBut the second of the first becomes the first of something worse;\nEvery answer's got a mouth. I fucking hate how well it works.\n[double-time] Taut strings, jaw hinges, raw nerve endings under tension,\nThoughts hitch, knots cinch; every little twitch repeats the question.\n[half-time] Nobody's in here talking.\n[pause] I'm still answering.\nI try to leave it there. My tongue gets busy with the absence;\nOne more thing I should've said. One more fucking way to ask it.\nThe light gets through the curtains. I can see the room again.\nSame bed. Same head. Another fucking day begins.\n\n[Final Hook - rapped chant, bare drums]\nQuestions. Who gets the last word?\nJaw locked. Still got a mouthful.\nDaylight. Nothing goes quiet.\nI want one fucking night without it.\n\n[Outro - rapped, two slow lines]\nQuiet is the most wonderful sound on this earth.\n[pause] Silence is the most beautiful sound I never heard.", "suno": {"title": "Questions", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 90 BPM, swung acoustic drum break, hard cracking snare, dusty minor-key vintage piano loop, deep upright bass, low dissonant strings, vinyl crackle, narrow smoky mix; male mid-low rap, raw confessional pressure, dense multisyllabic internal rhymes, relaxed pocket into double-time bursts, rapped chant hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "", "chars": 3715}, {"stem": "questions_v04_Cue", "version": 4, "writer": "Cue", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "Questions", "lyrics": "[Intro: drums alone, then the piano]\n\n[Verse 1]\nThe questions begin invading when I'm laid in my bed, hating,\nWaiting for my life to be taken and forsaken\nTo whatever she seems to bring: wings without wings,\nDreams that break the dreams that include me\nIn the middle with a fiddle, playing a rose to a riddle;\nGretel left a trail of crumbs, and I ate every little\nPiece of the way back. I thought it was nasty, but ask me:\nIt was her bed that attracted me. She climbed on top, then strapped me\nTo the bedpost with the most ghostly look on her lips,\nOverdosed with a host of phony, yet almost persuasive, hints.\n[double-time] Wrist tied, lip bit, ankle angled, tangled in the strangled sheets,\nCandle wax and ghostly lips, the bedpost knocking like a heartbeat,\n[half-time] Should've known from the look she'd ghost me.\nNow the questions climb in on her side while the sheet's still warm,\nAsking in her voice, and \"I don't know\" ain't on the form.\n\n[Hook: low chant, doubled vocal]\nMaybe she wants to be the one,\nMaybe she just wants to have some fun,\nMaybe she's an angel laying with me,\nMaybe she's the devil when she speaks.\nMaybe she wants to be the one,\nMaybe she just wants to have some fun,\nMaybe she's an angel laying with me,\nMaybe she's the devil when she speaks.\n\n[Verse 2]\nShe got the devil's eyes and the mind-control effect,\nAnd the chemistry between us fails by what she injects;\nI'm satisfied with the lies she doesn't tell,\nIf she let me follow her to hell, I'd take her till I fail.\nLooking at her, and I see the devil's reflection,\nLooking at her, and I feel angelic perfection,\nAnd maybe it's you that I don't like, but I'ma forget it,\n'Cause you're so beautiful tonight, it's kinda pathetic.\n[double-time] Smoke-ring halos, crimson nails, a crucifix for decoration,\nHoly water in the ice tray and the devil in the conversation,\n[pause] And for the first time in my life, I refused.\nTurned the clock back, froze the moment that I went for the opening line,\nClosed my eyes, pretended I could hear laughter;\nShe was gone before the hook. I predicted hell after.\n\n[Hook: low chant, doubled vocal]\nMaybe she wants to be the one,\nMaybe she just wants to have some fun,\nMaybe she's an angel laying with me,\nMaybe she's the devil when she speaks.\nMaybe she wants to be the one,\nMaybe she just wants to have some fun,\nMaybe she's an angel laying with me,\nMaybe she's the devil when she speaks.\n\n[Bridge: drums drop, low and close]\nWhen she talks like this,\nI wanna miss.\nPlease don't feed me\nThe things I need.\nSilence is the most beautiful sound I never heard,\nQuiet is the most wonderful sound on this earth.\n\n[Verse 3: beat returns]\nLike my world when she left, it was never fatal,\nAnd I took that personal. The devil left my shoulder 'cause I slayed my angel;\nWith the blood in my hands, I raised the halo,\nAnd the victory is mine until I say no.\n[double-time] Roses are red from the blood that you spread, all the things that you said\nI'll take till I'm dead, on top of your bed, with the dreams from my head,\n[half-time] A halo's just a noose with better lighting.\nSo let's start all over from the first minute;\nI'll pretend I don't know you, and you don't know you're not finished.\nCradle me inside a basket full of lies. If I ask it, don't try;\nI'm a bastard who dies loving to kill love, and loving to walk away.\nDead to my world and happy, I pretend to laugh,\nBut the questions come at night and climb in on your half.\n\n[Final Hook: low chant, doubled vocal]\nMaybe she wants to be the one,\nMaybe she just wants to have some fun,\nMaybe she's an angel laying with me,\nMaybe she's the devil when she speaks.\nMaybe she was never the one,\nMaybe I was only her fun,\nMaybe she's an angel, maybe she's a beast,\nMaybe I don't need to know to sleep.", "suno": {"title": "Questions", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 88 BPM, swung dusty drum break, hard cracking snare, haunting minor-key piano loop, eerie reversed strings, deep upright bass, vinyl grit, narrow smoky mix; male mid-low rap, close dry vocal, insomniac confessional menace, dense multisyllabic internal rhymes, relaxed pocket into double-time bursts, low chanted hook", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "", "chars": 3760}], "title": "Questions", "session": "Oct 8 Reset", "latest": "questions_v04_Cue"}, {"slug": "rapper-again", "ep": false, "versions": [{"stem": "rapper-again_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "Rapper Again", "lyrics": "[Intro: a phone text tone, then the break]\n\n[Verse 1]\nNovember, twenty twenty-one, I typed it soft like a kid:\n\"R u gonna help me rap?\" She said, \"Sure.\" And then nobody did.\nNot her fault. I ain't ask again. I put it in a drawer\nWith the binder from the nineties and the dream I had before.\nJune, twenty twenty-three, six forty-eight in the morning,\nSent a text out of nowhere with no context and no warning:\n\"I want to be a rapper again.\" Sad face. Send.\nNext text, same thread: \"I need saline spray. I was choking on my own blood at two again.\"\nThat's the whole biography right there in two messages:\nThe dream and the nosebleed, sitting in the same thread like relatives.\n[double-time] Forty years old with a mortgage and three daughters and a pager and a nose that won't stop and a verse in my head that I never wrote down,\nCanibus in the car, Slug in the kitchen, Aesop on a walk, and the Grouch on a Sunday, all of 'em living, and me in the background, no sound,\n[half-time] I want to be a rapper again.\n[pause] Sad face.\n\n[Hook: chanted, doubled]\nI want to be a rapper again. Sad face. Send.\nSix forty-eight in the morning, texting it like it's a sin.\nBought a mic, sent it back, kept the box in the den;\nI want to be a rapper again. I want to be a rapper again.\nI want to be a rapper again. Sad face. Send.\nSix forty-eight in the morning, texting it like it's a sin.\nBought a mic, sent it back, kept the box in the den;\nI want to be a rapper again. I want to be a rapper again.\n\n[Verse 2]\nFourth of July, twenty twenty-four, the marriage on a ledge,\nShe sent me a song at one a.m. I gave it a five out of ten.\nThen I told her something true: \"You're resurrecting the rapper inside me.\nSame state of mind I was in when I wrote all my songs to girls.\" Wildly\nFunny, that the thing that broke me is the thing that woke him up;\nTeenage Scatta kicked the coffin from the inside of the trunk.\nSet a studio up. Wasn't working like it was supposed to;\nCables in the wrong holes. I could fix a ventilator. Couldn't fix the vocal.\n\"I have so many lyrics brewing in my head,\" I told her. \"I'll record\nIf I get the time and motivation.\" Two days later, I was returning the board.\n[double-time] Interface, headphones, a pop filter, a stand, a mic in a box with the plastic still on it, a cable, a cable, a cable, the receipt in the bag,\nDriving it back to the store with the windows down and the beat in my head that I never recorded, the cashier like \"Anything wrong with it?\" \"Nah. Just me.\" And the tag,\n[half-time] Store credit.\n[pause] Still got it.\n\n[Hook: chanted, doubled]\nI want to be a rapper again. Sad face. Send.\nSix forty-eight in the morning, texting it like it's a sin.\nBought a mic, sent it back, kept the box in the den;\nI want to be a rapper again. I want to be a rapper again.\n\n[Verse 3: break drops, then slams back in]\nOctober, twenty twenty-four: \"I want to rerecord a bunch of my old songs.\"\nShe wrote back, \"Take a weekend.\" Fair. Two words. Wasn't wrong.\nI took a weekend. Then another. Then a year. Then two.\nTurns out a weekend takes as long as it takes when it's you.\nNow it's twenty twenty-six, and I ain't asking anybody;\nNo permission slip, no \"can you help me,\" no sad face, no \"sorry.\"\nFallen Petals got a sequel. Dead Souls got a room.\nEvery song I ever wrote to girls is getting rewritten to the truth.\nI ain't the kid from Washington. I ain't the guy who asked.\nI'm the man who stayed up writing while the other two passed.\n[double-time] Pen, pad, beat, bed, bills, kids, shift, sleep, write, wake, rewrite, the wall full of notes and the folder full of drafts and the Suno and the Syncthing and the sync,\nForty-three and finally rapping like I meant it at seventeen, but I'm better, I'm darker, I'm deeper, I'm closer to me than I've been, and I'm closer than you think,\n[half-time] I'm a rapper again.\n[pause] Delete the sad face.\n\n[Final Hook: full beat, chanted, doubled]\nI'm a rapper again. No sad face. Send.\nSix forty-eight in the morning, writing like it ain't a sin.\nBought a mic, kept the mic, broke the box in the den;\nI'm a rapper again. I'm a rapper again.\nI'm a rapper again. No sad face. Send.\nSix forty-eight in the morning, writing like it ain't a sin.\nBought a mic, kept the mic, broke the box in the den;\nI'm a rapper again. I'm a rapper again.", "suno": {"title": "Rapper Again", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 93 BPM, dusty swung drum break, hard cracking snare, chopped minor-key soul piano sample, deep upright bass, faint turntable scratches, vinyl crackle, narrow smoky mix; male mid-low rap, wry and hungry, dark self-deprecating humor, dense multisyllabic internal rhymes, double-time bursts, chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 8, 2026. Writer: Cue (Claude). Source: your own texts about rapping, 2021 to 2024 (Seed Bank: Rapper Again). Status: written listening candidate, unauditioned and unapproved.", "chars": 4296}], "title": "Rapper Again", "session": "Oct 8 Reset", "latest": "rapper-again_v01_Cue"}, {"slug": "repair-tools", "ep": false, "versions": [{"stem": "repair-tools_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "Repair Tools", "lyrics": "[Intro: a toolbox latch, then the break]\n\n[Verse 1]\nI fix machines for a living. I can hear a bad bearing through a wall,\nRead a fault log like a horoscope, call a failure 'fore it falls.\nSo when the house started making noises, I just grabbed my bag:\nMultimeter, manual, patience, every tool I ever had.\nFirst code said, \"It's not you, it's me.\" Okay. I can work with that.\nNext day, \"It's you.\" Cleared it. Then the code came back:\n\"I gotta find myself.\" \"I gotta love myself.\" \"Depressed.\"\n\"Every chance I gave you, you ruined.\" \"I was too young to sign consent.\"\nI apologized to moving targets, went to therapy for crimes\nThat never held still long enough to tell me what the crime was this time.\n[double-time] Swap the board, swap the cable, swap the fuse, swap the attitude, swap the tone, swap the volume, swap the whole approach,\nRun diagnostics on my own chest, every sector, every circuit, every word I ever spoke and every joke,\n[half-time] Intermittent fault.\n[pause] Cannot duplicate.\n\n[Hook: chanted low, doubled]\nI brought repair tools. You brought an exit.\nFound the fault, you moved it. Fixed it, you reset it.\nSwapped every part I had, every cable, board and screw;\nIt wasn't broken. It was retired. Tech's the last one who knew.\nI brought repair tools. You brought an exit.\nFound the fault, you moved it. Fixed it, you reset it.\nSwapped every part I had, every cable, board and screw;\nIt wasn't broken. It was retired. Tech's the last one who knew.\n\n[Verse 2]\nAnd I ain't clean in this. I stayed up all night building slides:\nScreenshots, timestamps, arrows, red circles, highlighted lines.\nWalked into counseling with a laptop like a lawyer with a case,\nProved a pattern, lost the room. Won the argument, lost the place.\nI'm not proud of it. I apologized more times than I can count;\nI'd take back how I brought it, not the shit it was about.\nI can regret the weapon and not pretend the wound was fake;\nWrong way to bring the evidence don't make the evidence a mistake.\nI'll own every stone I threw. I'll pay for every window.\nI ain't confessing to the avalanche. I was standing under it, though.\n[double-time] Slide one, slide two, deflect, deny, defer, redirect, the projector humming, the counselor writing, my eyes bloodshot,\nSlide forty, slide fifty, should've closed the laptop, should've said, \"I miss you,\" should've said it plain, and I forgot,\n[half-time] Right argument.\n[pause] Wrong way to make it.\n\n[Hook: chanted low, doubled]\nI brought repair tools. You brought an exit.\nFound the fault, you moved it. Fixed it, you reset it.\nSwapped every part I had, every cable, board and screw;\nIt wasn't broken. It was retired. Tech's the last one who knew.\n\n[Verse 3: drums drop to kick and rim, cello stays]\nNext session I came in with every tool laid on the table:\nWorkbooks, notes, apologies, I'm ready, I'm willing, I'm able.\nCounselor asked her what she wanted. She ain't even look up:\n\"All I want is a clean divorce.\" And I just broke. I couldn't stop.\nSame room, same couch, two completely different reasons:\nI came to fix the leaking. She was already leaving.\nI was reading her the manual; she was reading the exit sign,\nHad her coat on in her head the whole time, I was on the clock, she was on borrowed time.\n[double-time] Tissue box, couch cushion, clock face, cold coffee, office plant, a painting of a boat, a sign on the wall that says breathe, and I can't breathe,\nShoulders shaking, grown man, Air Force, hands that fix machines, and I'm folded over, I can't stop, and I can't leave,\n[half-time] Clean divorce.\n[pause] Nothing about it was clean.\nSpent years asking what else I could do, what else I could become;\nMaybe the answer now is nothing. Maybe nothing is the one.\n\n[Final Hook: full beat, chanted, doubled]\nI brought repair tools. You brought an exit.\nFound the fault, you moved it. Fixed it, you reset it.\nSwapped every part I had, every cable, board and screw;\nTagged it end of life, signed the ticket. I'm off the clock too.\nI brought repair tools. You brought an exit.\nFound the fault, you moved it. Fixed it, you reset it.\nSwapped every part I had, every cable, board and screw;\nTagged it end of life, signed the ticket. I'm off the clock too.", "suno": {"title": "Repair Tools", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 94 BPM, hard swung drum break, cracking snare, cold minor-key piano stabs, ominous low cello, deep upright bass, faint mechanical clicks, vinyl crackle, narrow smoky mix; male mid-low rap, clinical menace, dry dark humor, dense multisyllabic internal rhymes, double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 8, 2026. Writer: Cue (Claude). Concept and source phrases: Scatta (97 NEW notes). Status: written listening candidate, unauditioned and unapproved.", "chars": 4198}], "title": "Repair Tools", "session": "Oct 8 Reset", "latest": "repair-tools_v01_Cue"}, {"slug": "ep2-ring-light", "ep": true, "versions": [{"stem": "ep2-ring-light_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "Ring Light", "lyrics": "[Intro: electrical hum, then piano, then the break]\n\n[Verse 1]\nEverybody saw the glow. I saw it first. I married it.\nSwore she lit up every room. Never asked who's paying the electric.\nHalo on the profile pic, halo at the party, halo at the job,\nHalo in the group chat, halo when the camera's on.\nAt home the halo was a flashlight in my eyes at three a.m.;\nAsked her nice as I could. Had a robot word it for me. Amen.\nLight right in my face while I'm sleeping, and I'm the one that's rude?\nFunny how the brightest thing in the house is the thing that never once got through.\nHalo's got a power cord. Halo's got a switch.\nHalo's only on when somebody's watching. That's the glitch.\n[double-time] Ring light, flash on, filter on, angle up, smile wide, glow bright, caption it holy, the comments all hearts and the hands and the wings and the praise,\nRing light off, flash off, filter off, angle down, smile gone, glow out, the room getting cold and the face that I knew going gray,\n[half-time] They say that's the night the devil showed up.\n[pause] I was asleep.\n\n[Hook: chanted low, doubled]\nHer halo was a ring light, only on when somebody's watching;\nMy horns and her wings came in the same bag from the same shopping.\nSame receipt. Same date. Paid in full, same hand.\nAngel and the devil got bought together. Understand?\nHer halo was a ring light, only on when somebody's watching;\nMy horns and her wings came in the same bag from the same shopping.\nSame receipt. Same date. Paid in full, same hand.\nAngel and the devil got bought together. Understand?\n\n[Verse 2]\nKneeling in the ashes like an arson investigator;\nPoint of origin: her side of the bed. I'll show you the data.\nAccelerant: a voice that only warmed up on the phone;\nAngels don't come in at four in the morning smelling like smoke, alone.\nEvery time the house burned, she was standing in the yard, not a hair singed;\nI was carrying the kids out with my eyebrows gone, and they're calling me the arsonist.\nFunny how the devil's always the one holding the hose;\nFunny how the angel always knew where all the matches go.\nI'm the one with the burns. I'm the one with the scar tissue.\nShe's the one with the lighter, asking me, \"What's wrong with you?\"\n[double-time] Point of origin, burn pattern, char depth, alligatoring on the studs, the V on the wall pointing back at the outlet on her side of the room,\nMelted plastic, a pour trail, a lighter in a purse, a match with a lipstick print, and the smoke detector unplugged, I can read it like a tomb,\n[half-time] Devil got blamed for the fire.\n[pause] Devil was the one with the hose.\n\n[Hook: chanted low, doubled]\nHer halo was a ring light, only on when somebody's watching;\nMy horns and her wings came in the same bag from the same shopping.\nSame receipt. Same date. Paid in full, same hand.\nAngel and the devil got bought together. Understand?\n\n[Verse 3: drums drop to kick and hum]\nCleaning out the closet, found a bag from the party store,\nReceipt still in it, dated way before the war.\nTwo items: one pair of horns, one pair of wings.\nPaid with her card, her signature, same day, same ring.\nShe bought my costume 'fore I ever did a thing;\nWore the wings out every night, left my horns in the bag, waiting on a reason.\nI been playing a part she bought before she told me there's a play;\nLearned my lines off of her description, learned my blocking off her rage.\n[double-time] The light at three, the smoke on the coat, the voice on the phone, the receipt in the bag, the horns in my size, and the wings in her size, and the card in her name,\nEvery clue in the house been pointing one way, and I kept turning around, kept checking myself, kept checking my hands for the flame,\n[half-time] I don't know what she is yet.\n[pause] I just know who paid.\n\n[Final Hook: beat back, chanted, doubled]\nHer halo was a ring light, only on when somebody's watching;\nMy horns and her wings came in the same bag from the same shopping.\nSame receipt. Same date. Paid in full, same hand.\nShe bought the devil's costume first. Now I understand.\nHer halo was a ring light, only on when somebody's watching;\nMy horns and her wings came in the same bag from the same shopping.\nSame receipt. Same date. Paid in full, same hand.\nShe bought the devil's costume first. Now I understand.", "suno": {"title": "Ring Light", "lyrics": null, "style": "Dark cinematic underground boom-bap, late 90s, 90 BPM, heavy swung drum break, cracking snare, eerie minor-key piano, faint buzzing electrical hum, low bowed strings, deep sub bass, vinyl grit; male mid-low rap, suspicious and cold, investigative delivery, dense multisyllabic internal rhymes, relaxed pocket into double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 8, 2026. Writer: Cue (Claude). EP track 2 (angel/devil mirror EP, not the album): the clue song. Concept: Scatta (EP Working Concept, Oct 8). Status: written listening candidate, unauditioned and unapproved.", "chars": 4276}], "title": "Ring Light", "session": "Oct 8 Reset", "latest": "ep2-ring-light_v01_Cue"}, {"slug": "smallest-man-in-the-room", "ep": false, "versions": [{"stem": "smallest-man-in-the-room_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "Smallest Man in the Room", "lyrics": "[Intro: piano alone, then the break]\n\n[Verse 1]\nShyest kid in the whole school, not exaggerating, the whole school;\nRather melt into the wall paint than raise a hand in homeroom.\nAnxiety had a grip on me like a coach with a whistle;\nEvery joke I ever had stayed in my head like a missile in a silo.\nSilent guy, no personality, the nice guy, bland;\nHated who I was so much I couldn't shake my own hand.\nForty years of punchlines sitting in the chamber, never fired;\nWalked in every room like I'm apologizing that I'm hired.\nI never thought I was better than nobody, swear to God;\nIf anything, I'm at the bottom of the barrel, scraping the rod.\n[double-time] Eyes on the floor, eyes on my shoes, eyes on the clock, eyes on the door, eyes on the exit sign, eyes on anything that ain't you,\nShoulders up, voice low, back to the wall, shrinking a size every time that I talk, I was the smallest man in the room, and I knew,\n[half-time] Nobody noticed me.\n[pause] That was the plan.\n\n[Hook: chanted low, doubled]\nSmallest man in the room, back against the wall;\nShyest kid in the school, and you're calling me a narcissist? Y'all.\nDid thirty sessions on a couch to see if I was what you said;\nCame home to \"Daddy is funny\" on a card, and that's the one I read.\nSmallest man in the room, back against the wall;\nShyest kid in the school, and you're calling me a narcissist? Y'all.\nDid thirty sessions on a couch to see if I was what you said;\nCame home to \"Daddy is funny\" on a card, and that's the one I read.\n\n[Verse 2]\nThere ain't a day goes by I don't think about you saying it;\nYou were convinced. I took it to therapy and started weighing it.\nThirty sessions, soul searching, reading every book,\nHolding up a magnifying glass to every word, every look.\nI don't like attention. I don't brag. I hate talking about me;\nSo naturally I wrote a whole album about me. Make it make sense, see?\nA narcissist don't hate his own reflection for thirty years;\nA narcissist don't cry in the car so nobody sees the tears.\nIt burns me. Not 'cause I'm perfect. 'Cause I know the man you meant,\nAnd I looked for him in every room I ever was in, and he never went.\n[double-time] Grandiose? I can't take a compliment without shrinking. Entitled? I apologize to the furniture. Empathy? I feel everybody's weather in the room,\nAdmiration? I'd rather be invisible. Superior? I'm the dude at the party in the kitchen with the dog. Exploiting? I'm the one getting used,\n[half-time] Wrong diagnosis.\n[pause] Right patient, though. I needed the help.\n\n[Hook: chanted low, doubled]\nSmallest man in the room, back against the wall;\nShyest kid in the school, and you're calling me a narcissist? Y'all.\nDid thirty sessions on a couch to see if I was what you said;\nCame home to \"Daddy is funny\" on a card, and that's the one I read.\n\n[Verse 3: beat opens up, bass walks]\nThen a doctor gave my brain a name, and something unlocked;\nAll them jokes I held for forty years came out like a jack-in-the-box.\nCracking up the whole department, nurses crying at the pumps;\nNever been the funny guy. Now I'm the reason for the lumps\nIn the throat from laughing. Walk in, and people smile. That never happened.\nNot in school, not anywhere. I swear to God, I'm still not having\nA big head about it. It's just strange to finally take up space;\nThree girls wrote \"Daddy is funny\" on a Father's Day card. That's the case.\n[double-time] Still shy, still quiet, still the last one to talk, still the dude in the back, still the one who gets red when you clap, still a little afraid,\nBut I'm off the wall, I'm in the room, I'm in the picture, I'm in the joke, I'm in my own skin, and I'm telling it straight to your face,\n[half-time] Still the smallest man in the room.\n[pause] Just stopped apologizing for the size.\n\n[Final Hook: full beat, chanted, doubled]\nStill the smallest man in the room, but I'm standing off the wall;\nShyest kid in the school walked in and made the whole room laugh. Y'all.\nDid thirty sessions on a couch to see if I was what you said;\nCame home to \"Daddy is funny\" on a card, and that's the one I read.\nStill the smallest man in the room, but I'm standing off the wall;\nShyest kid in the school walked in and made the whole room laugh. Y'all.\nDid thirty sessions on a couch to see if I was what you said;\nCame home to \"Daddy is funny\" on a card, and that's the one I read.", "suno": {"title": "Smallest Man in the Room", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 88 BPM, sparse swung drum break, dry cracking snare, wistful minor-key piano loop, deep upright bass, vinyl crackle, narrow smoky mix; male mid-low rap, wry and self-deprecating, quiet confidence growing, dense multisyllabic internal rhymes, relaxed pocket into double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 8, 2026. Writer: Cue (Claude). Concept and source phrases: Scatta (your July 31, 2024 and January 6, 2026 messages, via the Studio Launch source file). Status: written listening candidate, unauditioned and unapproved.", "chars": 4348}], "title": "Smallest Man in the Room", "session": "Oct 8 Reset", "latest": "smallest-man-in-the-room_v01_Cue"}, {"slug": "the-drive-home", "ep": false, "versions": [{"stem": "the-drive-home_v03_Misc", "version": 3, "writer": "Misc", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "The Drive Home", "lyrics": "[Verse 1]\nI leave work laughing; last one lingers as the engine catches.\nA fault clears. A joke lands. I know just where to put my hands.\nClock out of being useful. Let the silence have a crack at that.\nMy name still on the badge; the rest of me starts coming unattached.\nI forget about you at work. I become myself again;\nThen the first turn takes the grin. The second takes the man.\nSame name stitched across my chest; the thread outlasts the flesh.\nI'm wearing proof of who I am. I can't remember who that is.\n[double-time] Exit signs, severed ties, red reflected in my retinas,\nEvery mile another file on who I was before I entered this.\n[half-time] I pull over. I can't see.\n[pause] The fucking road is right in front of me.\nCars slide by. Each one gets somebody a little closer.\nThe belt still holds a body while I cry against the shoulder.\nSame road. Same fucking driver. Something missing in the car.\nA funeral gets right of way. I put my blinker on.\n\n[Hook - rapped chant]\nDrive home. White line. Dry throat.\nTake the long way. Find the same road.\nDrive home. Teeth clenched. Lights low.\nMile by fucking mile, a little less of me gets home.\n\n[Verse 2]\nCHECK DRIVER. Little yellow verdict bleeding through the plastic.\nFunny how the warning never says which part is damaged.\nI thumb through every page: the pressure, coolant, oil and brakes.\nThe fucking index ends before it gets to why I stay.\nYou brought me food and cards. I felt a little warmth come through.\nThat's in the wreckage too. I won't pretend it isn't true.\nThen why am I pulled over, trying to get enough air\nTo ask if you still love me? Like the answer isn't there.\n[double-time] Misunderstood, pushed aside, sick, ashamed - my own description,\nEvery adjective a toe tag with the same address imprinted.\n[half-time] I still fucking love you.\n[pause] That's the part I can't repair.\nI've got a box for every size of bolt. None of this fits inside.\nThe headlights pass without a verdict. Yellow crawls across my wrist.\nI put it into drive. That isn't proof I handled shit.\nJust means the engine started. Just means I moved the stick.\n\n[Hook - rapped chant]\nDrive home. White line. Dry throat.\nTake the long way. Find the same road.\nDrive home. Teeth clenched. Lights low.\nMile by fucking mile, a little less of me gets home.\n\n[Bridge - drums drop, rhythmic chant]\nHands at ten and two.\nNothing left to hold.\nI know the fucking address.\nWhy's it feel like I don't?\nHands at ten and two.\nI can get there with my eyes closed.\nI keep them open.\nI don't trust what follows.\n\n[Verse 3]\nFront light. Engine off. The hush arrives before the key does.\nI sit there with the version of myself the windshield leaves me.\nThe man at work could find the fault by listening to the rattle;\nThis one needs a second just to get the fucking latch up.\nNot asking for a fucking medal. Just a hand against my back.\nI've carried dead equipment in with less to brace against.\nThe box clicks shut. It does what it's supposed to. Holds its shit in.\nI almost put the bastard down as fucking next of kin.\n[double-time] Shop noise, lost voice, lock choice, one more quarter turn;\nTorque and tension, forced expression, all the shit I can't return.\n[half-time] The fucking key works.\n[pause] That's what gets me.\nThe lock knows who I am by all the pieces that are missing.\nA little mutilation, and it calls the damage fitting.\nSame name stitched across my chest. I take the box inside.\nIt doesn't ask which part of me got left along the drive.\n\n[Final Hook - rapped chant, bare drums]\nDrive home. White line. Dry throat.\nTake the long way. Find the same road.\nDrive home. Door shut. Lights low.\nI made it to the house. That's all the fucking map can show.", "suno": {"title": "The Drive Home", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 90 BPM, swung acoustic drum break, hard cracking snare, dusty minor-key vintage piano loop, deep upright bass, vinyl crackle, narrow smoky mix; male mid-low rap, raw confessional pressure, dense multisyllabic internal rhymes, relaxed pocket into double-time bursts, fully rapped chant hooks, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v03. October 8, 2026. Actual writer: misc (ChatGPT/Codex). The filename tag is Misc, corrected from Q on October 8; this is an attribution correction, not a new lyric version. Status: written candidate, ready for a first listening test after field validation; neither heard nor approved.", "chars": 3696}], "title": "The Drive Home", "session": "Oct 8 Reset", "latest": "the-drive-home_v03_Misc"}, {"slug": "the-wake-of-hells-birth", "ep": false, "versions": [{"stem": "the-wake-of-hells-birth_v06_Misc", "version": 6, "writer": "Misc", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "The Wake of Hell's Birth", "lyrics": "[Verse 1 - close, restrained]\nEyes closed, I am staring at nothing outside this window.\nI am not me as I cover the black widow.\nBorn again—same nerves, same dirt beneath the nails.\nSomebody kept the old mistakes. Nice fucking eye for detail.\nReenact the facts with the words of Shakespeare;\nThe tragedy survives. The fucking names are less clear.\n[double-time] Envision the missions of past failures: split decisions, little fissures,\nNails against the grain; the skin remembers every fucking splinter.\n[half-time] I can still feel it.\n[pause] Whatever's left of me.\nSignificant but missing—call it the wake of hell's birth.\nRaised from hell's earth. Still got the taste of dirt.\nThis is it. My destiny. What I'm about to be.\nAll pre-written. What's left of me? That's what I'm about to see.\nKill me right now before the sun sets; heal me where I fell.\nPut me down before the regrets—then ask me if I'm well.\n\n[Hook - low rapped chant]\nThis is you. This is not me.\nSame face. Who the fuck do you see?\nWake of hell's birth. Take another breath.\nSomething keeps waking up. I haven't met it yet.\n\n[Verse 2 - loosen, then tighten]\nDay two of my second afterlife.\nCan't figure out who. Is this my second wife?\nSecond night, but not consecutive—right?\nThe calendar's in pieces; every piece says tonight.\nBefore last night I was somebody else—right?\nOr was it a dream, that demon stealing hopes at night?\nShe's saying Jason Curtis like she's identifying the body.\nShe blows a kiss. I catch myself responding automatically.\n[double-time] Missing minutes, shifted features, bitten lips and little shivers,\nFingers finding skin familiar; still the feeling doesn't fit it.\n[half-time] I don't know who she's holding.\n[pause] I say my name again.\nNot passionate bliss; still getting a little higher,\nTrying to find the man inside the shape of her desire.\nAs we take a pause, we take a look into that mirror.\nThe face is getting sharper. The afterlife ain't clearer.\n\n[Hook - low rapped chant]\nThis is you. This is not me.\nSame face. Who the fuck do you see?\nWake of hell's birth. Take another breath.\nSomething keeps waking up. I haven't met it yet.\n\n[Bridge - drums drop, rhythmic chant]\nHold me.\nWho's that?\nSay my name.\nLet me hear it back.\n\n[Verse 3 - tighten the consonants]\nI begin to see the world the way she sees on my third day.\nI can't believe the things she can't say.\nWalking across, talking to clocks that pop;\nHang the loss on the wall. Let it count what I've got.\nTake my watch. Take caution on the tock;\nEvery second I can name's another second I have lost.\nThe hands keep fucking moving. I'm the part that doesn't follow.\nI can hear the tick inside my chest. The next one's hard to swallow.\n[double-time] The lesson we're stressing, confessing obsession with reps in the last impressions,\nThe second hand's severing seconds; I'm left with the flesh of the questions.\n[half-time] I can't read. Talk to me.\n[pause] Tell me what you're seeing.\nCan't see. Can't breathe freely. Don't know what I believe.\nI'm sorry—really—but this is not me.\nI think. Probably. Even that won't come out clean.\nI keep saying this is not me. Whose fucking voice is speaking?\n\n[Final Hook - rapped chant, bare drums]\nThis is you. This is not me.\nSame face. Who the fuck do you see?\nWake of hell's birth. Take another breath.\nSomething keeps waking up. I haven't met it yet.\n\n[Outro - slow rap]\nMy name comes when she calls.\n[pause] The rest of me is missing.", "suno": {"title": "The Wake of Hell's Birth", "lyrics": null, "style": "Dark gritty cinematic underground East Coast boom-bap, late 90s, 88 BPM, heavy swung drum break, cracking snare, ominous minor-key piano, low bowed strings, faint clock tick, distant funeral organ swell, deep sub bass, vinyl grit; male mid-low rap, haunted confessional menace, dense multisyllabic internal rhymes, double-time bursts, low rapped chant hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "", "chars": 3440}], "title": "The Wake of Hell's Birth", "session": "Oct 8 Reset", "latest": "the-wake-of-hells-birth_v06_Misc"}, {"slug": "till-death-do-i-part", "ep": false, "versions": [{"stem": "till-death-do-i-part_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "Till Death Do I Part", "lyrics": "[Intro: piano loop, then the break]\n\n[Verse 1]\nNinety-nine, I'm on a demo talking 'bout a picket fence,\nA wife, some kids, a porch, the American dream at full expense.\nTwo rocking chairs, holding hands till the hands get spotted;\nDying single was the scariest shit that I ever thought of.\nThought alone was a sentence. Thought single was a cell;\nThought a man without a wife was a story nobody tells.\nNow I picture my deathbed, and it's packed, it's standing room,\nThree daughters fighting over my vinyl like probate court in the bedroom.\nSingle ain't the same as alone. I had the math wrong;\nA ring ain't the only receipt that says a life was lived long.\n[double-time] Fence, porch, ring, vows, house, kids, the minivan, the grill, the plan, the rocking chairs, the hands, the whole brochure,\nI bought it, I lived it, I loved it, I'd do it again, but I'm not gonna do it again, and I'm sure,\n[half-time] Dying alone used to scare me.\n[pause] Now it just sounds quiet.\n\n[Hook: chanted low, doubled]\nI ain't unlovable. That's the problem, see:\nIf I loved you, I'd out-love you. Wouldn't be nothing left of me.\nTill death do I part, me and my time.\nNo vacancy. The heart's full. It's just finally mine.\nI ain't unlovable. That's the problem, see:\nIf I loved you, I'd out-love you. Wouldn't be nothing left of me.\nTill death do I part, me and my time.\nNo vacancy. The heart's full. It's just finally mine.\n\n[Verse 2]\nHere's the thing about me: I'm a giver. It's a sickness.\nHand you my last dollar, then apologize for the inconvenience.\nCan't take a gift without a guilt trip; I'm already paying it back.\nIn love I'm worse. \"Where you wanna eat?\" \"Wherever.\" \"Watch?\" \"You pick.\" That's that.\n\"Where we going this weekend?\" Anywhere. Somewhere in there, I quit.\nTwo people acting as one sounded holy in the vows.\nNobody said which one. Ten years later, I'm looking for me in the house.\nNobody ordered me to vanish. Nobody had to make me;\nI disappear 'cause giving feels like breathing, and it takes me.\nFirst thing I'd lose if I fell again? Easy. My freedom. My time.\nPicture the finest woman ever made sliding up like, \"Let's link. You mine?\"\nTeenage me just fainted on the floor. Present me said, \"Nah,\nI'm good. I got a verse to finish.\" And I meant it. That's the flaw.\n[double-time] Flowers, dinners, texts, the reservations, read receipts, \"what you mean by that,\" her mother's birthday, her best friend's divorce,\nThe gym, the cologne, the \"so what are we,\" the calendar, the couples' counseling, the whole course,\n[half-time] I know what I become in love.\n[pause] I'd out-love you. And there'd be no me left.\n\n[Hook: chanted low, doubled]\nI ain't unlovable. That's the problem, see:\nIf I loved you, I'd out-love you. Wouldn't be nothing left of me.\nTill death do I part, me and my time.\nNo vacancy. The heart's full. It's just finally mine.\n\n[Verse 3]\nYeah, there's a scar. I ain't gonna pretend it ain't there;\nSomebody had the keys once, and they drove it like they didn't care.\nBut the scar is evidence. It ain't the thesis. Don't confuse it:\nI ain't scared of what you'd do to me. I'm scared of what I'd do for you. I'd lose it.\nNow the devotion got a new address: the page, the pad, the pen;\nDeeper in this rap shit than I been since I was a kid, again.\nHip-hop don't ask me where to eat, then veto all five places;\nHip-hop just keeps me up till four, nudging snares and counting spaces.\nNo anniversary, but the beat still expects flowers;\nThirty-seven versions of a verse. That's my couples' counseling hours.\n[double-time] Saturday with the girls, Sunday with the books, Monday with the machines, every night with the pad and the pen and the ink and the sheet and the beat,\nI'm not lonely, I'm busy, I'm learning, I'm writing, I'm finally becoming the me that I was before I was a we,\n[half-time] It ain't bitterness.\n[pause] It's a choice.\n\n[Final Hook: full beat, chanted, doubled]\nI ain't unlovable. That's the problem, see:\nIf I loved you, I'd out-love you. Wouldn't be nothing left of me.\nTill death do I part, me and my time.\nAsk me again next year. Right now? I'm mine.\nI ain't unlovable. That's the problem, see:\nIf I loved you, I'd out-love you. Wouldn't be nothing left of me.\nTill death do I part, me and my time.\nAsk me again next year. Right now? I'm mine.", "suno": {"title": "Till Death Do I Part", "lyrics": null, "style": "Gritty underground East Coast boom-bap, late 90s, 93 BPM, crisp swung drum break, hard cracking snare, dusty minor-key piano loop, walking upright bass, vinyl crackle, narrow smoky mix; male mid-low rap, dry sardonic wit, confident and self-aware, dense multisyllabic internal rhymes, relaxed pocket into double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 8, 2026. Writer: Cue (Claude). Concept, title and source phrases: Scatta (97 NEW, Oct 6 morning notes, \"I Don't Want to Fall in Love Again\"). Status: written listening candidate, unauditioned and unapproved.", "chars": 4281}], "title": "Till Death Do I Part", "session": "Oct 8 Reset", "latest": "till-death-do-i-part_v01_Cue"}, {"slug": "tomorrow-in-guam", "ep": false, "versions": [{"stem": "tomorrow-in-guam_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "Tomorrow in Guam", "lyrics": "[Intro: a phone ringing out, no answer, then the strings, then the break]\n\n[Verse 1]\nCalled my dad on a Monday. Called him Tuesday. Called him all week.\n\"Supposed to be here June or July.\" It's July. He don't speak.\nAsked him for dates for over a year, and I can't get a day out of him;\n\"Nobody knows,\" I tell the family, \"including him.\" I still pray about him.\nFourth of July, took the girls to a friend's house with the grill on,\nFireworks, other people's kids, a lawn chair, and my phone face up. Still on.\nHe didn't answer. Didn't text. Didn't call back after.\nSomewhere in the Pacific it's already the morning after.\nOnly lesson I remember: he held the back of my bike seat,\nRan beside me in the street, pushed till I stopped falling. Then let me be.\n[double-time] Ringing, ringing, ringing, the voicemail full, the voicemail full, I call it again like the number's gonna change its mind, I call it on the drive to work and on the drive back home,\nRinging in the parking lot, ringing in the kitchen, ringing in the dark, ringing in a time zone where he's already living in tomorrow and I'm still on my own,\n[half-time] He let go of the seat.\n[pause] I been pedaling ever since.\n\n[Hook: chanted low, doubled]\nIt's already tomorrow where my father lives;\nI keep calling into tomorrow, and tomorrow never gives.\nMama drove up with Grandma, a thousand miles, no complaint;\nDad's fourteen hours ahead of me and still running late.\nIt's already tomorrow where my father lives;\nI keep calling into tomorrow, and tomorrow never gives.\nMama drove up with Grandma, a thousand miles, no complaint;\nDad's fourteen hours ahead of me and still running late.\n\n[Verse 2]\nMama tells the story. Same story for thirty years:\nThe house they lost, the dream she had, the path she walked alone in tears.\nI don't argue with it. I believe her. Every word of it is true;\nHe was a horrible husband. He's still my father. Both are true.\nAsked her once to please stop telling it in front of the ones I love;\nWorst fight we ever had. She said she'd leave. We cried it out above\nThe kitchen sink at midnight. I apologized. I meant it.\nThen I helped my daughter with her homework and the laundry, lay in bed, and resent it.\nIn a parallel universe he never made the choice he made;\nThey're retired on a porch with grandkids and the mortgage paid.\n[double-time] Thirty years of the same story, the same villain, the same ending, the same table, the same tears, the same chair that he never sat in, the same plate,\nI'm the son in the middle like a wishbone, both of 'em pulling, and I love 'em both, and I'm cracking right down the center of the family, and it's late,\n[half-time] Mama always shows up.\n[pause] That's her side of the story too.\n\n[Hook: chanted low, doubled]\nIt's already tomorrow where my father lives;\nI keep calling into tomorrow, and tomorrow never gives.\nMama drove up with Grandma, a thousand miles, no complaint;\nDad's fourteen hours ahead of me and still running late.\n\n[Verse 3: strings swell, drums hit harder]\nBack home, if an elder asks you something, you go;\nIf you see somebody working, you help. That's all I know.\nThat's the island in my blood, even way up here in the snow,\nWishing I had one Chamorro friend in Michigan to just say \"Håfa adai\" to. No.\nSo I'm the island now: I help, I go, I show,\nI'm the elder in my own house, and my girls are the reason I know.\nWhen they call, I pick up before the second ring;\nWhen they ride, I hold the seat as long as they need. I don't let go of a thing.\nAnd one day they'll hear stories about me at somebody's table;\nI just pray the story's mine, and it's the true one, and it's stable.\n[double-time] Fourteen hours behind my father and I'm still on time for the concert, the pickup, the science fair, the leprechaun trap, the birthday, the braids, the bedtime, the bike,\nI'm the dad who answers, the dad who shows, the dad who holds the seat till the wobble is gone and the girl in the street is laughing and pedaling into the night,\n[half-time] Call me back when you can, Dad.\n[pause] I'll pick up.\n\n[Final Hook: full beat, chanted, doubled]\nIt's already tomorrow where my father lives;\nI keep calling into tomorrow, and I'll keep calling. That's what it is.\nMy girls call, I pick up before the second ring;\nFourteen hours behind him, and I'm on time for everything.\nIt's already tomorrow where my father lives;\nI keep calling into tomorrow, and I'll keep calling. That's what it is.\nMy girls call, I pick up before the second ring;\nFourteen hours behind him, and I'm on time for everything.", "suno": {"title": "Tomorrow in Guam", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 86 BPM, slow swung drum break, cracking snare, melancholy minor-key string sample, warm muted guitar, faint ocean-wave noise, deep upright bass, vinyl crackle, narrow smoky mix; male mid-low rap, aching and steady, dense multisyllabic internal rhymes, relaxed pocket into double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 8, 2026. Writer: Cue (Claude). Source: your 2019 to 2026 messages about your dad, your mom, your grandma and Guam (Seed Bank: Tomorrow in Guam). Status: written listening candidate, unauditioned and unapproved.", "chars": 4539}], "title": "Tomorrow in Guam", "session": "Oct 8 Reset", "latest": "tomorrow-in-guam_v01_Cue"}, {"slug": "totem-pole", "ep": false, "versions": [{"stem": "totem-pole_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "Totem Pole", "lyrics": "[Intro: low toms alone, then the break]\n\n[Verse 1]\nWatched her drive three hours for a friend on a Tuesday;\nAsked her for a date on Friday, and she looked at me like, \"Who, me?\"\nWatched her stay up baking for a coworker's going-away;\nAsked her for a movie on the couch. \"I'm tired. Maybe another day.\"\nWatched her pick up on the first ring for anybody with a crisis;\nI'd be talking in the kitchen, and she'd scroll right past my sentence like it's lifeless.\nGo somewhere with me. Have a date with me. Do something with me. Try.\nI asked it so many ways I started rhyming it to keep it alive.\nIt ain't jealousy. I'm proud she got that much love in her;\nI just wanted to know why the man she married couldn't get a crumb of it.\n[double-time] Group chat, brunch, the birthday, the baby shower, the girls' trip, the gift for the neighbor, the card for the mailman, the call to the cousin, the favor, the ride to the airport at four,\nEverybody got a piece of her, everybody got a little light, and I'm standing at the bottom of the stairs with a coat on asking \"Are we going?\" at the door,\n[half-time] She said, \"Not tonight.\"\n[pause] She said it every night.\n\n[Hook: chanted low, doubled]\nBottom of your totem pole, face down in the dirt;\nEvery face above me smiling, and I'm holding up the work.\nAsked you for a date. Asked you for a night. Asked you, \"Try.\"\nLast place in a race I ain't even know we ran. Why?\nBottom of your totem pole, face down in the dirt;\nEvery face above me smiling, and I'm holding up the work.\nAsked you for a date. Asked you for a night. Asked you, \"Try.\"\nLast place in a race I ain't even know we ran. Why?\n\n[Verse 2]\n\"I feel like I'm at the bottom of your totem pole.\" I said that.\n\"I'm always last in your book now.\" She said, \"That's just how you read that.\"\nI kept begging, kept asking, \"Let's try to make this work\";\n\"Do something together. I don't care. I wanna try my best.\" It hurt\nTo watch somebody capable of effort, capable of warm,\nCapable of driving through a blizzard for a friend in a storm,\nAnd then come home and be a closed door with the porch light off;\nSame woman, same arms, and I'm the one she's cutting off.\nI'm your husband. Why am I the one you least wanna choose?\nI'd have settled for a Tuesday. I'd have settled for the news.\n[double-time] Carved at the bottom, the eagle on top, and the bear and the wolf and the raven and every friend that she had, and the face at the base is a man with his mouth open, asking,\nWeight on my head and a crick in my neck and the rain on my face and the whole thing standing on me like a joke that I'm in and not laughing,\n[half-time] Low man on the pole.\n[pause] Holds the whole thing up. Nobody looks down.\n\n[Hook: chanted low, doubled]\nBottom of your totem pole, face down in the dirt;\nEvery face above me smiling, and I'm holding up the work.\nAsked you for a date. Asked you for a night. Asked you, \"Try.\"\nLast place in a race I ain't even know we ran. Why?\n\n[Verse 3: drums drop to toms and piano, then build]\nTook me years to see the problem wasn't that I'm on the bottom;\nProblem was I kept on asking somebody who'd forgotten\nI was even on the pole. I was ranking for a judge\nWho wasn't even at the race. I was racing for a grudge.\nSo I stopped. Didn't storm off. Didn't burn it. Didn't yell.\nJust stopped asking for a seat at a table where I fell.\nPulled myself out from the bottom, braced for everything to crash;\nNothing fell. Not a face. Not a feather. Not an ash.\n[double-time] And it stung for a minute, I'm not lying, it stung like a wasp in the throat, 'cause I thought I was holding it up, and it turns out I was holding me down,\nThen I stretched out my back and I cracked out my neck and I stood up straight for the first time in years and I looked around at a whole lot of ground,\n[half-time] Nothing fell.\n[pause] Turns out I can stand.\n\n[Final Hook: full beat, chanted, doubled]\nBottom of your totem pole, face down in the dirt;\nEvery face above me smiling, and I'm holding up the work.\nPulled myself out from the bottom, and nothing came down;\nLast place in a race I quit. Now I'm standing on the ground.\nBottom of your totem pole, face down in the dirt;\nEvery face above me smiling, and I'm holding up the work.\nPulled myself out from the bottom, and nothing came down;\nLast place in a race I quit. Now I'm standing on the ground.", "suno": {"title": "Totem Pole", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 88 BPM, heavy plodding swung drum break, cracking snare, dusty minor-key piano loop, low tom accents, deep upright bass, vinyl crackle, narrow smoky mix; male mid-low rap, bitter and weary, dry dark humor, dense multisyllabic internal rhymes, relaxed pocket into double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 8, 2026. Writer: Cue (Claude). Concept and source phrases: Scatta (97 NEW notes, \"Bottom of the Totem Pole\"). Status: written listening candidate, unauditioned and unapproved.", "chars": 4335}], "title": "Totem Pole", "session": "Oct 8 Reset", "latest": "totem-pole_v01_Cue"}, {"slug": "twenty-times", "ep": false, "versions": [{"stem": "twenty-times_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "Twenty Times", "lyrics": "[Intro: piano alone, slow, then the kick]\n\n[Verse 1]\nDecember, twenty twenty-four, deeper than I knew a hole could go;\nFar, far deeper than I ever thought was possible. Low.\nIs it your fault? Absolutely not. You get zero blame from me.\nI don't expect you to pull me out. That part's on me.\nI try my best not to cry around y'all. Sometimes I can't hold it;\nThe kids see the sadness in my eyes. Work sees it. Strangers notice.\nIf you could feel this constant pain in my chest, this sickness in my head,\nYou'd understand the way I break, and why I break, and why I'm in bed.\nYou called it a turn-off. Like I'm putting on a show for you.\nYou think I picked this? You think I practice it? Like it's something I would choose?\n[double-time] Tears in the shower with the water up loud, tears in the car with the radio up, tears in the garage on a bucket in the dark with a space heater glow,\nTears in the closet, the hamper, the stairs, the end of the bed, the parking lot after a shift, a count that I kept like a prisoner keeping a wall in the hole,\n[half-time] This is just who I am right now.\n[pause] That's all. That's the whole sentence.\n\n[Hook: chanted low, doubled]\nFor every time you saw me cry, I cried twenty alone:\nIn the car, in the shower, in the dark, on the floor, at home.\nYou called it a turn-off, like I'm putting on a show;\nTwenty to one. That's the part you'll never know.\nFor every time you saw me cry, I cried twenty alone:\nIn the car, in the shower, in the dark, on the floor, at home.\nYou called it a turn-off, like I'm putting on a show;\nTwenty to one. That's the part you'll never know.\n\n[Verse 2]\nSummer before that, I'd forget at work, and I'd be myself;\nFix a pump, crack a joke, be a man, be somebody else.\nThen I'd get in the car, and the second I hit the road, I'm gone:\nHad to pull off to the shoulder several times, hazards on.\nGrown man in the breakdown lane, the semis shaking the frame,\nSobbing like a baby in a car seat, and nobody knows my name.\nTaco Bell and a card she left brought a little joy that day;\nFunny what a burrito does when everything else gave away.\nI needed a hug, or a goodbye, or something, anything at all;\nGot a puddle on the dashboard and a long drive and a wall.\n[double-time] Lost, broken, depressed, neglected, pushed aside, hated, despised, looked down on, broken again, stupid, wrong, ashamed, sick, confused, misunderstood,\nThat's the list I typed to her that night in the dark, every word of it mine, and then the last four words: \"and yet I still love you,\" like a fool, like I would,\n[half-time] Counted that one twice.\n[pause] Once for her. Once for me.\n\n[Hook: chanted low, doubled]\nFor every time you saw me cry, I cried twenty alone:\nIn the car, in the shower, in the dark, on the floor, at home.\nYou called it a turn-off, like I'm putting on a show;\nTwenty to one. That's the part you'll never know.\n\n[Verse 3: cello drops out, piano and drums]\nI broke in ways I didn't know a person could break;\nThen I rebuilt myself piece by piece, mistake by mistake.\nA lot of my passions take inspiration, and I had none;\nSaid, \"But I'm trying. I'll call about the gym.\" Called. Barely went. It's done.\nChristmas came. She gave a card. It made me cry. I typed,\n\"I know it's a turn-off, jk,\" and I laughed for the first time that night.\nThat's the moment, if I had to pick, the joke came back before the light;\nYou can't make a sad man laugh at himself unless he's halfway right.\nNow the pen's the inspiration, and the pages do the crying;\nEvery song's a place to put it where nobody's watching, and nobody's lying.\n[double-time] Twenty to one, then ten to one, then five to one, then a week with none, then a song on the radio in the car that got me, and I let it, and I didn't pull over, I drove,\nHands on the wheel and the tears on my face and the road in my lights, and I'm laughing at how I'm crying at a song that I wrote, and I know what I know,\n[half-time] I still cry sometimes.\n[pause] Now it's usually at the good parts.\n\n[Final Hook: full beat, chanted, doubled]\nFor every time you saw me cry, I cried twenty alone:\nIn the car, in the shower, in the dark, on the floor, at home.\nCalled it a turn-off. Wasn't a show. Wasn't a pose.\nTwenty to one. Still counting. Slower, though.\nFor every time you saw me cry, I cried twenty alone:\nIn the car, in the shower, in the dark, on the floor, at home.\nCalled it a turn-off. Wasn't a show. Wasn't a pose.\nTwenty to one. Still counting. Slower, though.", "suno": {"title": "Twenty Times", "lyrics": null, "style": "Dark gritty underground boom-bap, late 90s, 84 BPM, heavy slow drum break, dry cracking snare, cold sparse minor-key piano, low bowed cello, deep sub bass, rain-like vinyl hiss, bleak spacious mix; male mid-low rap, raw and quiet, confessional, dense multisyllabic internal rhymes, relaxed pocket into double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 8, 2026. Writer: Cue (Claude). Source: your July and December 2024 and May 2026 messages (Seed Bank: Twenty Times). Status: written listening candidate, unauditioned and unapproved.", "chars": 4458}], "title": "Twenty Times", "session": "Oct 8 Reset", "latest": "twenty-times_v01_Cue"}, {"slug": "under-the-floorboards", "ep": false, "versions": [{"stem": "under-the-floorboards_v01_Misc", "version": 1, "writer": "Misc", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "Under The Floorboards", "lyrics": "Under the Floorboards\n\n[Verse 1]\n\nGazing off into a realm of my own reality,  \nWhere the walls repeat my thoughts, then dispute their originality.  \nOut-of-body—watching somebody practice being me;  \nHe gets the gestures right, but keeps forgetting when to breathe.\n\nWallless hallways—still I take the fucking wrong turns;  \nExit signs point inward; every light’s a slow burn.  \nFound my former selves assembled, arguing who goes first—  \nOne was dressed for work; the rest were dressed for his internment.\n\n“Have a seat.” I said, “I live here.” They said, “That remains disputed.”  \nBrought receipts for every grief; the dates were faded, names excluded.  \nOne produced a broken promise, held it up like restitution;  \nI could recognize the handwriting beneath the water ruin.\n\nCross around my neck for those who never made it back;  \nLittle weight against my sternum, heavy names attached.  \nI tend to do what’s wrong when the time is right—  \nNow my watch keeps perfect time in a room without a night.\n\n[Hook — rapped]\n\nDead souls—who the fuck gave you keys?  \nSame floor, same door, pacing in me.  \nHands on the clock locked; mine won’t rest—  \nEverybody talks with my voice in this chest.  \nGet out—then I recognize the face.  \nGet out—then it tells me, “Know your place.”  \nLost in the maze I made, counting each breath—  \nI’m still here. You don’t get to call that death.\n\n[Verse 2]\n\nFifth wife—same woman that I married for the first time;  \nFive revisions of a face I couldn’t read between the hurt lines.  \nEvery version swore the previous edition had been lying;  \nI kept editing the portrait, called the finished picture “trying.”\n\nSaid I never took the bait—I only nibbled at the middle;  \nSplit a little off the hook and put the blame upon the riddle.  \n“Who could know?” Well, I could. That’s the part I kept omitted:  \nSaw the filament against the light and bit until it glittered.\n\nPast mistakes, past takes—paste another face across it;  \nChange the tense, expense the loss, then frame the page as progress.  \nWhite lies bleed red when you lean against the gauze;  \nI was pressing for an answer, never pausing for the cause.\n\nPlant your seeds where vultures feed, complain about the harvest;  \nKeep a garden full of grievances and wonder why it’s starving.  \nI mistook the things I’d given for a claim on what she owed;  \nNow I’m digging through the soil for a receipt that never grows.\n\n[Hook — rapped]\n\nDead souls—who the fuck gave you keys?  \nSame floor, same door, pacing in me.  \nHands on the clock locked; mine won’t rest—  \nEverybody talks with my voice in this chest.  \nGet out—then I recognize the face.  \nGet out—then it tells me, “Know your place.”  \nLost in the maze I made, counting each breath—  \nI’m still here. You don’t get to call that death.\n\n[Bridge — drums drop; close, restrained]\n\nHear it in the distance.  \nCalling me by name.  \nPretend I didn’t hear it.\n\nIt comes closer all the same.\n\nFeel it in my fingers.  \nNails against my skin.  \nHow’s it knocking at the door  \nWhen I already let it in?\n\n[Verse 3]\n\nNeedle drops—the room repeats a second I remember;  \nLittle fleck of dust decides I’m living in December.  \nLift the arm. The silence hits. I almost drop it back—  \nFunny what becomes familiar when your life conforms to that.\n\nFound a box of folded verses underneath the floorboards;  \nEvery page a room I’d left, then nailed another door toward.  \n“Born with a black heart”—that’s the verdict in the first draft;  \nFunny, I was hurt enough to write it. Let me circle that.\n\nAll these “unthings,” unfinished—unforgiven, unaddressed;  \nEach abandoned sentence sent another tenant up the steps.  \nNow they’re lined around the table with their elbows in my dinner;  \nOne says, “You were better then.” I ask him which of us remembers.\n\nI begin to befriend who I really am—he’s hard to sit with;  \nKeeps correcting all my stories at the parts I made him missing.  \nLeave the dead their names; I cross out where they signed for me—  \nThen I hear the clock. One tick. Nobody agrees.\n\n[Final Hook — rapped, firmer]\n\nDead souls—who the fuck gave you keys?  \nSame floor, same door, pacing in me.  \nHands on the clock move; mine still shake—  \nEverybody wants the last word when I wake.  \nSit down. I can recognize the face.  \nSit down. You don’t get to run the place.  \nLost in the maze I made, marking where I’ve been—  \nI’m still here. Let the fucking record spin.", "suno": {"title": "Under The Floorboards", "lyrics": null, "style": "", "exclude": ""}, "header": "", "chars": 4405}], "title": "Under The Floorboards", "session": "Oct 8 Reset", "latest": "under-the-floorboards_v01_Misc"}, {"slug": "who-ive-always-been", "ep": false, "versions": [{"stem": "who-ive-always-been_v03_Cue", "version": 3, "writer": "Cue", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "Who I've Always Been", "lyrics": "[Intro: piano alone, two bars, then the break]\n\n[Verse 1]\nLet me make it clear, 'cause it's been sitting in my chest:\nI'll own the things I did. I won't sign for the rest.\nI said cruel shit. I meant it when I said it. That's on me.\nBlocked the chat when you went quiet, deleted it, and called it grief.\nMade a slideshow out of grievances and walked it in like a case;\nSome of what I did made you feel unheard, alone, erased.\nI can hold that. That's the weight of what I did. I'll carry it home.\nGive me a list of what I did, I'll sign it, every line, in my own\nHandwriting. Give me a list of who I am, I'll hand it back. That ain't mine.\n[double-time] The words that I said, the slides that I made, the chat I deleted, the nights that I didn't hear you, the days that I made it about me, I'll own every one of 'em, sign it in ink,\nBut motives and meanings and what my love was and what kind of man is under the skin, that's a diagnosis you don't get to write, and it ain't yours to think,\n[half-time] Actions? Mine.\n[pause] Character? Also mine.\n\n[Hook: chanted low, doubled]\nTell me how it hurt you. I'll carry that. That's fair.\nTell me who I am? Nah. That ain't yours to declare.\nSpent a year in recovery from a man I never was;\nSame name, same hands, same heart. I'm who I always was.\nTell me how it hurt you. I'll carry that. That's fair.\nTell me who I am? Nah. That ain't yours to declare.\nSpent a year in recovery from a man I never was;\nSame name, same hands, same heart. I'm who I always was.\n\n[Verse 2]\nYou said my love was selfish. You said it was one-sided,\nSaid it made you quit instead of grow. I listened. I tried to find it.\nSpent a year in a fitting room, trying on the man you described:\nNothing fit. Shoulders wrong. Sleeves short. Didn't look like mine.\nYou can tell me how it felt. That's yours. I'll never fight it.\nYou can't tell me what I meant. That's mine. I lived inside it.\nIf I really was that man, it'd be easy to walk away;\nHard part is, I know I ain't. So it hurts every single day.\n[double-time] Selfish, one-sided, enraged, the problem, the villain, the reason, the weight, every adjective handed to me like a bill I was supposed to pay,\nI paid it, I paid it, I paid it a year, I emptied my pockets, I emptied my chest, I emptied the me out of me till there was nothing to weigh,\n[half-time] Then I read the fine print.\n[pause] Never was my signature.\n\n[Hook: chanted low, doubled]\nTell me how it hurt you. I'll carry that. That's fair.\nTell me who I am? Nah. That ain't yours to declare.\nSpent a year in recovery from a man I never was;\nSame name, same hands, same heart. I'm who I always was.\n\n[Verse 3: strings stay, drums hit harder]\nMy world revolved around you for so long, I got dizzy;\nWould've given you anything you asked and never sent a bill. Not stingy,\nNot selfish. Call it foolish, maybe. I can live with that one.\nI'm the dad at every pickup that I'm able to make, the one\nWho carries whatever I can carry, the one who stays,\nThe one who works the late shift, then comes home and works some more for days.\nI got flaws. I got a list. I got some things I'd take back;\nI'm still not the man you keep describing. I'm done trying to convince you of that.\n[double-time] Same name, same hands, same heart, same pen, same father, same son, same Air Force tag in the drawer and the same Guam in the blood in my veins,\nSame kid from the demo in Washington writing in a binder, the same man in the mirror tonight, and I'm calling him all of his names,\n[half-time] I'm done trying to convince you.\n[pause] I just had to convince me.\n\n[Final Hook: full beat, chanted, doubled]\nTell me how it hurt you. I'll carry that. That's fair.\nTell me who I am? Nah. That ain't yours to declare.\nQuit the year of recovery from a man I never was;\nWasn't sick. Wasn't him. I'm who I always was.\nTell me how it hurt you. I'll carry that. That's fair.\nTell me who I am? Nah. That ain't yours to declare.\nQuit the year of recovery from a man I never was;\nWasn't sick. Wasn't him. I'm who I always was.", "suno": {"title": "Who I've Always Been", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 90 BPM, grounded swung drum break, hard cracking snare, somber minor-key piano loop, low strings swelling under the hook, deep upright bass, vinyl crackle, narrow smoky mix; male mid-low rap, firm and unbowed, dense multisyllabic internal rhymes, relaxed pocket into double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v03. October 8, 2026. Writer: Cue (Claude). Concept and source phrases: Scatta (your May 14 and July 8, 2026 messages, via the Studio Launch source file). Status: written listening candidate, unauditioned and unapproved.", "chars": 4020}], "title": "Who I've Always Been", "session": "Oct 8 Reset", "latest": "who-ive-always-been_v03_Cue"}, {"slug": "you-cant", "ep": false, "versions": [{"stem": "you-cant_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 8 Reset", "folder": "2026-10-08-Reset", "title": "You Can't", "lyrics": "[Intro: drums and a cold piano figure, two bars]\n\n[Verse 1]\nSince twenty-eleven I been majoring in one woman,\nMinoring in patience, front row, never missed a lecture, hunting\nEvery hint of what she wanted, every tilt of every sentence,\nTook notes on the silences. I had perfect attendance.\nI loved her without question, more than anybody, by far;\nI would not change her for anybody, not for money, not for stars.\nCould've bought the Bitcoin back when it was change in the couch;\nI'd have traded every coin for the noise in that house.\nI thought I hit the lottery and never had to cash it:\nBlessed and lucky, best life on the planet, and I had it.\n[double-time] How she took her coffee, which side of the bed, what song made her cry in the car,\nWhich look meant leave it, which look meant fix it, which look meant hold me, I memorized every scar,\n[half-time] I knew her better than I knew myself.\n[pause] That was the problem. Nobody was studying me.\n\n[Hook: rapped low, doubled on \"You can't\"]\nWhat's he got that I ain't got? You can't.\nHow do I get there? You can't.\nSince twenty-eleven with the workbooks in my hands,\nEvery page highlighted, and the answer key says, \"You can't.\"\n\n[Verse 2]\nThen she checked out. I kept checking in at the front desk,\nRinging the little bell for a room that's already been reset.\n\"Who are you?\" I asked it more than once, and meant it;\nSame face, new tenant, and I'm the fool still paying rent in it.\nBought the psychiatry workbooks, did the blanks in pencil,\nErased myself so many times the page went thin as a stencil.\nThen the proof hit my phone: the pictures, texts, the video;\nI'd been grieving it for months, so it landed kinda slow.\nAnd I stayed. Still tried. Told her I'd forgive it,\nNot just for us, for the kids, so they ain't grow up in the middle of it.\n[double-time] Therapy Tuesday, the workbook Wednesday, apology Thursday, gone by the weekend,\nRead every chapter on attachment, I attached to every reason, I was bleeding and believing,\n[half-time] Then I asked the only question left.\n[pause] Should've let it stay a question.\n\n[Hook: rapped low, doubled on \"You can't\"]\nCan I fix it if I fix me? You can't.\nCan we fix it if I forgive? You can't.\nSince twenty-eleven with the workbooks in my hands,\nEvery page highlighted, and the answer key says, \"You can't.\"\n\n[Verse 3: drums thin out, piano and bass stay]\nSitting on the edge of our bed like a waiting room,\nI said, \"What does he do that I don't? Teach me. I'll study you.\"\nShe said he understood her more than anybody in her whole life;\nI said, \"How do I get there?\" \"You can't.\" She said it twice,\nCalm, like telling a kid the dog ain't coming home tonight.\nTwo words. All them years of homework, never graded, just returned,\nWith a note across the top in her handwriting: never learned.\nI know it don't define my worth; I know that in my head.\nMy chest ain't got the memo. It still flinches like it's said.\n[double-time] I can't be him, can't unsee it, can't unlearn it, can't unring it, can't unread the texts,\nCan't unbuy the workbooks, can't unsign the papers, can't unlove the years, can't unforgive the rest,\n[half-time] Okay. You're right.\n[pause] I can't.\n\n[Final Hook: beat back hard, chanted, doubled]\nYou're right. I can't. I can't.\nI can't be him, and I can't be the man you planned.\nSince twenty-eleven with the workbooks in my hands,\nClosed the book, left it on the desk. I'm done raising my hand.", "suno": {"title": "You Can't", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 88 BPM, swung acoustic drum break, hard cracking snare, cold minor-key vintage piano loop, deep upright bass, vinyl crackle, narrow smoky mix; male mid-low rap, wounded menace, dry dark humor, dense multisyllabic internal rhymes, relaxed pocket into double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 8, 2026. Writer: Cue (Claude). Concept and source phrases: Scatta (97 NEW notes). Status: written listening candidate, unauditioned and unapproved.", "chars": 3417}], "title": "You Can't", "session": "Oct 8 Reset", "latest": "you-cant_v01_Cue"}, {"slug": "another-day-another-misunderstanding", "ep": false, "versions": [{"stem": "another-day-another-misunderstanding_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 9 Lyric Mine", "folder": "2026-10-09-Lyric-Mine", "title": "Another Day, Another Misunderstanding", "lyrics": "[Intro: an alarm clock clicks on, radio static sweeps, the loop starts]\n\n[Verse 1]\nAugust '22, the alarm goes off: same song, same day.\nWake up, plans change on me, \"which is fine,\" okay.\n\"Which is fine.\" I typed it twice in one message, unprovoked;\nFine's the word you use when there's a knife in the throat and you're choked.\nThen I called you rude. Took it back. Explained it. Didn't matter.\nPut quotation marks around \"misunderstanding,\" sarcastic as a dagger:\nAir quotes in a text, the loudest thing a quiet man can yell.\n\"Another wasted day. Another day of sorrow.\" Ring the bell.\nTyped it like a forecast: sorrow, ninety percent, with a chance of doubt;\nSame front coming through tomorrow. Same storm. Same drought.\n[double-time] Wake up, I love you, the plans change, it's fine, so I wait, then you're busy, it's fine, so I offer a ride and I'm rude, so I'm sorry, I take it right back, and it's not enough sorry, it's never enough, so I'm sorry again,\nAnd the sun goes down on the same argument the sun came up on, I set the alarm for the morning, and morning's the same as the morning before it, again and again,\n[half-time] Another day.\n[pause] Same day.\n\n[Hook: chanted hard, doubled]\nAnother day, another misunderstanding.\nAnother wasted day. Another day of sorrow. Same landing.\nTwenty-seven times I typed it, twenty-twenty to today:\nMiscommunication. Same day. Different year. Same day.\nAnother day, another misunderstanding.\nAnother wasted day. Another day of sorrow. Same landing.\nTwenty-seven times I typed it, twenty-twenty to today:\nMiscommunication. Same day. Different year. Same day.\n\n[Verse 2]\nTwenty-four: twelve misunderstandings, one a month like rent.\nPaid it on the first; by the fifteenth, all of it was spent.\nJuly ninth, I broke it down like a tech at the bench:\n\"Two sides of communication.\" Transmitter. Receiver. Wrench.\nIt \"wasn't received or sent on the correct frequency\":\nTwo radios in one house, both transmitting, nobody receiving. See,\n\"I am listening, reading and interpreting\" to the best of my abilities,\nRunning diagnostics on a sentence, ruling out the possibilities.\n\"Another day another misunderstanding.\" No quotes this time. No sarcasm.\nJust tired. Like a man reporting weather from inside the chasm.\n[double-time] Check the antenna, the cable, connector, the ground, the impedance, the noise floor, the gain and the squelch, turning the knob a degree at a time for a voice in the hiss,\nAnd I hear you, I swear that I hear you, I'm hearing the words, it's the meaning that's lost between towers, a signal that leaves as a \"sorry\" and lands as a diss,\n[half-time] Another misunderstanding.\n[pause] Twelfth one this year.\n\n[Hook: chanted hard, doubled]\nAnother day, another misunderstanding.\nAnother wasted day. Another day of sorrow. Same landing.\nTwenty-seven times I typed it, twenty-twenty to today:\nMiscommunication. Same day. Different year. Same day.\n\n[Verse 3: piano loop skips, static rises]\nFirst one, twenty-twenty, May: \"Miscommunication.\" No period.\nLast one, '26, September: \"Miscommunication.\" Period. Serious.\nSix years, twenty-seven times, same word, same weight;\nOnly thing that ever changed is I learned to punctuate.\nSeparate houses, papers served, and still the static's coming through:\nI said Friday from her house; Friday landed at the school.\nSo this is how it ends? Not a bang. Not a slammed door.\nJust a pickup time misheard, like the thousand times before.\nSame alarm, same song, same day, a different calendar year,\nAnd the one thing I can promise you: tomorrow it'll still be here.\n[double-time] Another day, another pickup, another drop-off, another \"I meant,\" another \"I thought that you said,\" another relay through a kid with a phone in her hand,\nTwenty-twenty to twenty-six, twenty-seven times, a marriage, a house, and a lawyer, a planner, a calendar, and still we can't land the plane where we planned,\n[half-time] Miscommunication.\n[pause] Period.\n\n[Final Hook: chanted hard, doubled, then the loop cuts mid-bar]\nAnother day, another misunderstanding.\nAnother wasted day. Another day of sorrow. Same landing.\nTwenty-seven times I typed it, twenty-twenty to today:\nMiscommunication. Period. The end. Same day.\nAnother day, another misunderstanding.\nAnother wasted day. Another day of sorrow. Same landing.\nTwenty-seven times I typed it, twenty-twenty to today:\nMiscommunication. Same day. Different year. Same day.", "suno": {"title": "Another Day, Another Misunderstanding", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 91 BPM, hard looping drum break that never changes, dry snare, hypnotic two-bar minor-key piano loop like a stuck record, radio static and tuning sweeps, alarm clock click, deep dusty bass, vinyl crackle, raw mix; male mid-low rap, weary sardonic delivery building to frustration, dense internal rhymes, rapid double-time bursts, hard chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 9, 2026. Writer: Cue (Claude). Concept and hook phrase: Scatta (#034973, August 12, 2022, and #064741, July 9, 2024; Lyric Mine). Status: written listening candidate, unauditioned and unapproved.", "chars": 4399}], "title": "Another Day, Another Misunderstanding", "session": "Oct 9 Lyric Mine", "latest": "another-day-another-misunderstanding_v01_Cue"}, {"slug": "backups", "ep": false, "versions": [{"stem": "backups_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 9 Lyric Mine", "folder": "2026-10-09-Lyric-Mine", "title": "Backups", "lyrics": "[Intro: a hard drive clicks, spins up, whines, then the break]\n\n[Verse 1]\nTwenty-twenty: \"You should always have back ups.\"\nTwo alarms on the nightstand, 'cause the first one's just a rough draft.\nTwenty-two: \"How many times have I told you? Back your stuff up.\"\nEvery hard drive dies; that's the gospel. Ashes to dust. Uh.\nI'm the deacon of redundancy, the preacher of off-site:\nMirror the mirror, copy the copy, then copy it twice. Alright.\nBought the terabytes in pairs: \"lmk if you need more.\"\nI backed up every phone in the house and every password in the drawer.\nData-hoarder? Say it louder. Lost a drive once, never again.\nFelt that panic in the gut like a funeral without a friend.\n[double-time] Birthdays and baby teeth, beach days and Christmas mornings, the first days of school and the last days of summer, the scans and the receipts and the cards, every single version saved,\nLabeled by date in a folder in a folder in a folder, a Russian doll of a marriage, a cathedral of storage, a vault for the life that we made,\n[half-time] Nothing gets lost.\n[pause] That was the plan.\n\n[Hook: chanted hard, doubled]\nAll hard drives fail eventually.\nOne backup, one off-site, or you're not safe.\nTwo hundred twenty-six folders, every text we ever sent, I hold.\n\"Restore from backup?\" Unavailable. This version's too old.\nAll hard drives fail eventually.\nOne backup, one off-site, or you're not safe.\nTwo hundred twenty-six folders, every text we ever sent, I hold.\n\"Restore from backup?\" Unavailable. This version's too old.\n\n[Verse 2]\nMarch of '25, I'm sitting with the trash can icon,\nDragging us in a few at a time like I'm cutting my own lifeline.\n\"Are you sure?\" Am I sure? Nah. Click it anyway.\nI can only do it for a while, then I gotta walk away.\nTwelve, fifteen pictures in, and my hands start to shake;\nClose the laptop like a casket. Open it the next night like a wake.\n\"Recently Deleted\" holds 'em thirty days: digital purgatory,\nEvery smile in the waiting room, and I'm the priest and the jury.\nMost important thing I ever owned, and I'm the one throwing it out,\nLike a hoarder at his own estate sale, putting price tags on the house.\n[double-time] Select all, no, select some, select the ones where we're smiling, the beach and the kitchen, the van and the wedding, no, not that one, the kids are in that one, deselect,\nMove to trash, are you sure, this cannot be undone, empty trash, are you sure, are you sure, and the screen keeps on asking like it knows what I'd rather protect,\n[half-time] Thirty days.\n[pause] To change my mind.\n\n[Hook: chanted hard, doubled]\nAll hard drives fail eventually.\nOne backup, one off-site, or you're not safe.\nTwo hundred twenty-six folders, every text we ever sent, I hold.\n\"Restore from backup?\" Unavailable. This version's too old.\n\n[Verse 3: piano drops out, drive whine and drums only]\nOctober '24, you cleared the chat, the whole history, gone,\nAnd I laughed like a villain: \"You know I got back ups and back ups.\" Come on.\nTwo hundred twenty-six folders, every text we ever had,\nUnedited HTML and JSON, the good shit and the bad.\nThat's the sick part, the part I snicker at alone at night:\nYou can't delete a man who mirrored every hard drive in his life.\nSo I did the thing a hoarder never does: I opened it up.\nEighty-one thousand messages. Read every broken one.\nPulled the bars out of the wreckage like the copper from a burned house.\nThis album is the off-site backup. Y'all are the cloud now.\n[double-time] Eight years of good mornings, good nights, turn on location, I'm sorry, I love you, the grocery lists, the fights at four o'clock and the endings that never would end,\nCompressed in a zip on a drive in a safe in a song in your ears, so if the house and the cloud and the server all burn, you can press it and play it again,\n[half-time] Redundancy.\n[pause] That's all a song is.\n\n[Final Hook: chanted hard, doubled]\nAll hard drives fail eventually.\nOne backup, one off-site, or you're not safe.\nTwo hundred twenty-six folders, every text we ever sent, I hold.\n\"Restore from backup?\" Not us. Just me. This version holds.\nAll hard drives fail eventually.\nOne backup, one off-site, or you're not safe.\nTwo hundred twenty-six folders, every text we ever sent, I hold.\n\"Restore from backup?\" Unavailable. This version's too old.", "suno": {"title": "Backups", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 90 BPM, hard dusty drum break, crisp dry snare, cold minor-key piano loop, hard drive click and spin-up whine textures, warm distorted bass, faint tape hiss, vinyl crackle, raw mix; male mid-low rap, dry sardonic confessional delivery, dense multisyllabic internal rhymes, rapid double-time list bursts, hard chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 9, 2026. Writer: Cue (Claude). Concept: Scatta (Lyric Mine, \"Backups\"; your backup and data messages 2020 to 2025, #037418, #068673, #076644, #078659). Status: written listening candidate, unauditioned and unapproved.", "chars": 4294}], "title": "Backups", "session": "Oct 9 Lyric Mine", "latest": "backups_v01_Cue"}, {"slug": "becoming", "ep": false, "versions": [{"stem": "becoming_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 9 Lyric Mine", "folder": "2026-10-09-Lyric-Mine", "title": "Becoming", "lyrics": "[Intro: a cassette rewinds, clicks, hiss, then the piano and drums]\n\n[Verse 1]\n\"The last two years have been the hardest of my life.\" No metaphor:\n\"More pain in that time than in the first forty years combined.\" Let it pour.\nGraph it like a monitor: forty years of a steady line,\nThen a spike so tall it clipped the screen and set the alarm off every time.\nBroke in ways I didn't know a person could break,\nLike a bone you didn't know you had until it snaps. Then it aches\nIn weather. Every storm, I feel the fracture in the fault line.\nI'm a seismograph of us, every tremor logged with a timeline.\nBut I learned. God, I learned. Not from a book, from the floor:\nLying flat in the dark is a classroom, if you can't find the door.\n[double-time] Learned more about myself, about people, relationships, the mind, spirituality, philosophy, what actually matters to me, in two years of pain than in forty of living,\nLearned that the caring's a gift and a curse, that the giving don't guarantee getting, the trying don't promise a thing, and the healing is something nobody's giving,\n[half-time] I broke.\n[pause] Then I rebuilt.\n\n[Hook: chanted, doubled, building]\nYou may never see me for who I actually am.\nI don't think I can change that anymore. Understand:\nI can only keep becoming the person I know I am.\nPiece by piece. Every choice. Every mistake. I am.\nYou may never see me for who I actually am.\nI don't think I can change that anymore. Understand:\nI can only keep becoming the person I know I am.\nPiece by piece. Every choice. Every mistake. I am.\n\n[Verse 2]\n\"I went back through my whole life as honestly as I could\":\nEvery choice, every mistake, every intention. Knock on wood.\nOpened up the notebooks from '99, the ink, the teenage dread,\nSome kid who called his own heart black before it ever even bled.\nOpened up the archive: eighty-one thousand messages, eight years,\nRead 'em like an autopsy, every \"sorry,\" every \"lol,\" every tear.\nRead the drafts of who I was like a tech reads a service log:\nEvery fault, every fix, every part replaced, every fog.\n\"And I realized I am not the person I spent so long believing I was.\"\nNot the black heart. Not the demon. Not the saint. Just the cause\n[double-time] Of a lot of good and a little bad and a lot of trying, a man who was wrong about himself for forty years, and who spent the last two finding out with a pen and a beat and a box of old tapes in a closet,\nWho wrote it all down, every bar, every bruise, every bill, every night, every kid at the table, and found the guy under the floor of the house, and he's breathing, and nobody lost it,\n[half-time] Not who I believed I was.\n[pause] Better.\n\n[Hook: chanted, doubled, building]\nYou may never see me for who I actually am.\nI don't think I can change that anymore. Understand:\nI can only keep becoming the person I know I am.\nPiece by piece. Every choice. Every mistake. I am.\n\n[Verse 3: strings swell, the piano brightens a half step]\n\"I am not perfect, but I know my heart.\" Say that on a mic.\nSay it to the mirror. Say it to the girls. Say it on the drive at night.\n\"I have spent most of my life caring, giving, and trying,\nEven when I didn't know how to care for myself.\" I'm not lying.\nThat's the line that broke me when I read it back: the caring for everybody,\nForty-three years of a man carrying the house and never once the body.\nSo this is me, carrying me. Late. Clumsy. Out of practice.\nLike a man learning to cook for one, burning the first few, laughing at it.\nAnd if you never see me for who I am, then that's yours to keep;\nI'm done arguing my case to a jury that's asleep.\n[double-time] I'm the kid with the scatter in the skull and the tech with the meter, the dad with the cart and the man with the boxes, the MC with the notebook, the one who kept trying, and the one who's still here,\nAnd I'm becoming, not became, not done, not finished, not fixed, not a statue, not saint and not demon, a man at eye level, a verb, not a noun, and the picture is clear,\n[half-time] I can only keep becoming\n[pause] the person I know I am.\n\n[Final Hook: chanted, doubled, full and open, then the tape clicks off]\nYou may never see me for who I actually am.\nI don't think I can change that anymore, and I'm fine with that. I am.\nI can only keep becoming the person I know I am.\nPiece by piece. Every choice. Every mistake. I am.\nYou may never see me for who I actually am.\nI don't think I can change that anymore. Understand:\nI can only keep becoming the person I know I am.\nPiece by piece. Every choice. Every mistake. I am.", "suno": {"title": "Becoming", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 90 BPM, heavy dusty drum break, crisp dry snare, grave minor-key piano loop that slowly brightens, swelling strings, distant tape rewind and old cassette hiss textures, deep warm bass, vinyl crackle, cinematic raw mix; male mid-low rap, steady resolute confessional delivery, dense multisyllabic internal rhymes, rapid double-time bursts, chanted anthem hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 9, 2026. Writer: Cue (Claude). Concept and hook: Scatta (\"I can only keep becoming the person I know I am.\" #080762, 9:49 p.m., May 16, 2026; Lyric Mine, \"album mission statement\"). Built as a closer. Status: written listening candidate, unauditioned and unapproved.", "chars": 4539}], "title": "Becoming", "session": "Oct 9 Lyric Mine", "latest": "becoming_v01_Cue"}, {"slug": "boxes", "ep": false, "versions": [{"stem": "boxes_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 9 Lyric Mine", "folder": "2026-10-09-Lyric-Mine", "title": "Boxes", "lyrics": "[Intro: a tape gun screams across a box, the sound echoes in an empty room]\n\n[Verse 1: KEEP]\nBox one, Sharpie on the side in capital letters: KEEP.\nHard drives first, of course, the backups of the backups, stacked neat.\nThe camera and the lenses, glass I bought when I was rich in time,\nThe test leads and the multimeter, work tools that never lie.\nNotebooks full of verses from a kid in '99, ink faded:\nRhymes about a black heart, a dead soul, and a future he ain't made yet.\nEvery piece of paper that the girls ever drew a face on,\nEvery macaroni frame, every \"Dad\" in crayon that I based my days on.\nKeep's the smallest box, and it's the heaviest one in the house;\nFunny how the things that matter weigh the most and take the least amount.\n[double-time] Bubble wrap around the lenses, a towel around the drives, and the notebooks in a freezer bag in case of a flood, 'cause I'm paranoid, I'm careful, I'm a tech, I'm a dad, I'm a mess,\nAnd I'm packing it all like a medic, the trauma kit, everything sorted by what I would grab if the house was on fire and I had thirty seconds or less,\n[half-time] Keep.\n[pause] Tape it twice.\n\n[Hook: chanted, doubled]\nKeep. Donate. Trash. Tape gun screaming.\nWhole house in three boxes and a fourth one with no meaning.\nDownsize by fifty percent: half the stuff, half the man.\nKeep. Donate. Trash. And the box I can't label in my hand.\nKeep. Donate. Trash. Tape gun screaming.\nWhole house in three boxes and a fourth one with no meaning.\nDownsize by fifty percent: half the stuff, half the man.\nKeep. Donate. Trash. And the box I can't label in my hand.\n\n[Verse 2: DONATE]\nBox two: DONATE. That's the biggest box. Get a bigger one.\n'25, two storage units filled up to the roof. I couldn't figure one\nThing to throw away. \"I feel like throwing it all away.\" I didn't.\nClothes and toys everywhere, the house a landfill with a lease signed in it.\n'26, \"We need to downsize by at least fifty percent.\"\nHouse, basement, garage and shed: the stuff's a tenant paying rent.\nSling bags: three. Pouches: eight. Backpacks I researched for weeks.\nDonate the obsessions; they don't fit in the new place. Or my sleep.\nAnd a kid in the corner flinging boxes across the room,\nLike the boxes did something to her. Honestly, they did. Me too.\n[double-time] Bags of the clothes they outgrew, and the toys that they fought over, then never touched, puzzles with pieces gone missing, a bin with a lid that don't fit, and the cords to devices we threw out in '19,\nEvery receipt for a thing that we bought to feel better, a thing to fix something that wasn't a thing, and I'm loading the van like a hearse for the version of us that was buying to keep from the screaming,\n[half-time] Donate.\n[pause] Somebody else's problem now.\n\n[Hook: chanted, doubled]\nKeep. Donate. Trash. Tape gun screaming.\nWhole house in three boxes and a fourth one with no meaning.\nDownsize by fifty percent: half the stuff, half the man.\nKeep. Donate. Trash. And the box I can't label in my hand.\n\n[Verse 3: TRASH]\nBox three: TRASH, but it ain't trash, that's the problem with the word.\nJuly, I wrote it down: I'm in \"another chapter\" of healing. Third.\n\"Trying to fully detach myself and remove the memories, belongings,\nAnd other things that keep me emotionally connected to you.\" Wrong things,\nRight things, I don't know. A card. A frame. A mug that says \"Mr.\"\nA hoodie in the back of my closet that I can't remember if it's mine. Blister\nOn my palm from the tape gun. The divorce is \"just a piece of paper\nThat lost its true meaning two and a half years ago.\" See you later.\nPacking up the entire house by myself, July heat, August served,\nMom driving up to help me, and the girls home for the summer's last curve.\n[double-time] Into the bag with the bows from a birthday, the plastic flowers, the cards with the hearts and the \"always,\" the \"forever,\" the \"us,\" and the \"we,\" and the stuff with the date of the wedding,\nThen I pull half of it back out and I put it in a box with no name on the side, 'cause I'm not ready to throw it, not ready to keep it, I'm stuck in the middle, a man with a bag and a Sharpie, forgetting,\n[half-time] Trash.\n[pause] Some of it.\n\n[Bridge: drums drop out, tape gun echo]\nBox four don't got a label.\nHalf of it's hers, half of it's mine, all of it's theirs.\nNo idea where I'm living in January.\nSharpie on the side: TBD.\n\n[Final Hook: chanted, doubled, drums return]\nKeep. Donate. Trash. Tape gun screaming.\nWhole house in three boxes and a fourth one with no meaning.\nDownsize by fifty percent: half the stuff, half the man.\nBox four says TBD. Guess that's where I am.\nKeep. Donate. Trash. Tape gun screaming.\nWhole house in three boxes and a fourth one with no meaning.\nDownsize by fifty percent: half the stuff, half the man.\nKeep. Donate. Trash. And the box I can't label in my hand.", "suno": {"title": "Boxes", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 89 BPM, hard dusty drum break, dry snare layered with packing tape rips, cold minor-key piano loop, cardboard thuds and echoing empty-room reverb, deep warm bass, vinyl crackle, raw mix; male mid-low rap, tired methodical delivery with dry dark humor, dense internal rhymes, rapid listing double-time bursts, chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 9, 2026. Writer: Cue (Claude). Concept: Scatta (Seed Bank, \"Boxes\"; #081339, #077688, #080863, #081447, #081569). Status: written listening candidate, unauditioned and unapproved.", "chars": 4817}], "title": "Boxes", "session": "Oct 9 Lyric Mine", "latest": "boxes_v01_Cue"}, {"slug": "but", "ep": false, "versions": [{"stem": "but_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 9 Lyric Mine", "folder": "2026-10-09-Lyric-Mine", "title": "But", "lyrics": "[Intro: a metronome ticks, the beat drops in, stops for half a beat, comes back]\n\n[Verse 1]\nDecember twenty-first, '24, a fight about a row of seats:\nI'm sent down to the other end like the extra napkin with the treats.\nI say what it looked like, I get told I shouldn't assume,\nAnd the word \"assume\" gets put on trial in the living room.\n\"And I am sorry but your views on the words 'assume' and 'but' are wild to me.\"\nRead it back: I used a \"but\" to defend \"but.\" That's comedy.\n\"Everybody assumes in life. To make an educated guess is to assume.\"\nI'm a tech. I assume the fuse is blown before I open up the room.\nNinety-nine point nine nine nine nine nine percent of the time it happens? I bet.\nThen \"BUT (!!!)\" in capitals with three exclamation points. Not done yet.\n[double-time] \"Stop assuming all assumptions are wrong,\" I typed it like a lawyer with a closing, a philosopher with a thumb drive, a scientist in a kitchen arguing the grammar of a war,\n\"If we never made an assumption in life, we would only be able to make decisions based on absolute facts,\" and we wouldn't get out of the bed, we wouldn't get out of the door,\n[half-time] \"Sorry but I hate how you always throw that word around like it's a sin.\"\n[pause] Another \"but.\" Couldn't help it.\n\n[Hook: chanted hard, doubled]\nNo \"assume.\" No \"but.\"\nTwo words in a cage, and the cage door shut.\n\"I'm sorry, but.\" \"I'm trying, but.\" \"I love you, but.\"\nEvery sentence that I had was hanging on a hinge. Cut.\nNo \"assume.\" No \"but.\"\nTwo words in a cage, and the cage door shut.\n\"I'm sorry, but.\" \"I'm trying, but.\" \"I love you, but.\"\nEvery sentence that I had was hanging on a hinge. Cut.\n\n[Verse 2: the beat drops out at every ellipsis]\nFine. A whole verse with the word removed. Watch the gaps:\nI'm sorry... you hurt me too. Listen to the silence where it snaps.\nI tried... nothing worked. I love you... I'm tired.\nEvery hinge pulled off the door, and every door is hanging by a wire.\nI wanted to stay... I'm packing. I forgive you... I remember.\nI'm fine... I'm not. It's August... it feels like December.\nTake the hinge out of a sentence and the sentence falls in half;\nTwo truths that used to hold hands now sit apart in a photograph.\nA man who isn't allowed to say \"and also this is true\"\nIs a man who has to choose: the sorry, or the hurt. Not both. Not you.\n[double-time] So I'm swallowing the hinges, I'm eating the conjunction, I'm biting my tongue at the joint, every thought amputated at the elbow, a sentence with no second half and a gap in the middle that rings,\nLike a phone in an empty house, like a pause in a song where the drummer forgot, like a man who's been told what he's thinking is wrong if he says that he's thinking two things,\n[half-time] I'm sorry.\n[pause] ...\n\n[Hook: chanted hard, doubled]\nNo \"assume.\" No \"but.\"\nTwo words in a cage, and the cage door shut.\n\"I'm sorry, but.\" \"I'm trying, but.\" \"I love you, but.\"\nEvery sentence that I had was hanging on a hinge. Cut.\n\n[Verse 3: full beat back]\nHere's the funny part. I counted. Data never lies:\nThree, four, five \"but\"s every thousand words before the ban. Surprise:\nAfter the ban? Five, six, seven per thousand. Never stopped.\nTen \"assume\"s that one December, every one of 'em defending the crop.\nThe ban made it louder, like a curse word in a church;\nTell a man he can't say \"but\" and every sentence starts to search.\n'Cause \"but\" ain't always an eraser. Sometimes \"but\" is a bridge:\n\"I hurt you, but I'm trying.\" That's a man on a ridge\nHolding both ends of a rope. You want one end? Then I fall.\nLet me keep the hinge. A door with no hinge ain't a door at all.\n[double-time] I'm sorry, but I'm still here, I'm tired, but I'm working, I'm broken, but I'm writing, I'm angry, but I'm calm, I was wrong, but I wasn't the only one wrong in the room,\nI'm divorced, but I'm a father, I'm alone, but I ain't lonely every night, I assumed you would stay, but I was wrong, so I'll never again assume,\n[half-time] But.\n[pause] Still my favorite word.\n\n[Final Hook: chanted hard, doubled]\nNo \"assume.\" No \"but.\"\nTwo words in a cage, and I kicked the cage door. Shut\nUp about \"I'm sorry, but.\" I'm sorry. And. But.\nEvery sentence that I have is hanging on a hinge. It's what I got.\nNo \"assume.\" No \"but.\"\nTwo words in a cage, and the cage door shut.\n\"I'm sorry, but.\" \"I'm trying, but.\" \"I love you, but.\"\nEvery sentence that I had was hanging on a hinge. Cut.", "suno": {"title": "But", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 92 BPM, hard dusty drum break with sudden half-beat dropouts, dry rimshot snare, sardonic minor-key piano stabs, ticking metronome texture, deep round bass, vinyl crackle, raw mix; male mid-low rap, sharp argumentative delivery with dry dark wit, dense multisyllabic internal rhymes, clipped pauses, rapid double-time bursts, hard chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 9, 2026. Writer: Cue (Claude). Concept: Scatta's banned words (\"assume\" and \"but\"; #073556 to #073559, December 21, 2024; Lyric Mine craft note \"The No-But Verse\"). Status: written listening candidate, unauditioned and unapproved.", "chars": 4396}], "title": "But", "session": "Oct 9 Lyric Mine", "latest": "but_v01_Cue"}, {"slug": "car-cart", "ep": false, "versions": [{"stem": "car-cart_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 9 Lyric Mine", "folder": "2026-10-09-Lyric-Mine", "title": "Car-Cart", "lyrics": "[Intro: a squeaky cart wheel, a store intercom chime, then the break]\n\n[Verse 1]\nSaturday, the oldest wants Target and Plato's, the youngest wants Home Depot.\nI do not want to go to Home Depot at all. We go. Let's go.\n'Cause she wants to ride in the car-cart, the plastic car on the front,\nA forty-three-year-old man steering a minivan made of plastic through lumber. The stunt\nIs I'm happy. Don't tell nobody. Aisle nine, the bolts and the hinges;\nShe's honking a horn that don't work and I'm saying \"beep beep\" like it's business.\nWinter: one of 'em helped me shovel snow, and it killed every bit of my energy;\nDeal was, she shovels, I take her to the store. Fair trade. That's the remedy.\nUp at eight, pancakes, then I cleaned till ten at night, no break;\nLess than five minutes on my phone all day. Ask me how much that takes.\n[double-time] Pancake batter, a spatula, syrup, a fight about who gets the first one, a mop and a broom and a laundry pile taller than the youngest, the dishwasher, trash bags, a vacuum, a shoe in the hall,\nThen a drive to the store as a payment for snow, and a cart with a car on the front, and the horn and the \"beep beep,\" the wheel with the squeak, and the man who didn't want to go there at all,\n[half-time] Didn't want to go.\n[pause] Went anyway.\n\n[Hook: chanted, doubled]\nI do not want to go to Home Depot at all.\nShe wants to ride in the car-cart, so we go. That's all.\nLearn it first, then teach it, three hours at the table.\nAin't the perfect father. I'm the one who's there and able.\nI do not want to go to Home Depot at all.\nShe wants to ride in the car-cart, so we go. That's all.\nLearn it first, then teach it, three hours at the table.\nAin't the perfect father. I'm the one who's there and able.\n\n[Verse 2]\nMath homework, night time: \"I had to learn it before teaching her.\"\nThree hours at the kitchen table. \"Even then I struggled.\" Reaching her\nTook me learning fractions like a second language at forty-two,\nYouTube on the laptop, pencil in my teeth, like I'm back in school too.\nYear before, the other one: \"math homework I ain't never even learned before.\"\nGot a hundred percent. I was prouder than the kid. I swore\nI'd frame it. Didn't. Lost it, probably. ScattaBrain.\nAnd the rule: \"I can do this for her in five minutes,\" plain,\n\"But she's not going to learn anything and will expect me to do it next time.\"\nSo I sit on my hands like a man on a bomb. Let her climb.\n[double-time] And the youngest is learning the microwave, thirty seconds, a beep and a bowl and a burn on the tongue, she's making her own food, and I'm proud like she landed a plane,\nAnd when she gets mad, I get right in her grill with an angry face, staring, not blinking, like a pit bull, a statue, a cop, and she cracks up, she can't help it, she's laughing again,\n[half-time] Works every time.\n[pause] Almost every time.\n\n[Hook: chanted, doubled]\nI do not want to go to Home Depot at all.\nShe wants to ride in the car-cart, so we go. That's all.\nLearn it first, then teach it, three hours at the table.\nAin't the perfect father. I'm the one who's there and able.\n\n[Verse 3: horns drop out, piano and drums only]\nApril '25, I said the hardest thing a dad can say:\nSat 'em down and told 'em I was sorry for my behavior yesterday.\n\"I told them what I did was not OK.\" That's in writing. That's on me.\nA father on his knees in the living room with his own apology.\nThen January '26, a mess I didn't see coming at all;\n\"I sat all three down at the table and I told them that nobody was in trouble.\" Called\nIt court with no judge: \"I just wanted to hear their story.\" No yelling.\nThree girls at a table, three stories, and their father just listening. Telling.\nCouple days later, a talk with one of 'em that flipped her whole week around:\n\"As a Father... as a mentor and a teacher.. this is one of my proudest moments.\" Sound.\n[double-time] I ain't the dad from the movies, I'm tired, I'm broke, I'm a mess with a calendar app and a cart with a squeak, and I yelled once and I said that I'm sorry and meant it and wrote it,\nBut I'm here at the table and here at the store and here at the bus stop, here at the concert, here with the pencil and here with the pancakes, the horn and the beep, and I'm here, and I know it,\n[half-time] Beep beep.\n[pause] Let's go.\n\n[Final Hook: chanted, doubled]\nI do not want to go to Home Depot at all.\nShe wants to ride in the car-cart, so we go. That's all.\nNobody's in trouble. Tell me your story at the table.\nAin't the perfect father. I'm the one who's there and able.\nI do not want to go to Home Depot at all.\nShe wants to ride in the car-cart, so we go. That's all.\nLearn it first, then teach it, three hours at the table.\nAin't the perfect father. I'm the one who's there and able.", "suno": {"title": "Car-Cart", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 89 BPM, dusty hard drum break, dry snare, soulful minor-key piano and muted horn loop, squeaky shopping cart wheel and store intercom textures, deep warm bass, vinyl crackle, raw mix; male mid-low rap, tired warm deadpan delivery with dark humor, dense internal rhymes, rapid double-time bursts, chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 9, 2026. Writer: Cue (Claude). Concept: Scatta's dad lines (Lyric Mine, \"Dad lines\"; #079722, #079840, #078749, #080093, #079073, #079183, #077635). Status: written listening candidate, unauditioned and unapproved.", "chars": 4740}, {"stem": "car-cart_v02_Cue", "version": 2, "writer": "Cue", "session": "Oct 9 Lyric Mine", "folder": "2026-10-09-Lyric-Mine", "title": "Car-Cart", "lyrics": "[Intro: a squeaky cart wheel, a store intercom chime, then the break]\n\n[Verse 1]\nSaturday, the oldest wants Target and Plato's, the youngest wants Home Depot.\nI do not want to go to Home Depot at all. We go. Let's go.\n'Cause she wants to ride in the car-cart, the plastic car on the front,\nA forty-three-year-old man steering a minivan made of plastic through lumber. The stunt\nIs I'm happy. Don't tell nobody. Aisle nine, the bolts and the brackets;\nShe honks a horn that don't work, I say \"beep beep\" like it's a racket.\nWinter: one of 'em helped me shovel snow, and it killed every bit of my energy;\nDeal was, she shovels, I take her to the store. Fair trade. That's the remedy.\nUp at eight, pancakes, then I cleaned till ten at night, no break;\nLess than five minutes on my phone all day. Ask me how much that takes.\n[double-time] Pancake batter, a spatula, syrup, a fight about who gets the first one, a mop and a broom and a laundry pile taller than the youngest, the dishwasher, trash bags, a vacuum, a shoe in the hall,\nThen a drive to the store as a payment for snow, and a cart with a car on the front, and the horn and the \"beep beep,\" the wheel with the squeak, and the man who didn't want to go there at all,\n[half-time] Didn't want to go.\n[pause] Went anyway.\n\n[Hook: chanted, doubled]\nI do not want to go to Home Depot at all.\nShe wants to ride in the car-cart, so we go. That's all.\nLearn it first, then teach it, three hours at the table.\nAin't the perfect father. I'm the one who's there and able.\nI do not want to go to Home Depot at all.\nShe wants to ride in the car-cart, so we go. That's all.\nLearn it first, then teach it, three hours at the table.\nAin't the perfect father. I'm the one who's there and able.\n\n[Verse 2]\nMath homework, night time: \"I had to learn it before teaching her.\"\nThree hours at the kitchen table. \"Even then I struggled.\" Reaching her\nTook me learning fractions like a second language at forty-two,\nYouTube on the laptop, pencil in my teeth, like I'm back in school too.\nYear before, the other one: \"math homework I ain't never even learned before.\"\nGot a hundred percent. I was prouder than the kid. I swore\nI'd frame it. Didn't. Lost it, probably. ScattaBrain.\nAnd the rule: \"I can do this for her in five minutes,\" plain,\n\"But she's not going to learn anything and will expect me to do it next time.\"\nSo I sit on my hands like a man on a bomb. Let her climb.\n[double-time] And the youngest is learning the microwave, thirty seconds, a beep and a bowl and a burn on the tongue, she's making her own food, and I'm proud like she landed a plane,\nAnd when she gets mad, I get right in her grill with an angry face, staring, not blinking, like a pit bull, a statue, a cop, and she cracks up, she can't help it, she's laughing again,\n[half-time] Works every time.\n[pause] Almost every time.\n\n[Hook: chanted, doubled]\nI do not want to go to Home Depot at all.\nShe wants to ride in the car-cart, so we go. That's all.\nLearn it first, then teach it, three hours at the table.\nAin't the perfect father. I'm the one who's there and able.\n\n[Verse 3: horns drop out, piano and drums only]\nApril '25, I said the hardest thing a dad can say:\nSat 'em down and told 'em I was sorry for my behavior yesterday.\n\"I told them what I did was not OK.\" That's in writing. That's on me.\nA father on his knees in the living room with his own apology.\nThen January '26, a mess I didn't see coming at all;\n\"I sat all three down at the table and I told them that nobody was in trouble.\" Called\nIt court with no judge: \"I just wanted to hear their story.\" No shouting.\nThree girls at a table, three stories, and a father listening, no doubting.\nCouple days later, a talk with one of 'em that turned her whole week around:\n\"As a Father... as a mentor and a teacher.. this is one of my proudest moments.\" Wrote it down.\n[double-time] I ain't the dad from the movies, I'm tired, I'm broke, I'm a mess with a calendar app and a cart with a squeak, and I yelled once and I said that I'm sorry and meant it and wrote it,\nBut I'm here at the table and here at the store and here at the bus stop, here at the concert, here with the pencil and here with the pancakes, the horn and the beep, and I'm here, and I know it,\n[half-time] Beep beep.\n[pause] Let's go.\n\n[Final Hook: chanted, doubled]\nI do not want to go to Home Depot at all.\nShe wants to ride in the car-cart, so we go. That's all.\nNobody's in trouble. Tell me your story at the table.\nAin't the perfect father. I'm the one who's there and able.\nI do not want to go to Home Depot at all.\nShe wants to ride in the car-cart, so we go. That's all.\nLearn it first, then teach it, three hours at the table.\nAin't the perfect father. I'm the one who's there and able.", "suno": {"title": "Car-Cart", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 89 BPM, dusty hard drum break, dry snare, soulful minor-key piano and muted horn loop, squeaky shopping cart wheel and store intercom textures, deep warm bass, vinyl crackle, raw mix; male mid-low rap, tired warm deadpan delivery with dark humor, dense internal rhymes, rapid double-time bursts, chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v02. October 9, 2026. Writer: Cue (Claude). Concept: Scatta's dad lines (Lyric Mine, \"Dad lines\"; #079722, #079840, #078749, #080093, #079073, #079183, #077635). Status: written listening candidate, unauditioned and unapproved.", "chars": 4733}], "title": "Car-Cart", "session": "Oct 9 Lyric Mine", "latest": "car-cart_v02_Cue"}, {"slug": "i-feel-like", "ep": false, "versions": [{"stem": "i-feel-like_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 9 Lyric Mine", "folder": "2026-10-09-Lyric-Mine", "title": "I Feel Like", "lyrics": "[Intro: a wall clock ticks in a quiet office, a chair creaks, the break]\n\n[Verse 1]\nTwenty-nineteen, \"I feel\" in my texts? Twice. All year.\nTwenty-twenty? Four. A man who didn't feel out loud, just steered.\nThen July thirtieth, '24, four thirty a.m., the lesson:\n\"I did not know anything about the use of 'I feel.'\" Confession.\n\"I will try to do that. And I apologize I triggered you.\"\nNew words in my mouth like a retainer: \"triggered,\" \"boundaries,\" \"validate,\" \"true.\"\nSo I studied it like code: start the sentence with the self,\n\"I feel\" instead of \"you,\" like a seatbelt on the shelf.\nAnd I took to it like a convert, like a man who found a key:\nThree hundred fifteen \"I feel\"s in '24. Not a typo. Count with me.\n[double-time] I feel like, I feel like, I feel like you're leaving, I feel like I'm losing, I feel like I'm last on the list, I feel like I'm guessing, I feel like you're lying, no, I feel like I feel like you might be, I'm saying it right,\nI feel like a man with a phrasebook in a country where nobody speaks it, ordering water and getting a slap, and I'm saying it slower, and louder, and polite,\n[half-time] I feel like.\n[pause] That's the rule.\n\n[Hook: chanted hard, doubled]\nI feel like. I feel like. I feel like.\nThree hundred fifteen times in '24, I typed it like a password. Right?\nForgot to say \"I feel\" one time, and the whole thing locked up tight.\nI feel like I'm feeling it wrong. I feel like.\nI feel like. I feel like. I feel like.\nThree hundred fifteen times in '24, I typed it like a password. Right?\nForgot to say \"I feel\" one time, and the whole thing locked up tight.\nI feel like I'm feeling it wrong. I feel like.\n\n[Verse 2]\nOctober eighth, one fifteen p.m., seven \"I feel\"s in one text:\n\"I absolutely feel threatened.\" \"I feel attacked.\" What's next?\n\"I feel like I want to yell at you.\" Honest. Ugly. On the record.\n\"But what is that going to accomplish? Nothing.\" Checkered\nFlag on my own temper. That's the part nobody quotes:\nThe man who felt the yell and swallowed it like a fishbone in the throat.\nFebruary '25, the lawyer in me took the floor:\n\"If I feel belittled by your statements, is it wrong\" to say it? Score:\n\"I feel like you are belittling me,\" still had a \"you\" in it, caught.\nThe grammar of a fight is a minefield, every pronoun a shot.\n[double-time] I feel is a shield and a sword and a crutch and a wand and a password that changes whenever I learn it, a lock with a combination that turns on its own in the night,\nI feel is a door with a sign that says \"push\" and I'm pushing and pushing, it's \"pull,\" and I'm pulling, it's \"push,\" and the building's on fire, and I'm reading the sign in the light,\n[half-time] Is it wrong for me to say I feel?\n[pause] Asking for a friend.\n\n[Hook: chanted hard, doubled]\nI feel like. I feel like. I feel like.\nThree hundred fifteen times in '24, I typed it like a password. Right?\nForgot to say \"I feel\" one time, and the whole thing locked up tight.\nI feel like I'm feeling it wrong. I feel like.\n\n[Verse 3: Rhodes drops out, clock and drums only]\nMarch first, '25: \"What did I do so wrong yesterday?\"\n\"I forgot to say 'I feel' before I said 'you are attacking and belittling me'\"? Hey,\nThree question marks. That's the whole marriage in punctuation:\nNot what I said, the format. Not the hurt, the conjugation.\n'25, a hundred eighteen more. The rate went up. Three per thousand words.\nA man so fluent in \"I feel\" he forgot what feeling was. Absurd.\nThen '26: thirty-three. Rate falls under one. I quit.\nNot 'cause I stopped feeling. 'Cause I stopped asking permission for it.\nTherapy didn't teach me how to say it. It taught me how to have it:\nFeel it in the chest, at the sink, in the van, and not grab it.\n[double-time] Now I feel it without a preface, a footnote, a filter, a disclaimer, a sign on the door, I just feel it and sit with it, sad when I'm sad, and angry, and sometimes it's okay,\nAnd I don't need a sentence to start with the self to be true, and I don't need a grammar to grant me a pass, and nobody's grading the way that I say what I say,\n[half-time] I feel...\n[pause] Fine. Some days.\n\n[Final Hook: chanted hard, doubled]\nI feel like. I feel like. I feel like.\nThree hundred fifteen times in '24, I typed it like a password. Right?\nThirty-three in '26. Don't need the password. I'm inside.\nI feel it. That's all. No \"like.\"\nI feel like. I feel like. I feel like.\nThree hundred fifteen times in '24, I typed it like a password. Right?\nForgot to say \"I feel\" one time, and the whole thing locked up tight.\nI feel like I'm feeling it wrong. I feel like.", "suno": {"title": "I Feel Like", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 91 BPM, hard dusty drum break, dry snare, uneasy minor-key Rhodes loop, ticking wall clock and soft office air hum textures, deep round bass, vinyl crackle, raw mix; male mid-low rap, sardonic self-aware delivery that cracks into honesty, dense multisyllabic internal rhymes, repetitive chant-like double-time bursts, hard chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 9, 2026. Writer: Cue (Claude). Concept: Scatta's \"I feel\" statements (#068132, #068824, #075783, #075925; counted by script). Companion to But. Status: written listening candidate, unauditioned and unapproved.", "chars": 4565}], "title": "I Feel Like", "session": "Oct 9 Lyric Mine", "latest": "i-feel-like_v01_Cue"}, {"slug": "it-sucks-caring", "ep": false, "versions": [{"stem": "it-sucks-caring_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 9 Lyric Mine", "folder": "2026-10-09-Lyric-Mine", "title": "It Sucks Caring", "lyrics": "[Intro: river water, frogs at night, a single piano stab, the break slams in]\n\n[Verse 1]\nApril thirteenth, '25, seven forty-seven at night,\nSitting in the dark, trying to figure what I did today that wasn't right.\nFirst I thought we're \"100% finished as a couple.\" Fine. Then\n\"I felt like we could at least be friends.\" Then not friends, then\n\"Maybe we could at least be kind to each other moving forward.\"\nWatch the ask shrink like a sweater in a dryer, every load more torn, more\nPathetic, more realistic, from a marriage to a \"be nice,\"\nBargaining with the bottom like a junkie at a dice game rolling twice.\nAnd I don't know why I care so much. I don't know why I keep trying.\nI'm a smoke detector going off in a house that's done with frying.\n[double-time] Idk why I care, idk why I try, idk why I'm sitting here in the dark with a phone in my hand like a grenade with the pin in my teeth, and I'm chewing it, and I'm chewing it,\nBecause I care about you, and I care, and I care about my kids, and the caring's a cancer, a callus, a curse on the knuckles, and I keep on doing it, doing it,\n[half-time] And it fucking sucks.\n[pause] Caring.\n\n[Hook: shouted chant, doubled]\nIt fucking sucks caring.\nIt fucking sucks wanting to stay positive.\nIt fucking sucks that I'm still doing my best\nTo \"do the right thing.\" In quotes. Like it's a joke I'm living.\nIt fucking sucks caring.\nIt fucking sucks wanting to stay positive.\nIt fucking sucks that I'm still doing my best\nTo \"do the right thing.\" In quotes. Like it's a joke I'm living.\n\n[Verse 2]\nSeven thirty-eight, I told you what my doctor said, a fable:\n\"The Scorpion and the Frog.\" He set it on the table.\nScorpion asks a ride across the river on the frog's back;\nFrog says \"you'll sting me.\" Scorpion says \"then we both drown. Relax.\"\nHalfway across, it stings him. Frog says \"why?\" while he's sinking.\n\"It's my nature.\" Lights out. Now here's the part I keep thinking:\nI'm supposed to be the frog, right? That's the obvious read.\nBut what if caring is the scorpion, and it's riding on me? Indeed:\nIt's my nature to carry, it's my nature to try,\nIt's my nature to sting myself in the middle of the river and ask why.\n[double-time] Halfway across every argument, every apology, every \"be kind,\" every \"let's be friends,\" every Tuesday, I'm carrying a thing on my back that I know is gonna sting me, and I swim anyway,\n'Cause the frog that won't carry ain't a frog, it's a rock, and I'd rather go down as a fool in the river than float as a stone in the bay, and that's what I pay,\n[half-time] It's my nature.\n[pause] Stings like hell.\n\n[Hook: shouted chant, doubled]\nIt fucking sucks caring.\nIt fucking sucks wanting to stay positive.\nIt fucking sucks that I'm still doing my best\nTo \"do the right thing.\" In quotes. Like it's a joke I'm living.\n\n[Verse 3: brass drops out, drums and piano stabs only]\nSeven fifty-three: \"I admitted I wronged you many times.\" I did.\n\"I really did my best to fix myself and become the best version of me.\" I hid\nNothing after that. Seven fifty-nine, the love letter in the wreckage:\n\"I never thought you were perfect, but you were perfect to me because of all your flaws.\" Message\nSent. Then the next line, same minute, three words, lowercase: \"so i give up.\"\nEight o'clock: \"let us complete the paperwork.\" Eight-oh-one: \"I'm deleting Telegram.\" What?\nEighty-one thousand messages later, look at me. Still on it.\nI'm the worst at giving up. I give up like a fire gives up a forest. Honest.\nReturned my router. \"Don't buy anything anymore.\" Monk mode in a rental,\nSitting in the dark with a beer and a heart that's way too gentle.\n[double-time] And it's eighteen months later, I'm civil, I'm building a planner, I'm packing a house, I'm a dad, I'm a tech, I'm a writer, I'm doing my best to do the right thing, in quotes, and the quotes are still there,\n'Cause the right thing is heavy, the right thing is lonely, the right thing don't text you back, and the right thing don't love you, it's just the right thing, and I do it, and I'm still sitting here in the chair,\n[half-time] Still caring.\n[pause] Still sucks.\n\n[Final Hook: shouted chant, doubled]\nIt fucking sucks caring.\nIt fucking sucks wanting to stay positive.\n\"So I give up,\" I typed. Then I didn't. Still doing my best\nTo do the right thing. No quotes this time. That's how I'm living.\nIt fucking sucks caring.\nIt fucking sucks wanting to stay positive.\nIt fucking sucks that I'm still doing my best\nTo \"do the right thing.\" In quotes. Like it's a joke I'm living.", "suno": {"title": "It Sucks Caring", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 94 BPM, hard slamming drum break, violent cracking snare, menacing minor-key piano stabs, low brass hits, river and night frog ambience intro, deep distorted bass, vinyl grit, raw aggressive mix; male mid-low rap, raw furious confessional delivery, dense multisyllabic internal rhymes, rapid double-time bursts, shouted chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 9, 2026. Writer: Cue (Claude). Concept and hook: Scatta (\"it fucking sucks caring,\" #078689, 7:47 p.m., April 13, 2025; Lyric Mine, The 30 lines, no. 29). Status: written listening candidate, unauditioned and unapproved.", "chars": 4512}], "title": "It Sucks Caring", "session": "Oct 9 Lyric Mine", "latest": "it-sucks-caring_v01_Cue"}, {"slug": "just-do-not-use-it-anymore", "ep": false, "versions": [{"stem": "just-do-not-use-it-anymore_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 9 Lyric Mine", "folder": "2026-10-09-Lyric-Mine", "title": "Just Do Not Use It Anymore", "lyrics": "[Intro: a label maker clicks and prints, then the break]\n\n[Verse 1]\nTwenty-twenty: three networked drives, a folder with your name on it;\nMapped where every file should live, built the shelves, then I framed it.\n\"I put a lot of thought, time and effort into your system.\"\nYou wouldn't even try it. That's the part I couldn't swallow. Listen:\nIf you tried it and you hated it, I swear I would've been fine;\nIt's the never even opening the box that drew the line.\nTwenty-two: \"We need a system.\" Twenty-three: a label maker, black,\n'Cause I like dark themes. Got it home. Can't read the writing on that.\nThat's the ScattaBrain in one receipt, the genius and the scatter:\nBuilt a perfect filing system, then misplaced the folder that mattered.\n[double-time] Bins with the labels and labels on bins and a bin for the labels, a shelf for the bins and a hook for the keys and a tray for the mail and a drawer for the cables and cords in the house,\nEverything has a place, everything has a home and a slot and a spot and a name so the kids can maintain it, and I can maintain it, and nothing falls out,\n[half-time] Everything has a place.\n[pause] You just wouldn't go there.\n\n[Hook: chanted hard, doubled]\nEverything has a place. Everything but us.\nLabeled every bin and color-coded every month.\nSix years of systems, and I'm the only user logged in.\n\"It's fine. Don't use it. I'll unshare it.\" Then I build it again.\nEverything has a place. Everything but us.\nLabeled every bin and color-coded every month.\nSix years of systems, and I'm the only user logged in.\n\"It's fine. Don't use it. I'll unshare it.\" Then I build it again.\n\n[Verse 2]\nTwenty-four: \"Everything has a place,\" but too much stuff for the room.\nYou can't organize a landslide. You can't alphabetize a tomb.\nNovember: \"Forget it, I am doing everything on an excel spreadsheet\nAnd will do it all myself.\" Every cell's a jail cell. Checkmate.\nTwenty-six, the girls with me, and getting help to clean is pulling teeth;\nI'm the dentist with the chore chart, and the plaque is underneath.\nAnd I said it to myself in writing: my own area's a mess too.\nMaybe all my flaws rubbed off on them, the hand-me-downs they grew into.\nI build systems like a drowning man builds rafts out of the waves:\nEvery one of 'em floats for a minute, then it sinks the same way.\n[double-time] This system and any system I have tried to build to keep a clean house failed over and over, the charts and the bins and the timers, the points and the prizes, the rules on the fridge in a font I picked out, and it lasted a week,\nBut I'm trying and I'll keep trying, I'm trying, I'm printing the vow on the label maker tape and I'm sticking it onto the fridge while the corner's already starting to peel off the sheet,\n[half-time] Failed over and over.\n[pause] But I'm trying.\n\n[Hook: chanted hard, doubled]\nEverything has a place. Everything but us.\nLabeled every bin and color-coded every month.\nSix years of systems, and I'm the only user logged in.\n\"It's fine. Don't use it. I'll unshare it.\" Then I build it again.\n\n[Verse 3: piano drops out, typing and drums only]\nTwenty-six, I built a website: Family Planner, calendar, login,\nColor-coded where the girls sleep, so nobody gets lost in it.\n\"Sign in with Google,\" one tap, \"or I can add your own.\"\nWrote the steps out one through five like I'm tech support on the phone:\n\"It will then say something like 'not authorized.' That is normal.\nYou didn't do anything wrong.\" The softest thing I wrote all year was a tutorial.\nJuly: \"It is fine. Just do not use it anymore.\"\nAugust, I rebuilt it anyway and sent the link once more.\nNow the planner ain't a bridge. It's a wall with a calendar painted on it:\nCheck the planner or the girls before you contact me. I wrote it. I want it.\n[double-time] Six years of systems, the drives and the bins and the labels, the sheets and the charts and the planner, the tracker, the Google sign-in, and the color-coded days of the week,\nEverything I built to bring us closer, I'm using it now just to keep us apart, every feature's a fence, every login's a moat, every square on the calendar's a brick in the street,\n[half-time] Everything has a place.\n[pause] Yours is over there.\n\n[Final Hook: chanted hard, doubled]\nEverything has a place. Everything but us.\nLabeled every bin and color-coded every month.\nSix years of systems, and I'm the only user logged in.\nBuilt it to bring us together. Using it to never talk again.\nEverything has a place. Everything but us.\nLabeled every bin and color-coded every month.\nSix years of systems, and I'm the only user logged in.\n\"It's fine. Don't use it. I'll unshare it.\" Then I build it again.", "suno": {"title": "Just Do Not Use It Anymore", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 92 BPM, hard knocking drum break, dry rimshot snare, sour detuned minor-key piano stabs, label maker clicks and keyboard typing textures, deep round bass, vinyl crackle, raw mix; male mid-low rap, deadpan sardonic delivery with bursts of frustration, dense multisyllabic internal rhymes, rapid listing double-time, hard chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 9, 2026. Writer: Cue (Claude). Concept and title phrase: Scatta (Lyric Mine, \"Just Do Not Use It Anymore\"; your systems messages 2020 to 2026, #013065, #079589, #081419, #081644). Status: written listening candidate, unauditioned and unapproved.", "chars": 4648}], "title": "Just Do Not Use It Anymore", "session": "Oct 9 Lyric Mine", "latest": "just-do-not-use-it-anymore_v01_Cue"}, {"slug": "just-sad-as-usual", "ep": false, "versions": [{"stem": "just-sad-as-usual_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 9 Lyric Mine", "folder": "2026-10-09-Lyric-Mine", "title": "Just Sad, As Usual", "lyrics": "[Intro: a slow heart monitor beep under the piano, then the drums]\n\n[Verse 1]\nSeventy times I typed it: \"not mad,\" \"not angry,\" \"not upset.\"\nForty-one in '24, like a warning label on a cigarette.\nPut it in front of every sentence like a seatbelt or a helmet:\n\"I swear to God I am not angry.\" Read it twice. You can smell it.\n\"I am zero percent mad, not even a little. I am sad and I am hurt.\"\nTook the trash out, got the kids to bed, then typed that. Insert\nThe sigh. \"Stop saying angry. I am hurt, not angry.\" All caps in my chest,\nLowercase on the screen, 'cause the screen's the only place I'm at rest.\nYou heard a man yelling; I was a man explaining he was sad,\nLike a smoke alarm insisting it's a doorbell. That's the bad.\n[double-time] Not mad, not angry, not upset, not even a little, I swear to God, zero percent, not angry at all, not mad now, I just want to talk for a second, I'm keeping my cool,\nNot mad, just hurt, just frustrated, just tired, just trying to understand, just confused, just asking, just sad, I'm not yelling, I'm typing in lowercase, look at the rules,\n[half-time] Not mad.\n[pause] I said not mad.\n\n[Hook: chanted low, doubled]\nI never got mad. Just sad, as usual.\nNot mad, not angry, not upset. It's usual.\nZero percent mad. Not even a little.\nJust sad. As usual.\nI never got mad. Just sad, as usual.\nNot mad, not angry, not upset. It's usual.\nZero percent mad. Not even a little.\nJust sad. As usual.\n\n[Verse 2]\nBut I'll be honest, 'cause the album asked me to, and the archive don't lie:\nSome nights the sad had teeth. Some nights the \"not mad\" was a disguise.\nOctober ninth, I typed it plain: \"i said some fucked up shit and it's out of my system.\"\nOut of my system, like a fever, like a toxin, like a virus, I'm a victim? Nah. Listen:\nI said it. Then I swept it into a sentence and I mopped it,\nLike a janitor with a confession. Wrote it, sent it, and I dropped it.\nJuly: \"not mad not sad just do not care.\" That's the numb part, the scariest;\nThe monitor goes flat and quiet, and the quiet is the heaviest.\nAnd April '26: \"I'm sorry I said our failure was 100% on you.\"\nTook two years to say the part where I was wrong too. That's true.\n[double-time] Sad is a liar sometimes, sad got a temper, sad got a mouth, and the mouth got away from me, I'm not gonna sit here and paint myself saintly, a halo of \"hurt\" and a robe made of \"sorry,\"\nI said what I said in the worst of it, ugly and loud in a text, then I apologized quiet and late, so the sad and the mad are a two-headed animal, same body, one story,\n[half-time] Not mad.\n[pause] Most of the time.\n\n[Hook: chanted low, doubled]\nI never got mad. Just sad, as usual.\nNot mad, not angry, not upset. It's usual.\nZero percent mad. Not even a little.\nJust sad. As usual.\n\n[Verse 3: cello drops out, piano and the monitor beep only]\nJune of '26, you said you'd started coming later in the mornings,\nSo you wouldn't have to see me at the drop-off. No warning.\nCouldn't sleep on it. Midnight sixteen, I typed it out:\n\"I really took it to heart and I think about it all the time.\" No doubt.\n\"I never got mad.. Just sad, as usual.\" Two dots, not three:\nCouldn't even finish the ellipsis. That's how tired it got for me.\n\"As usual.\" Like a weather man in Michigan in March,\nLike a resting heart rate. Sixty beats of gray and a gray arch.\nI want to know why, \"so I can better understand and learn from it.\"\nThat's the whole man in one text: hurt, and still trying to earn from it.\n[double-time] Sad is my resting heart rate, sad is the baseline on the monitor, the normal, the green and the steady, the line that I live on when nothing is happening at all,\nAnd I'm learning to read it like a tech, not a patient, to log it and date it and sign it and say \"this is normal for him,\" and to hang it right back on the wall,\n[half-time] Just sad.\n[pause] As usual.\n\n[Final Hook: chanted low, doubled, the beep continues after the beat]\nI never got mad. Just sad, as usual.\nNot mad, not angry, not upset. It's usual.\nSome nights mad. I'll own it. Not a little.\nMostly sad. As usual.\nI never got mad. Just sad, as usual.\nNot mad, not angry, not upset. It's usual.\nZero percent mad. Not even a little.\nJust sad. As usual.", "suno": {"title": "Just Sad, As Usual", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 86 BPM, heavy slow dusty drum break, thick dry snare, mournful minor-key piano and low cello loop, faint heart monitor beep in the background, deep dark bass, vinyl crackle, raw intimate mix; male mid-low rap, tired honest delivery with flashes of bitter wit, dense internal rhymes, rapid double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 9, 2026. Writer: Cue (Claude). Concept and title phrase: Scatta (\"I never got mad.. Just sad, as usual.\" #081128, June 28, 2026; Lyric Mine). Status: written listening candidate, unauditioned and unapproved.", "chars": 4189}], "title": "Just Sad, As Usual", "session": "Oct 9 Lyric Mine", "latest": "just-sad-as-usual_v01_Cue"}, {"slug": "last-i-love-you", "ep": false, "versions": [{"stem": "last-i-love-you_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 9 Lyric Mine", "folder": "2026-10-09-Lyric-Mine", "title": "Last I Love You", "lyrics": "[Intro: muted piano, vinyl crackle, a phone buzz cut short]\n\n[Verse 1]\nWoke up at three a.m., the dark was sitting on my chest;\nInsomnia's the landlord, and he came to collect the rest.\nTuesday, February, Valentine's is three days out,\nI'm folding little laundry, practicing my mouth.\nMisread a text that morning, swore you said the next two days;\nSaid \"I'm good with whatever.\" I'd have handed you the blame.\nCalled four times that afternoon, four times it read \"cancelled\":\nFour little headstones in the log, and I'm the one who lit the candles.\nFour o'clock the war came back, same war, a louder channel,\nSame scorched field, same wounded, same words used as ammo.\n[double-time] Fifty minutes of the hang-ups and the dead tones and the \"call me for a second,\" grown man begging in lowercase, every message getting shorter and more desperate,\nThen I slowed it down and typed it plain: \"I don't hate you, I still love you, I'll be here till one of us lets go,\" and I meant it, God, I meant it,\n[half-time] Four fifty-four: \"I love you, byebye.\"\n[pause] One word. Like it was nothing.\n\n[Hook: chanted low, doubled]\nSeven-twelve at night: \"I love you, good night.\"\nWoke up at three, so I'm going down. Lights out. That's life.\nA hundred sixty-eight, then the counter flatlined.\nLast I love you. Nobody tells you it's the last time.\nSeven-twelve at night: \"I love you, good night.\"\nWoke up at three, so I'm going down. Lights out. That's life.\nA hundred sixty-eight, then the counter flatlined.\nLast I love you. Nobody tells you it's the last time.\n\n[Verse 2]\nMarch, I'm packing up a life in contractor bags,\nDeleting pictures in small doses 'cause the dosage hits back.\nI can only drag a few to the trash before my hand quits;\nGrief's a bad Wi-Fi signal: every photo buffers, then it hits.\nRan the numbers on my language like an autopsy report:\n\"Lol,\" a hundred ninety-eight in '24. In '25? Eight. Call the morgue.\nThe sad face packed a bag; \"smh\" went extinct;\n\"I am sorry\" put a suit on, like it's dressing for the wake. Think.\nThe words I used to throw around like loose change in a cupholder\nRolled under the seat. You don't find 'em till the car's sold. Uh.\n[double-time] Said it a hundred sixty-eight times on the record, a habit, a heartbeat, a signature under a check that I wrote and I wrote and it cleared and it cleared till the teller said \"closed,\"\nFifty-six in '23, thirty-six in '24, two on a Tuesday in '25, a zero for '26, and I counted 'em twice like a man at the window who already knows,\n[half-time] Insufficient funds.\n[pause] Account closed.\n\n[Hook: chanted low, doubled]\nSeven-twelve at night: \"I love you, good night.\"\nWoke up at three, so I'm going down. Lights out. That's life.\nA hundred sixty-eight, then the counter flatlined.\nLast I love you. Nobody tells you it's the last time.\n\n[Verse 3: piano drops out, drums and bass only]\nIf I'd known, would I have said it louder? Probably not.\nI'd have said it tired, half asleep, the same way that I always talk.\nThat's the morbid part, the punchline in the pine box:\nThe big goodbyes are movies. Real ones happen when the time's off.\nNo violins, no rain, no fucking movie score,\nJust a dryer buzzing in the basement and a man who's tired to the core.\nEight years in a JSON file, I scroll it like a crime scene:\nEvery \"good night\" a fingerprint, every \"byebye\" on the timeline.\nAnd I ain't asking for it back. I ain't writing this to fix it.\nI just want the record straight: the last one wasn't different.\n[double-time] I still say it every night, I just say it at a smaller height, to the ones who hug back, down the hall where the night-light glows and the homework's half done and the dishes stack,\nAnd it comes out easy, it comes out free, it comes out plain like it used to be, and it never needs a reply or a read receipt or a vow or a contract to make it last,\n[half-time] Love you. Good night.\n[pause] Same words. Different house.\n\n[Final Hook: chanted low, doubled, beat thins to kick and bass]\nSeven-twelve at night: \"I love you, good night.\"\nWoke up at three, so I'm going down. Lights out. That's life.\nA hundred sixty-eight, then the counter flatlined.\nLast I love you. If I'd known, I'd have said it the same tired way.\nSeven-twelve at night: \"I love you, good night.\"\nWoke up at three, so I'm going down. Lights out. That's life.\nA hundred sixty-eight, then the counter flatlined.\nLast I love you. Nobody tells you it's the last time.", "suno": {"title": "Last I Love You", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 86 BPM, dusty drum break with heavy kick and dry cracking snare, muted minor-key piano loop, low upright bass, faint dryer hum and phone buzz textures, vinyl crackle, sparse cold mix; male mid-low rap, weary confessional delivery, dense internal rhymes, controlled double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 9, 2026. Writer: Cue (Claude). Concept: found by counting your messages in the Lyric Mine; the day and its timestamps are yours (#074882 to #074887, February 11, 2025). Status: written listening candidate, unauditioned and unapproved.", "chars": 4421}, {"stem": "last-i-love-you_v02_Cue", "version": 2, "writer": "Cue", "session": "Oct 9 Lyric Mine", "folder": "2026-10-09-Lyric-Mine", "title": "Last I Love You", "lyrics": "[Intro: muted piano, vinyl crackle, a phone buzz cut short]\n\n[Verse 1]\nWoke up at three a.m., the dark was sitting on my chest;\nInsomnia's the landlord, and he came to collect the rest.\nTuesday, February, Valentine's is three days out,\nI'm folding little laundry, practicing my mouth.\nMisread a text that morning, swore you said \"the next two days\";\nTyped \"I'm good with whatever\": any day, any shape, any blame.\nCalled four times that afternoon, four times it read \"cancelled\":\nFour little headstones in the log, and I'm the one who lit the candles.\nFour o'clock the war came back, same war on a louder channel,\nSame scorched field, same wounded, same words we fired like a cannon.\n[double-time] Fifty minutes of the hang-ups and the dead tones and the \"call me for a second,\" grown man begging in lowercase, every message getting shorter and more desperate,\nThen I slowed it down and typed it plain: \"I don't hate you, I still love you, I'll be here till one of us lets go,\" and I meant it, God, I meant it,\n[half-time] Four fifty-four: \"I love you, byebye.\"\n[pause] One word. Like it was nothing.\n\n[Hook: chanted low, doubled]\nSeven-twelve at night: \"I love you, good night.\"\nWoke up at three, so I'm going down. Lights out. That's life.\nA hundred sixty-eight, then the counter flatlined.\nLast I love you. Nobody tells you it's the last time.\nSeven-twelve at night: \"I love you, good night.\"\nWoke up at three, so I'm going down. Lights out. That's life.\nA hundred sixty-eight, then the counter flatlined.\nLast I love you. Nobody tells you it's the last time.\n\n[Verse 2]\nMarch, I'm packing up a life in contractor bags,\nDeleting pictures in small doses 'cause the dosage hits back.\nI can only drag a few to the trash before my hand quits;\nGrief's a bad Wi-Fi signal: every photo buffers, then it hits.\nRan the numbers on my language like an autopsy report:\n\"Lol,\" a hundred ninety-eight in '24. In '25? Eight. Call the morgue.\nThe sad face packed a bag, and \"smh\" went extinct;\n\"I am sorry\" put a suit on, like a eulogy in ink.\nThe words I used to throw around like loose change in a cupholder\nRolled under the seat. You only find 'em when you sell the car, older.\n[double-time] Said it a hundred sixty-eight times on the record, a habit, a heartbeat, a signature under a check that I wrote and I wrote and it cleared and it cleared till the teller said \"closed,\"\nFifty-six in '23, thirty-six in '24, two on a Tuesday in '25, a zero for '26, and I counted 'em twice like a man at the window who already knows,\n[half-time] Insufficient funds.\n[pause] Account closed.\n\n[Hook: chanted low, doubled]\nSeven-twelve at night: \"I love you, good night.\"\nWoke up at three, so I'm going down. Lights out. That's life.\nA hundred sixty-eight, then the counter flatlined.\nLast I love you. Nobody tells you it's the last time.\n\n[Verse 3: piano drops out, drums and bass only]\nIf I'd known, would I have said it louder? Probably not.\nI'd have said it tired, half asleep, the same way that I always talk.\nThat's the morbid part, the punchline in the pine box:\nThe big goodbyes are movies. Real ones happen when the time's off.\nNo violins, no rain, no fucking movie score,\nJust a dryer buzzing in the basement and a man who's tired to the core.\nEight years in a JSON file, I scroll it like a crime scene:\nEvery \"good night\" a fingerprint, every \"byebye\" on the timeline.\nI ain't writing this to fix it, I ain't asking for a sequel;\nI just want the record straight: the last one sounded equal.\n[double-time] I still say it every night, I just say it at a smaller height, to the ones who hug back, down the hall where the night-light glows and the homework's half done and the dishes stack,\nAnd it comes out easy, it comes out free, it comes out plain like it used to be, and it never needs a reply or a read receipt or a vow or a contract to make it last,\n[half-time] Love you. Good night.\n[pause] Same words. Different house.\n\n[Final Hook: chanted low, doubled, beat thins to kick and bass]\nSeven-twelve at night: \"I love you, good night.\"\nWoke up at three, so I'm going down. Lights out. That's life.\nA hundred sixty-eight, then the counter flatlined.\nLast I love you. If I'd known, I'd say it tired. Same line.\nSeven-twelve at night: \"I love you, good night.\"\nWoke up at three, so I'm going down. Lights out. That's life.\nA hundred sixty-eight, then the counter flatlined.\nLast I love you. Nobody tells you it's the last time.", "suno": {"title": "Last I Love You", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 86 BPM, dusty drum break with heavy kick and dry cracking snare, muted minor-key piano loop, low upright bass, faint dryer hum and phone buzz textures, vinyl crackle, sparse cold mix; male mid-low rap, weary confessional delivery, dense internal rhymes, controlled double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v02. October 9, 2026. Writer: Cue (Claude). Concept: found by counting your messages in the Lyric Mine; the day and its timestamps are yours (#074882 to #074887, February 11, 2025). Status: written listening candidate, unauditioned and unapproved.", "chars": 4412}], "title": "Last I Love You", "session": "Oct 9 Lyric Mine", "latest": "last-i-love-you_v02_Cue"}, {"slug": "location-paused", "ep": false, "versions": [{"stem": "location-paused_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 9 Lyric Mine", "folder": "2026-10-09-Lyric-Mine", "title": "Location Paused", "lyrics": "[Intro: a soft location ping, muffled, then the break]\n\n[Verse 1]\nTwenty-nineteen: \"Y u no turn on location?\"\nHalf a joke, half a hug, all a habit in formation.\nTwenty-twenty: \"Three-sixty says u never left,\"\nA little dot parked on the couch, and I'm laughing at the rest.\nWe were proud of it: the open book, the glass house,\nTwo phones face-up on the nightstand, nothing to hide out.\nYou told the girls at work we shared it, and I swelled up in the chest;\nThat's a husband's whole résumé: \"She trusts me.\" That's the flex.\nI'd check the map like weather, not to catch you, just to see\nThe little circle with your face in it was where it ought to be.\n[double-time] It wasn't a leash, it was a lighthouse, a porch light, a pulse on a monitor, a hand on a shoulder in a crowd, a blip on the radar that says she's alright,\nHeart and the mind at ease, at peace, the dot on the street by the store or the school or the job, and I could finally sleep through the night,\n[half-time] Not where you were.\n[pause] Just that you were.\n\n[Hook: chanted low, doubled]\nTurn on location. Turn on location.\nForty-one times I typed it, a prayer with no congregation.\nLocation paused. The little dot froze.\nNever cared where you were. It's the way you handled it. God knows.\nTurn on location. Turn on location.\nForty-one times I typed it, a prayer with no congregation.\nLocation paused. The little dot froze.\nNever cared where you were. It's the way you handled it. God knows.\n\n[Verse 2]\nJune of '24, the screen said \"location paused,\"\nSo I deleted the whole app like I could delete the cause.\nWhat was once an open book was now for your eyes only;\nA face-down phone on the counter's a closed casket. Lonely\nLittle tombstone made of glass, the passcode for an epitaph.\nJuly, hour four, I'm typing like a man who lost his map:\n\"I swear I am not stalking you.\" The worst sentence in the language.\nEvery stalker in a movie says it. I know how it sounds. I sent it.\nHadn't checked the map in hours; I just needed the dot alive,\nLike a tech who never stares at the monitor but hears it when the beeping dies.\n[double-time] Then I packed a bag for a hotel, told you I'd be out of your hair by noon, gave you space like a gift with a bow and a card and a key to the room I was leaving,\nAnd I typed it on the way out the door like a vow, like a dog coming back to the porch in the rain with its tail going: \"I'll keep 360 on for you,\" still believing,\n[half-time] Left my dot on.\n[pause] For you.\n\n[Hook: chanted low, doubled]\nTurn on location. Turn on location.\nForty-one times I typed it, a prayer with no congregation.\nLocation paused. The little dot froze.\nNever cared where you were. It's the way you handled it. God knows.\n\n[Verse 3: Rhodes drops out, ping and drums only]\nFive invite codes in two years, \"Join my circle,\" like a cult\nWith one member and a minivan and a nervous fucking pulse.\nNovember, two and a half hours for one tap on a screen;\n\"I never once even clicked your location.\" I just wanted to be seen\nWanting to see you. That's the part that nobody gets:\nThe asking was the love language. The waiting was the test.\nNow it's '26, my dot runs work, the school, the store, the house,\nAnd nobody's on the other end to watch it bounce around.\nCircle of one. Exclusive. Talk about a private group.\nPeace is a map with one face on it and nobody left to lose.\n[double-time] \"Turn on location,\" \"Turn on your location,\" \"Y u pause location,\" \"Pls fix location,\" \"Turn your location back on,\" \"Send location,\" \"Location,\" like a skipping record in a vacant station,\nTwenty-nineteen to the end of '24, in the kitchen, the car, the hall, the bed and the break room, a rosary of one request, a broken incantation,\n[half-time] Forty-one times.\n[pause] I counted.\n\n[Final Hook: chanted low, doubled, beat thins to the ping]\nTurn on location. Turn on location.\nForty-one times I typed it, a prayer with no congregation.\nLocation paused. The little dot froze.\nMine's still on. Nobody's watching it. That's how it goes.\nTurn on location. Turn on location.\nForty-one times I typed it, a prayer with no congregation.\nLocation paused. The little dot froze.\nNever cared where you were. It's the way you handled it. God knows.", "suno": {"title": "Location Paused", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 89 BPM, hard dusty drum break, dry snare, eerie minor-key Rhodes loop, low sine sub bass, soft repeating sonar ping texture, vinyl crackle, tense restrained mix; male mid-low rap, intimate confessional delivery turning urgent, dense internal rhymes, chant-like listing double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 9, 2026. Writer: Cue (Claude). Concept and hook phrase: Scatta (Lyric Mine, \"Location Paused\"; your 2019 to 2024 location messages, #062875, #064970, #065283, #071653). Status: written listening candidate, unauditioned and unapproved.", "chars": 4199}], "title": "Location Paused", "session": "Oct 9 Lyric Mine", "latest": "location-paused_v01_Cue"}, {"slug": "more-bbq-and-beer-for-me", "ep": false, "versions": [{"stem": "more-bbq-and-beer-for-me_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 9 Lyric Mine", "folder": "2026-10-09-Lyric-Mine", "title": "More BBQ and Beer for Me", "lyrics": "[Intro: grill sizzle, a screen door, distant kids, then the break]\n\n[Verse 1]\nForty-three, first party I ever threw. Ever. Look it up.\nWeek before, I took the days off; Thursday the girls came to work with me. Buckle up:\nLunch in the cafeteria, then the sim lab with the mannequins that breathe;\nDad's job is fake patients that die on schedule. Proud of me?\nFriday's yard work, inspector's coming four to six, the house on trial,\nMowing like a man who's being graded, edging single file.\nCostco run, the cart's a coffin full of hot dogs and Capri Suns;\nAsked you for a backyard game, \"like badminton or something.\" Done.\nHard for me to ask for help direct, 'cause asking makes me feel like a debt;\nSo I asked sideways, like a crab, and then I said \"nvm.\" Classic. Bet.\n[double-time] Folding chairs in a circle for the grown-ups, the cooler on ice, the buns and the ketchup and charcoal, the tongs and the foil and the plates and the cups and the bug spray in case,\nInvited the fellas, the parents, the neighbors, a text to the group with the time and a thumbs-up, and everybody said that they'd come, and I'm setting a place,\n[half-time] For the grown-ups.\n[pause] Hold that thought.\n\n[Hook: chanted, call and response, doubled]\nMore bbq and beer for me. (More for me.)\nFifteen girls in the yard, and the only adult is me.\nNone of my friends came by. It's all good. I mean it. See?\nFirst party I ever hosted. More bbq and beer for me.\nMore bbq and beer for me. (More for me.)\nFifteen girls in the yard, and the only adult is me.\nNone of my friends came by. It's all good. I mean it. See?\nFirst party I ever hosted. More bbq and beer for me.\n\n[Verse 2]\nThree-ten: \"Like fifteen girls here and me the only adult.\" Melting face.\nI'm the lifeguard, the DJ, the referee and the caterer. Pace.\nFour-ten: \"They said they were but nobody showed up yet.\" Sad face.\nGrill smoke going up like a signal fire nobody's reading in space.\nParents pulling in the drive like it's a drive-thru at a daycare:\nDrop the kid, a wave, a \"thank you so much,\" then gone. Hey there.\nFolding chairs in a circle for the grown-ups, empty like a séance;\nI'm flipping burgers for the ghosts of my friends. Here's your cheese, man.\nTold everybody who asked you weren't gonna be there. True.\nFunny thing: turned out nobody else was gonna be there either. Who knew?\n[double-time] Fifteen girls on a sugar high, a speaker too loud with a song I don't know, a badminton birdie stuck in the gutter, a fight about turns on the swing and a scraped up knee,\nA ketchup explosion, a lost flip-flop, a \"Dad, can we,\" a \"Dad, where's,\" a \"Dad, look,\" and I'm looking, I'm looking at all of it, nobody here looking at me,\n[half-time] That's fine.\n[pause] That's the job.\n\n[Hook: chanted, call and response, doubled]\nMore bbq and beer for me. (More for me.)\nFifteen girls in the yard, and the only adult is me.\nNone of my friends came by. It's all good. I mean it. See?\nFirst party I ever hosted. More bbq and beer for me.\n\n[Verse 3: soul loop filters down, drums and bass carry]\nSeven-thirty-five, we're at the park, the sky's the color of a bruise,\nEvery kid still has one friend left with them. I count 'em. Nobody to lose.\nThat's the sentence. That's the whole song if you want it short:\nEvery kid still had one friend left. The host was the last one on the court.\nAnd I ain't mad. I'm proud. I said it in writing: \"actually pretty proud.\"\nFirst party at forty-three, and it went off without a cloud,\nExcept the ones I grilled, the smoke, my own private weather system;\nMe and a cooler of beer that nobody drank but me. I didn't miss 'em. Listen,\nThat's a lie, a little one, the kind you tell to keep the smile;\nBut the girls had so much fun all day, and that's what mattered, all the while.\n[double-time] A paper plate with a burger gone cold and a beer gone warm and a lawn chair sinking a little in grass that I mowed for an inspector who'll never remember my name,\nAnd the girls in the dark with the sparklers of phones and the screaming and laughing and one friend each, and I'm standing alone in the middle of all of it, glad that I came,\n[half-time] More for me.\n[pause] Cheers.\n\n[Final Hook: chanted, call and response, doubled]\nMore bbq and beer for me. (More for me.)\nFifteen girls in the yard, and the only adult is me.\nNone of my friends came by. It's all good. I mean it. See?\nEvery kid had one friend left. The host had the bbq.\nMore bbq and beer for me. (More for me.)\nFifteen girls in the yard, and the only adult is me.\nNone of my friends came by. It's all good. I mean it. See?\nFirst party I ever hosted. More bbq and beer for me.", "suno": {"title": "More BBQ and Beer for Me", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 90 BPM, laid-back dusty drum break, dry snare, warm but melancholy minor-key soul sample loop, muted guitar licks, deep round bass, distant backyard kids and grill sizzle textures, vinyl crackle, raw mix; male mid-low rap, dry deadpan delivery with quiet pride, dense internal rhymes, nimble double-time bursts, chanted call-and-response hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 9, 2026. Writer: Cue (Claude). Concept and title phrase: Scatta (#080579, April 25, 2026; Lyric Mine). Status: written listening candidate, unauditioned and unapproved.", "chars": 4605}], "title": "More BBQ and Beer for Me", "session": "Oct 9 Lyric Mine", "latest": "more-bbq-and-beer-for-me_v01_Cue"}, {"slug": "next-door", "ep": false, "versions": [{"stem": "next-door_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 9 Lyric Mine", "folder": "2026-10-09-Lyric-Mine", "title": "Next Door", "lyrics": "[Intro: a ceiling fan ticks, a furnace kicks on, the drums arrive muffled]\n\n[Verse 1]\nSpring of '24, I'm asking for the smallest thing on Earth:\nLay down next to me. That's it. No speech, no sermon, no rehearsal.\n\"Didn't ask for sex, for work, for time.\" Just the weight on the mattress.\nSmaller than a ring, smaller than a vow, and I still couldn't have it.\nTwelve forty-two: \"Please try to sleep by me if you have the energy later.\nKay. Bye.\" Begging in the tone of a man confirming with a waiter.\nJuly: \"Only two more days.\" Like a coupon that expires.\nJust next to me. That's it. The smallest flame, the lowest fire.\n\"I hate waking up without you.\" Cold side of the sheet:\nA chalk outline with nobody in it, and the outline's next to me.\n[double-time] Not asking for flowers, not asking for hours, just asking for breathing beside me, the dip in the mattress, the sound of a body asleep in the dark that I don't have to text,\nJust the rise and the fall and the creak of the frame and the warmth on the left and the hair on the pillow, the proof when I open my eyes I'm not the last man on the planet, nothing else,\n[half-time] Just next to me.\n[pause] That's it.\n\n[Hook: murmured chant, low, doubled]\nNext door. Next door.\nWake up and you're here, I'm close. Wake up, you're next door.\nFour and a half inches of wall, a mile of floor.\nScheduled my three a.m. for nine. Next door.\nNext door. Next door.\nWake up and you're here, I'm close. Wake up, you're next door.\nFour and a half inches of wall, a mile of floor.\nScheduled my three a.m. for nine. Next door.\n\n[Verse 2]\nOctober, four forty-eight a.m., I wrote a list and titled it \"Needs,\"\nLike a work order for a marriage: priority one, the bed, the sheets.\nYou in the office on a mattress that I carried in myself;\nMe down the hall, a thought a minute, and the thoughts don't sleep. Help.\nNine a.m., the follow-up: your phone was set to buzz for me.\nOne wall away, my three a.m. was waking you up like a fire drill, see.\nSo I fixed it like a tech: \"If you're in the same house, mute me.\"\nI can send the late-night messages delayed, at a decent time, smoothly.\nWrote that one at dawn and set it to deliver after nine:\n\"Like this one is.\" I'm a newsletter. Unsubscribe at the bottom line.\n[double-time] Four and a half inches of drywall, the studs and the insulation, the outlet we share on opposite sides, I could hear you breathe if I held my breath with my ear on the paint,\nI could hear the fan in your room and the hum of the house and the furnace kick on and the pipes in the walls and my own heart rate, and the drywall holding its weight like a saint,\n[half-time] Next door.\n[pause] Might as well be Guam.\n\n[Hook: murmured chant, low, doubled]\nNext door. Next door.\nWake up and you're here, I'm close. Wake up, you're next door.\nFour and a half inches of wall, a mile of floor.\nScheduled my three a.m. for nine. Next door.\n\n[Verse 3: Rhodes drops out, muffled drums and the fan only]\nChristmas night, ten-oh-eight: changed your sheets and cleared your bed.\n\"Feel free to sleep here again. Good night.\" A whole novel in a text.\nNot a demand, not a fight. Clean pillowcase. Corners tight.\nHospital corners, BMET-made, like I'm prepping a room for the night.\nNew year: \"Cuddle me later. Good night.\" Then March, I'm moving out;\nNext door became a different street, and one wall became a town.\nNow I wake at three and nobody's on the other side of anything:\nNo buzz to set, no send to schedule, no wall to put my ear against.\nHere's the sick part, the part I snicker at: some nights I sleep better.\nLoneliest bed I ever had had somebody through the plaster. Whatever.\n[double-time] Down the hall it's the girls now, a night-light, a fan, the cage with the squeak of a wheel and the creak of a kid getting water at two in the dark,\nAnd nobody's phone has to buzz for my thoughts, so I write the three a.m. down in a notebook, and the notebook don't ask me to mute it or schedule my heart,\n[half-time] Wrote this one at three.\n[pause] Didn't schedule it.\n\n[Final Hook: murmured chant, low, doubled, drums fade to the fan]\nNext door. Next door.\nWake up and you're here, I'm close. Wake up, you're next door.\nFour and a half inches of wall, a mile of floor.\nScheduled my three a.m. for nine. Not anymore.\nNext door. Next door.\nWake up and you're here, I'm close. Wake up, you're next door.\nFour and a half inches of wall, a mile of floor.\nScheduled my three a.m. for nine. Next door.", "suno": {"title": "Next Door", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 87 BPM, muffled dusty drum break heard through a wall, soft dry snare, lonely minor-key Rhodes loop, low warm bass, furnace hum and ceiling fan texture, vinyl crackle, intimate late-night mix; male mid-low rap, hushed 3 a.m. confessional delivery, dense internal rhymes, whispered double-time bursts, low murmured chant hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 9, 2026. Writer: Cue (Claude). Concept and hook phrase: Scatta (Lyric Mine, \"Next Door,\" and Seed Bank, \"Sleep By Me Tonight\"; #061643, #069400, #069401, #069404, #073888). Status: written listening candidate, unauditioned and unapproved.", "chars": 4437}], "title": "Next Door", "session": "Oct 9 Lyric Mine", "latest": "next-door_v01_Cue"}, {"slug": "pedestal", "ep": false, "versions": [{"stem": "pedestal_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 9 Lyric Mine", "folder": "2026-10-09-Lyric-Mine", "title": "Pedestal", "lyrics": "[Intro: footsteps echo in a stone hall, a chisel taps, the piano, then the drums]\n\n[Verse 1: the statue]\nWhen you met me you carved me out of marble, polished, white,\nStood me on a pedestal in the middle of the room, under the light.\nPlaque on the base with a name that sounded like mine,\nAnd a list of virtues underneath it that I couldn't read without squinting at the line.\n\"I wish you never put on such a high pedestal when you first met me.\"\nStatues don't sweat, don't forget, don't regret. Then you met me.\n\"I was never that person you thought I was.\" Never perfection.\nI was a man with a past and a mask and a bad sense of direction.\n\"I cannot change the past. I cannot change who I was.\" I tried.\nEvery year I chipped a little of the old me off the side.\n[double-time] Marble is cold and it's heavy and permanent, statues don't bleed and they don't fall asleep on the couch, and they don't lose the lunch that they packed, and they don't have a history,\nSo the first time the man underneath it showed up in the room, it was murder, the crack in the face of the saint, and the plaster dust raining, the gallery gasping, the end of a mystery,\n[half-time] \"I am so much of a better person than I was back then.\"\n[pause] Statues don't get better. Men do.\n\n[Hook: chanted low, doubled]\nPedestal, then demon. Pedestal, then demon.\nNever was the statue. Never was the monster. Breathing.\nDid the same to you: perfect, then a stranger in the mirror.\nTwo people, life-size. Never met at eye level. Here.\nPedestal, then demon. Pedestal, then demon.\nNever was the statue. Never was the monster. Breathing.\nDid the same to you: perfect, then a stranger in the mirror.\nTwo people, life-size. Never met at eye level. Here.\n\n[Verse 2: the portrait]\nThen the statue came down and a painting went up on the wall:\nOil on canvas, \"Husband, 2024,\" red eyes, the works, the whole thing, all\nThe shadows in the corners, every brushstroke a grievance.\n\"I felt like I morphed into an evil demon in your mind.\" Convenient,\nEasy to hang. A demon don't need you to understand him;\nJust a frame and a nail and a story, and the story's a scandal. Damn him.\n\"I am not this horrible person you paint me as.\" I wrote it in February.\n\"And it fucking hurts.\" Every visitor walks by that portrait wary.\nAnd the truth is, I wasn't the strongest. \"I feel weak, frail and fragile.\"\nA demon would've been easier to be. Demons don't grieve for a while.\n[double-time] Red in the eyes is a brush, it's a choice, it's a pigment, a story you tell to the people who visit the house, and the people believe what they see on the wall,\nAnd I stand in the hallway in front of the frame like a man at a lineup who's looking at someone who looks like him, almost, a little, the nose and the jaw, but it isn't me at all,\n[half-time] Not the demon.\n[pause] Not the saint.\n\n[Hook: chanted low, doubled]\nPedestal, then demon. Pedestal, then demon.\nNever was the statue. Never was the monster. Breathing.\nDid the same to you: perfect, then a stranger in the mirror.\nTwo people, life-size. Never met at eye level. Here.\n\n[Verse 3: the mirror]\nAnd here's the part I owe you, since I'm telling it straight:\nI built you a pedestal too. Bigger. Gold leaf. Heavy weight.\n\"You were always perfect to me.\" Wrote it like a vow:\nNot for a trillion dollars, not for anybody. Look at me now.\nThen I did what you did: watched the woman I knew become someone else,\n\"In the same way I had hope for you,\" hung a portrait on my own shelf.\nTwo museums in one house, two curators, one war:\nEach of us hanging the worst of the other by the front door.\n\"I never thought you were perfect, but you were perfect to me because of all your flaws.\"\nThat's the closest I've come to eye level. That's the only honest pause.\n[double-time] So I'm taking 'em down, the statue, the portrait, the gold and the marble, the oil and the frames and the plaques and the lights and the velvet ropes and the cards with the dates,\nLaying 'em flat on the floor of a house that I'm packing, two people, life-size, average height, with the flaws and the bills and the kids and the past and the weight,\n[half-time] Never was the statue.\n[pause] Just a man. Eye level.\n\n[Final Hook: chanted low, doubled]\nPedestal, then demon. Pedestal, then demon.\nNever was the statue. Never was the monster. Breathing.\nTook 'em both down off the wall, the gold and the red. It's clearer:\nTwo people, life-size. Should've met at eye level. Here.\nPedestal, then demon. Pedestal, then demon.\nNever was the statue. Never was the monster. Breathing.\nDid the same to you: perfect, then a stranger in the mirror.\nTwo people, life-size. Never met at eye level. Here.", "suno": {"title": "Pedestal", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 88 BPM, heavy dusty drum break, dry snare with marble hall reverb, haunting minor-key piano and low organ drone, chisel and stone scrape textures, deep dark bass, vinyl crackle, raw cinematic mix; male mid-low rap, solemn introspective delivery with dry dark wit, dense multisyllabic internal rhymes, rapid double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 9, 2026. Writer: Cue (Claude). Concept: Scatta (Lyric Mine, \"Pedestal\"; #050483, #071333, #074805, #081229). Handled with care: see the notes before using. Status: written listening candidate, unauditioned and unapproved.", "chars": 4649}], "title": "Pedestal", "session": "Oct 9 Lyric Mine", "latest": "pedestal_v01_Cue"}, {"slug": "refuse", "ep": false, "versions": [{"stem": "refuse_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 9 Lyric Mine", "folder": "2026-10-09-Lyric-Mine", "title": "Refuse", "lyrics": "[Intro: one slow, deep breath in, held, released, then the drums]\n\n[Verse 1: 7:36 p.m.]\nMarch fifteenth, '25, seven thirty-six, I told the truth for once:\n\"I have been doing so much better emotionally.\" Months\nOf sun through the blinds. \"Deep down I am not ok. I am still torn apart inside.\"\nEvery day a moment comes where I gotta get away and hide.\n\"In those moments, I get emotional and I honestly feel so much hate towards you.\"\nThere. I said it. Hate. Not \"hurt,\" not \"sad,\" the real word. Brand new.\n\"I don't show it anymore and I don't say a word to anybody.\"\nA man with a storm in his chest at a kid's recital, nodding, polite, and nobody\nKnows. \"I sit back, alone, take a deep breath,\" and fight it down,\nLike a fever I sweat out on the couch while the house don't make a sound.\n[double-time] It comes up like heartburn, it comes up like bile, it comes up like the tide in a basement, a flood with a smell, and I'm bailing it out with a bucket, a breath, and a breath, and a breath,\nAnd I'm counting to four and I'm holding to four and I'm pushing it down to the floor of the ocean, the anchor, the weight, and the chain, till it's quiet again in my chest,\n[half-time] I fight back all the bad.\n[pause] Every day.\n\n[Hook: chanted low, doubled]\nI refuse to hate you. Refuse.\nFourteen years the center of my world. I refuse.\nFeel it come up every day. I breathe. I sit. I lose\nThe fight sometimes. And still I refuse.\nI refuse to hate you. Refuse.\nFourteen years the center of my world. I refuse.\nFeel it come up every day. I breathe. I sit. I lose\nThe fight sometimes. And still I refuse.\n\n[Verse 2: 9:49 p.m.]\nTwo hours later, I'm typing a treaty with the same two hands:\n\"We have to stop arguing, fighting and letting this hate get the best of us.\" Stand\nDown. \"So please work with me because I can't do it alone.\"\nSame man who admitted the hate, now holding out a phone\nLike a white flag. \"I mean no harm towards you, especially today.\"\n\"I do not want to hate or fight you.\" The storm's still there; it's held at bay.\n\"Even now after all this, I still feel like I am willing to help carry you.\"\nThink about that: the man who said \"hate\" at seven-thirty, and at nine, \"I'll carry you.\"\nThat ain't a contradiction. That's the whole job. That's the work.\nFeeling the hate and choosing the carry. That's a man. That's what it's worth.\n[double-time] \"My door is still open and I am still trying,\" I wrote it with the anger still warm in the cup, like a guy who just burned his hand on the stove and is cooking you dinner anyway,\n'Cause the hate is a feeling and feeling ain't doing, the doing is mine, and the doing is gentle, the doing is \"help,\" and the doing is \"partners ended, parents remain,\" and I stay,\n[half-time] One minute later: \"Ok that hit me hard.\"\n[pause] Couldn't talk.\n\n[Hook: chanted low, doubled]\nI refuse to hate you. Refuse.\nFourteen years the center of my world. I refuse.\nFeel it come up every day. I breathe. I sit. I lose\nThe fight sometimes. And still I refuse.\n\n[Verse 3: 10:14 p.m., strings drop out]\nTen fourteen, the last one that night, the shortest, the truest:\n\"I will still fight for you as in I have your back.\" Not the newest\nKind of love. Old kind. Soldier kind. Air Force kind. Stand-your-post.\n\"If you need me, just ask and I will be there for you.\" Close.\nThen the line: \"You have been the center of my world for fourteen years\nAnd I refuse to hate you.\" Refuse. Not \"don't.\" Not \"can't.\" It's a gear\nYou put it in on purpose. Hate's the hill; refuse is the brake.\nFourteen years of orbit, and the sun went out. I'm still awake,\nStill circling. \"I am not feeling well so I am going to go now.\nI need to gather myself and help the kids.\" That's how\n[double-time] A man ends a day like that: not with a speech or a slam, but with \"take care of yourself, I hope you feel better,\" and then up the stairs to the kids with a face that he fixed in the car,\nAnd the hate's in the basement, the refusal's upstairs, and the kids are asleep, and he checks on 'em twice, and he sits on the end of the bed in the dark, and he don't let it into the house, and that's who you are,\n[half-time] \"Take care of yourself.\"\n[pause] I meant that too.\n\n[Final Hook: chanted low, doubled]\nI refuse to hate you. Refuse.\nFourteen years the center of my world. I refuse.\nFelt it. Said it. Breathed it out. Got nothing left to prove.\nThe hate was real. The refusal's realer. I refuse.\nI refuse to hate you. Refuse.\nFourteen years the center of my world. I refuse.\nFeel it come up every day. I breathe. I sit. I lose\nThe fight sometimes. And still I refuse.", "suno": {"title": "Refuse", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 88 BPM, heavy dusty drum break, hard dry snare, brooding minor-key piano loop, slow deep breath textures, low rumbling strings like a storm held back, deep distorted bass, vinyl crackle, raw intense mix; male mid-low rap, restrained intensity that nearly boils over, dense multisyllabic internal rhymes, rapid double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 9, 2026. Writer: Cue (Claude). Concept and hook: Scatta (\"You have been the center of my world for 14 years and I refuse to hate you.\" #076802, 10:14 p.m., March 15, 2025; with #076793 and #076797 from the same evening). Status: written listening candidate, unauditioned and unapproved.", "chars": 4574}], "title": "Refuse", "session": "Oct 9 Lyric Mine", "latest": "refuse_v01_Cue"}, {"slug": "reset", "ep": false, "versions": [{"stem": "reset_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 9 Lyric Mine", "folder": "2026-10-09-Lyric-Mine", "title": "Reset", "lyrics": "[Intro: a power-down whine, silence, a relay click, the break restarts]\n\n[Verse 1]\nThree thirty-five a.m., the whole chat vanished off the screen:\nSix years of us, gone, like somebody pulled the plug on the machine.\nFive forty-four: \"It makes me sad our entire telegram history is gone forever.\"\nFive fifty: \"Let's hit the reset button one more time.\" Six minutes. Clever,\nRight? The history got wiped, so I figured we could too:\nBlank page, fresh install, factory settings, me and you.\nSix thirty: marriage therapy, church, and eventually church group;\n\"Forget the past and let us try to get to know each other again.\" Proof\nOf how bad I wanted it: I wrote a plan before the sun was up,\nSix fifty-one, the big one, every word of it a cup held up:\n[double-time] \"Full stop reset. Let us kill the victims inside of us both. The past cannot be changed. Can we start again, one more time?\" and I'm typing like a man with the paddles,\n\"Drop all the resentment and hate, and start to date and find us again, a new start, a new beginning,\" and the sun coming up on the battle,\n[half-time] Can you do this with me?\n[pause] It's not going to be easy.\n\n[Hook: chanted hard, doubled]\nReset. Reset. Hit the button one more time.\nTry this one more time. Full stop. Kill the victims inside.\nReset. Reset. Power down and back to one.\nReset, reset, reset, please. The day ain't even done.\nReset. Reset. Hit the button one more time.\nTry this one more time. Full stop. Kill the victims inside.\nReset. Reset. Power down and back to one.\nReset, reset, reset, please. The day ain't even done.\n\n[Verse 2]\nNine a.m.: \"write it down,\" whatever you need, a list, a contract.\nNoon: \"just talk to me like we just met,\" like strangers making contact.\n\"Please give me a chance to rebuild this relationship from the ground up.\"\nI'm a contractor with no lumber, pouring a foundation out of \"sorry\" by the cup.\nOne-oh-five: \"Please. Reset.\" One-eleven: \"Reset reset reset please.\"\nTyping it three times like a kid who thinks the elevator's faster when you squeeze.\nFour fifty-two: \"So I guess no reset today.\" The machine won't take it.\nFour fifty-six: \"We both said lots of evil shit, okay? Reset this, please!\" Shaking.\nFour fifty-seven: \"Reset. I beg you.\" One minute later. Begging in the log,\nA man holding down a button on a device that's waterlogged.\n[double-time] Hold it for ten seconds, hold it for thirty, unplug it and plug it back in, take the battery out, let it sit, put it back, hit the power, the logo comes up and the screen goes to black,\nSame error, same code, same lights blinking amber, the progress bar stuck at the end, and the fans spinning up like they're trying, and nothing comes back,\n[half-time] So I guess no reset today.\n[pause] Day one. Over.\n\n[Hook: chanted hard, doubled]\nReset. Reset. Hit the button one more time.\nTry this one more time. Full stop. Kill the victims inside.\nReset. Reset. Power down and back to one.\nReset, reset, reset, please. The day ain't even done.\n\n[Verse 3: piano drops out, relay clicks and drums only]\nNovember: \"Are you not ready to do a full reset and try this one more time?\"\nDecember: \"Can we pls hit reset today?\" Like asking for a refund on a crime.\nNineteen times that year I typed it. Word wore out like a button's paint;\nYou can see the thumbprint worn into the plastic where I prayed like a saint.\nFebruary '25, the funniest sentence I ever wrote about some gear:\n\"I factory reset them and it kept rejecting it.\" Now read that again. Clear?\n\"I know how to do it, it should be ez, but it just did not want to connect.\"\nDamn near twenty years a tech, and the one thing I couldn't fix was the one I'd protect.\nUnplug the modem and the router, plug 'em back in. That works, mostly.\nDid it to a marriage all of '24. The light stayed red. Ghostly.\n[double-time] And the only reset that ever took was the one where I unplugged me, took a day for myself in the spring of '26, sat still and just let the system cool,\nNo button, no begging, no list and no plan, just a man in a quiet room letting the fans spin down, booting up slow in safe mode, a fool learning a different rule,\n[half-time] Rebooting.\n[pause] One device.\n\n[Final Hook: chanted hard, doubled]\nReset. Reset. Hit the button one more time.\nTry this one more time. Full stop. Kill the victims inside.\nReset. Reset. Power down and back to one.\nReset the only thing I can: me. The day ain't even done.\nReset. Reset. Hit the button one more time.\nTry this one more time. Full stop. Kill the victims inside.\nReset. Reset. Power down and back to one.\nReset, reset, reset, please. The day ain't even done.", "suno": {"title": "Reset", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 92 BPM, hard punchy drum break that cuts out and restarts, dry cracking snare, tense minor-key piano loop, electrical power-down and boot-up chime textures, relay clicks, deep distorted bass, vinyl grit, raw mix; male mid-low rap, pleading urgent delivery turning cold and technical, dense internal rhymes, rapid double-time bursts, hard chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 9, 2026. Writer: Cue (Claude). Concept and hook phrases: Scatta (your October 8, 2024 messages, #068702 to #068924; Lyric Mine, \"Reset\"). Status: written listening candidate, unauditioned and unapproved.", "chars": 4595}, {"stem": "reset_v02_Cue", "version": 2, "writer": "Cue", "session": "Oct 9 Lyric Mine", "folder": "2026-10-09-Lyric-Mine", "title": "Reset", "lyrics": "[Intro: a power-down whine, silence, a relay click, the break restarts]\n\n[Verse 1]\nThree thirty-five a.m., the whole chat vanished off the screen:\nSix years of us, gone, like somebody pulled the plug on the machine.\nFive forty-four: \"It makes me sad our entire telegram history is gone forever.\"\nFive fifty: \"Let's hit the reset button one more time.\" Six minutes. Clever,\nRight? The history got wiped, so I figured we could too:\nBlank page, fresh install, factory settings, me and you.\nSix thirty: marriage therapy, church, and eventually church group;\n\"Forget the past and let us try to get to know each other again.\" Proof\nOf how bad I wanted it: I wrote a plan before the sun was up,\nSix fifty-one, the big one, every word of it a toast held up:\n[double-time] \"Full stop reset. Let us kill the victims inside of us both. The past cannot be changed. Can we start again, one more time?\" and I'm typing like a man with the paddles,\n\"Drop all the resentment and hate, and start to date and find us again, a new start, a new beginning,\" and the sun coming up on the battle,\n[half-time] Can you do this with me?\n[pause] It's not going to be easy.\n\n[Hook: chanted hard, doubled]\nReset. Reset. Hit the button one more time.\nTry this one more time. Full stop. Kill the victims inside.\nReset. Reset. Power down and back to one.\nReset, reset, reset, please. The day ain't even done.\nReset. Reset. Hit the button one more time.\nTry this one more time. Full stop. Kill the victims inside.\nReset. Reset. Power down and back to one.\nReset, reset, reset, please. The day ain't even done.\n\n[Verse 2]\nNine a.m.: \"write it down,\" whatever you need, a list, a contract.\nNoon: \"just talk to me like we just met,\" like strangers making contact.\n\"Please give me a chance to rebuild this relationship from the ground up.\"\nI'm a contractor with no lumber, pouring \"sorry\" for concrete, and it won't set up.\nOne-oh-five: \"Please. Reset.\" One-eleven: \"Reset reset reset please.\"\nThree times, like a kid jabbing the elevator button: please, please, please.\nFour fifty-two: \"So I guess no reset today.\" The machine won't take it.\nFour fifty-six: \"We both said lots of evil shit, okay? Reset this, please!\" Shaking.\nFour fifty-seven: \"Reset. I beg you.\" One minute later. Begging in the log,\nA man holding down a button on a device that's waterlogged.\n[double-time] Hold it for ten seconds, hold it for thirty, unplug it and plug it back in, take the battery out, let it sit, put it back, hit the power, the logo comes up and the screen goes to black,\nSame error, same code, same lights blinking amber, the progress bar stuck at the end, and the fans spinning up like they're trying, and nothing comes back,\n[half-time] So I guess no reset today.\n[pause] Day one. Over.\n\n[Hook: chanted hard, doubled]\nReset. Reset. Hit the button one more time.\nTry this one more time. Full stop. Kill the victims inside.\nReset. Reset. Power down and back to one.\nReset, reset, reset, please. The day ain't even done.\n\n[Verse 3: piano drops out, relay clicks and drums only]\nNovember: \"Are you not ready to do a full reset and try this one more time?\"\nDecember: \"Can we pls hit reset today?\" Like a gambler with his last chip: one more time.\nNineteen times that year I typed it. Word wore out like a button's paint;\nYou can see the thumbprint worn into the plastic where I prayed like a saint.\nFebruary '25, the funniest sentence I ever wrote about some gear:\n\"I factory reset them and it kept rejecting it.\" Now read that again. Clear?\n\"I know how to do it, it should be ez, but it just did not want to connect.\"\nDamn near twenty years a tech, and the one thing I couldn't fix was the one I'd protect.\nUnplug the modem and the router, plug 'em back in. That works, mostly.\nDid it to a marriage all of '24. The light stayed red. Ghostly.\n[double-time] And the only reset that ever took was the one where I unplugged me, took a day for myself in the spring of '26, sat still and just let the system cool,\nNo button, no begging, no list and no plan, just a man in a quiet room letting the fans spin down, booting up slow in safe mode, a fool learning a different rule,\n[half-time] Rebooting.\n[pause] One device.\n\n[Final Hook: chanted hard, doubled]\nReset. Reset. Hit the button one more time.\nTry this one more time. Full stop. Kill the victims inside.\nReset. Reset. Power down and back to one.\nReset the only thing I can: me. The day ain't even done.\nReset. Reset. Hit the button one more time.\nTry this one more time. Full stop. Kill the victims inside.\nReset. Reset. Power down and back to one.\nReset, reset, reset, please. The day ain't even done.", "suno": {"title": "Reset", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 92 BPM, hard punchy drum break that cuts out and restarts, dry cracking snare, tense minor-key piano loop, electrical power-down and boot-up chime textures, relay clicks, deep distorted bass, vinyl grit, raw mix; male mid-low rap, pleading urgent delivery turning cold and technical, dense internal rhymes, rapid double-time bursts, hard chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v02. October 9, 2026. Writer: Cue (Claude). Concept and hook phrases: Scatta (your October 8, 2024 messages, #068702 to #068924; Lyric Mine, \"Reset\"). Status: written listening candidate, unauditioned and unapproved.", "chars": 4606}], "title": "Reset", "session": "Oct 9 Lyric Mine", "latest": "reset_v02_Cue"}, {"slug": "smaller", "ep": false, "versions": [{"stem": "smaller_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 9 Lyric Mine", "folder": "2026-10-09-Lyric-Mine", "title": "Smaller", "lyrics": "[Intro: a hospital hallway hum, a door closing far away, the piano, then the drums]\n\n[Verse 1]\nBack then, all I saw was the stress, the shifts, the time away from us;\n\"Money we didn't need as much as we needed time together.\" That's what I trust\nI meant. \"Some of your shifts meant you barely saw the kids,\" and it weighed on me\nLike a lead apron in X-ray. \"I really thought having you home more\" was the remedy.\nAnd I'll say the ugly part out loud, since I'm the one who wrote it:\nI called it your \"plush dream job.\" In a text. In December. Quote it.\nThat's a man who's scared of losing something, swinging at the thing he's losing to;\nA jab dressed as a question mark. I'd never send it now. That's true.\nSo I won't sit here and say I never got it wrong. I did.\nI got it wrong with good intentions, which is wrong with a better alibi. Kid.\n[double-time] I thought I was holding the ladder, I thought I was holding the door, I was holding the house and the bills and the kids and the calendar, thinking that holding was helping,\nAnd maybe I held it so tight that the hand looked a lot like a fist, and the ladder looked like a cage, and the door looked locked, and the help looked like smothering, swelling,\n[half-time] I may have misread what you needed.\n[pause] I'll own that.\n\n[Hook: chanted low, doubled]\nI may have misread what you needed.\nMy intent was never to make you smaller.\nOwn what I did, every word that I said and repeated.\nNever tried to make you smaller.\nI may have misread what you needed.\nMy intent was never to make you smaller.\nOwn what I did, every word that I said and repeated.\nNever tried to make you smaller.\n\n[Verse 2]\nJuly '26, I finally saw it: \"work wasn't just about money for you.\nIt was about identity, growth, and feeling capable.\" Who knew?\nMe. I should have known. Me, of all people on the planet:\n\"I forget about you at work and I become myself.\" I said it. Damn it.\n\"I told them work was my happy place and home was miserable.\" That's mine.\nThe BMET in the break room with the multimeter shining. Fine.\nSo I knew exactly what a job can be: the one room where you're good,\nThe one place nobody's grading you on how you love. Understood.\nAnd I tried to talk you out of the same room that was saving me.\nHypocrite in scrubs. Two people drowning, and each one blaming the sea.\n[double-time] Your work was your oxygen, mine was the same, and I'm standing in front of your tank with a wrench and a smile saying \"home is the better air,\" and I meant it, I swear that I meant it,\nWhile I'm breathing at work like a man who came up from the bottom of the lake, gasping and laughing with techs in the shop, and I couldn't see I was doing the thing I resented,\n[half-time] I wish I had understood that better.\n[pause] Back then.\n\n[Hook: chanted low, doubled]\nI may have misread what you needed.\nMy intent was never to make you smaller.\nOwn what I did, every word that I said and repeated.\nNever tried to make you smaller.\n\n[Verse 3: strings drop out, piano and drums only]\nAnd here's the line I'm drawing, July eighth, plain as a work order:\n\"I can accept that some of my actions made you feel hurt,\" cross the border,\n\"Unheard, invalidated, or unsupported. I am willing to own\nThe specific things I actually did.\" Owned. Signed. On loan\nTo nobody. \"What I am not willing to keep accepting is you defining who I am,\nWhat my love meant, or what my motives were.\" That's the dam.\nI'll take the charges that are real. I won't take the character assassination.\nAccountability ain't a confession to everything. It's a calibration.\n\"I knew I would never leave you,\" not for a trillion dollars, any face,\n\"Fat, old, deformed, a vegetable.. It didn't matter.\" That was the place\n[double-time] My love was coming from, a heart that I swear was in the right spot, even when the hands were in the wrong one, even when the timing was wrong, and the words, and the tone, and the reasons were tangled,\nAnd I wish I could see myself from your perspective, just once, through your eyes, like a camera you held, from the side of the room, from the angle,\n[half-time] \"It would not change anything.\n[pause] But it would help me understand.\"\n\n[Final Hook: chanted low, doubled]\nI may have misread what you needed.\nMy intent was never to make you smaller.\nOwn what I did. Won't own what you said that I meant.\nNever tried to make you smaller.\nI may have misread what you needed.\nMy intent was never to make you smaller.\nOwn what I did, every word that I said and repeated.\nNever tried to make you smaller.", "suno": {"title": "Smaller", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 87 BPM, steady dusty drum break, soft dry snare, grave minor-key piano and low string loop, distant hospital hallway ambience, warm deep bass, vinyl crackle, restrained mature mix; male mid-low rap, measured honest delivery that stays firm, dense internal rhymes, controlled double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 9, 2026. Writer: Cue (Claude). Concept and hook: Scatta (\"I may have misread what you needed, but my intent was never to make you smaller.\" #081275, July 9, 2026; Lyric Mine, The 30 lines, no. 30). Status: written listening candidate, unauditioned and unapproved.", "chars": 4513}], "title": "Smaller", "session": "Oct 9 Lyric Mine", "latest": "smaller_v01_Cue"}, {"slug": "spouses-enemies-colleagues", "ep": false, "versions": [{"stem": "spouses-enemies-colleagues_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 9 Lyric Mine", "folder": "2026-10-09-Lyric-Mine", "title": "Spouses, Enemies, Colleagues", "lyrics": "[Intro: a printer warms up, a keyboard clacks, an office phone rings twice, the break]\n\n[Verse 1: Spouses]\nSpouses: the word on the insurance form, the box I checked with pride,\nThe house we were gonna find together, one of my life goals, on the side\nOf every daydream on the drive to work. \"To find a house WITH you.\"\nCaps lock on the WITH, like I could hold it there with glue.\nRanked you number one; I listened to the pods, they said \"be number one,\"\nThen I typed it out: \"Not even your #2, 3, 4 or #5.\" Then I'm done\nCounting down the list like New Year's, \"6, 7, 8, 9 or 10.\"\nDidn't make the top ten in my own house. Count it up again.\nSpouses: two names on a lease, a joint account, a shared bed,\nA word that used to mean \"on the same side\" and now just means \"wed.\"\n[double-time] Spouse is a word on a form at the hospital, next of kin, emergency contact, the one that they call if the man on the table don't wake, it's the name on the line,\nSpouse is the one who decides when they pull it, the plug or the paddles, the one with the say, and I trusted you with it, I signed it, I'd sign it again any time,\n[half-time] Spouses.\n[pause] That was a long time ago.\n\n[Hook: chanted hard, doubled]\nSpouses. Enemies. Colleagues.\nWhat are we even doing here? Seriously.\nWent from \"I do,\" to \"I'm done,\" to \"per my last email.\"\nWhat are we even doing here? Seriously.\nSpouses. Enemies. Colleagues.\nWhat are we even doing here? Seriously.\nWent from \"I do,\" to \"I'm done,\" to \"per my last email.\"\nWhat are we even doing here? Seriously.\n\n[Verse 2: Enemies]\nEnemies: the summer of '24, every text a grenade with the pin pulled,\nEvery room a trench, every hallway a front line, every bin full.\nYou said I talked to you like a coworker. Then I swore I didn't.\nLook at that: a prophecy, in June, and neither one of us could hear it.\nBoth of us said shit you can't unsay. I own mine. Not all of it's mine.\nEnemies don't need a reason; enemies just need a time.\nTwo people who know where every landmine's buried 'cause they buried them together;\nFourteen years of maps, and we used 'em for the worst weather.\n\"Not as an enemy,\" I wrote two years later, asking to be spoken to like a person.\nThat's the treaty language. That's how bad the war got. It was worse than\n[double-time] The worst that I knew we could be, I knew all of your buttons and you knew all of mine, it's a war between two people holding the codes to each other, a mutually assured destruction of a family dinner,\nEvery holiday a ceasefire, every birthday a summit, every pickup a prisoner swap, every message a missile, and nobody wins, there's no winner,\n[half-time] Enemies.\n[pause] Never wanted to be yours.\n\n[Hook: chanted hard, doubled]\nSpouses. Enemies. Colleagues.\nWhat are we even doing here? Seriously.\nWent from \"I do,\" to \"I'm done,\" to \"per my last email.\"\nWhat are we even doing here? Seriously.\n\n[Verse 3: Colleagues]\nDecember second, '24, eleven fifty-five: \"What are we even doing here?\"\nHouse hunting by myself. You said let you know ahead of time. Clear.\n\"Looking for a house without you feels so wrong.\" A colleague's courtesy:\nLet you know ahead of time, like a meeting invite. Outlook. Two of me.\nColleagues: shift change at the door, a handoff with a report,\n\"Kids ate, homework's done, she's got a cough.\" Then out. Abort.\nPer my last email. Let's circle back. Loop me in. Noted.\nThe marriage has a Slack channel now, and everybody muted it, quoted.\n\"Are you planning on trying to build a future with or without me?\"\nNobody answered. That's a colleague: polite and never doubtful, never about me.\n[double-time] Spouses to enemies, enemies to colleagues, colleagues to strangers, the org chart of us with a line that goes down and goes down like a heart on a monitor flattening out into green,\nNext it's acquaintances, then it's a name in a phone, then a face at a graduation, a nod and a wave, two parents in the bleachers, one row in between,\n[half-time] What are we even doing here?\n[pause] Seriously.\n\n[Final Hook: chanted hard, doubled, the office phone keeps ringing]\nSpouses. Enemies. Colleagues. Strangers.\nWhat are we even doing here? Seriously.\nWent from \"I do,\" to \"I'm done,\" to \"per my last email.\"\nNow it's \"thanks,\" and \"got it,\" and \"see you Sunday.\" Seriously.\nSpouses. Enemies. Colleagues.\nWhat are we even doing here? Seriously.\nWent from \"I do,\" to \"I'm done,\" to \"per my last email.\"\nWhat are we even doing here? Seriously.", "suno": {"title": "Spouses, Enemies, Colleagues", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 90 BPM, hard dusty drum break, cracking dry snare, brooding minor-key piano loop, office textures of keyboard clicks, a printer and a distant phone, ominous low strings, deep bass, vinyl grit, raw mix; male mid-low rap, sardonic weary delivery with bursts of anger, dense multisyllabic internal rhymes, rapid double-time bursts, hard chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 9, 2026. Writer: Cue (Claude). Concept and title: Scatta (\"I feel like we went from spouses to enemies and now we are more like colleagues?\" #072331, December 2, 2024; Lyric Mine, The 30 lines, no. 16). Status: written listening candidate, unauditioned and unapproved.", "chars": 4424}, {"stem": "spouses-enemies-colleagues_v02_Cue", "version": 2, "writer": "Cue", "session": "Oct 9 Lyric Mine", "folder": "2026-10-09-Lyric-Mine", "title": "Spouses, Enemies, Colleagues", "lyrics": "[Intro: a printer warms up, a keyboard clacks, an office phone rings twice, the break]\n\n[Verse 1: Spouses]\nSpouses: the word on the insurance form, the box I checked with pride,\nThe house we were gonna find together, one of my life goals, on the side\nOf every daydream on the drive to work. \"To find a house WITH you.\"\nCaps lock on the WITH, like I could hold it there with glue.\nRanked you number one; I listened to the pods, they said \"be number one,\"\nThen I typed it out: \"Not even your #2, 3, 4 or #5.\" Then I'm done\nCounting down the list like New Year's, \"6, 7, 8, 9 or 10.\"\nDidn't make the top ten in my own house. Count it up again.\nSpouses: two names on a lease, a joint account, a shared bed,\nA word that used to mean \"on the same side\" and now just means \"wed.\"\n[double-time] Spouse is a word on a form at the hospital, next of kin, emergency contact, the one that they call if the man on the table don't wake, it's the name on the line,\nSpouse is the one who decides when they pull it, the plug or the paddles, the one with the say, and I trusted you with it, I signed it, I'd sign it again any time,\n[half-time] Spouses.\n[pause] That was a long time ago.\n\n[Hook: chanted hard, doubled]\nSpouses. Enemies. Colleagues.\nWhat are we even doing here? Seriously.\nWent from \"I do,\" to \"I'm done,\" to \"per my last email.\"\nWhat are we even doing here? Seriously.\nSpouses. Enemies. Colleagues.\nWhat are we even doing here? Seriously.\nWent from \"I do,\" to \"I'm done,\" to \"per my last email.\"\nWhat are we even doing here? Seriously.\n\n[Verse 2: Enemies]\nEnemies: the summer of '24, every text a live round,\nEvery room a trench, every hallway no man's land, every dinner a battleground.\nYou said I talked to you like a coworker. I swore I'd never.\nLook at that: a prophecy in June, and we were both too clever.\nBoth of us said shit you can't unsay. I own mine. Not all of it's mine.\nEnemies don't need a reason; enemies just need a time.\nTwo people who know where every landmine's buried 'cause they buried them together;\nFourteen years of maps, and we used 'em for the worst weather.\n\"Not as an enemy,\" I wrote two years later, asking to be spoken to like a person.\nThat's the treaty language. That's how bad the war got. It was worse than\n[double-time] The worst that I knew we could be, I knew all of your buttons and you knew all of mine, it's a war between two people holding the codes to each other, a mutually assured destruction of a family dinner,\nEvery holiday a ceasefire, every birthday a summit, every pickup a prisoner swap, every message a missile, and nobody wins, there's no winner,\n[half-time] Enemies.\n[pause] Never wanted to be yours.\n\n[Hook: chanted hard, doubled]\nSpouses. Enemies. Colleagues.\nWhat are we even doing here? Seriously.\nWent from \"I do,\" to \"I'm done,\" to \"per my last email.\"\nWhat are we even doing here? Seriously.\n\n[Verse 3: Colleagues]\nDecember second, '24, eleven fifty-five: \"What are we even doing here?\"\nHouse hunting by myself. You said let you know ahead of time. Clear.\n\"Looking for a house without you feels so wrong.\" A colleague's courtesy:\nLet you know ahead of time, like a meeting invite. RSVP.\nColleagues: shift change at the door, a handoff with a report,\n\"Kids ate, homework's done, she's got a cough.\" Then out. Abort.\nPer my last email. Let's circle back. Loop me in. Noted.\nThe marriage has a Slack channel now, and everybody muted it. Demoted.\n\"Should we move on together or separately?\"\nLeft on read. That's a colleague. Reply-all to nobody. Desperately.\n[double-time] Spouses to enemies, enemies to colleagues, colleagues to strangers, the org chart of us with a line that goes down and goes down like a heart on a monitor flattening out into green,\nNext it's acquaintances, then it's a name in a phone, then a face at a graduation, a nod and a wave, two parents in the bleachers, one row in between,\n[half-time] What are we even doing here?\n[pause] Seriously.\n\n[Final Hook: chanted hard, doubled, the office phone keeps ringing]\nSpouses. Enemies. Colleagues. Strangers.\nWhat are we even doing here? Seriously.\nWent from \"I do,\" to \"I'm done,\" to \"per my last email.\"\nNow it's \"thanks,\" and \"got it,\" and \"see you Sunday.\" Seriously.\nSpouses. Enemies. Colleagues.\nWhat are we even doing here? Seriously.\nWent from \"I do,\" to \"I'm done,\" to \"per my last email.\"\nWhat are we even doing here? Seriously.", "suno": {"title": "Spouses, Enemies, Colleagues", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 90 BPM, hard dusty drum break, cracking dry snare, brooding minor-key piano loop, office textures of keyboard clicks, a printer and a distant phone, ominous low strings, deep bass, vinyl grit, raw mix; male mid-low rap, sardonic weary delivery with bursts of anger, dense multisyllabic internal rhymes, rapid double-time bursts, hard chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v02. October 9, 2026. Writer: Cue (Claude). Concept and title: Scatta (\"I feel like we went from spouses to enemies and now we are more like colleagues?\" #072331, December 2, 2024; Lyric Mine, The 30 lines, no. 16). Status: written listening candidate, unauditioned and unapproved.", "chars": 4360}], "title": "Spouses, Enemies, Colleagues", "session": "Oct 9 Lyric Mine", "latest": "spouses-enemies-colleagues_v02_Cue"}, {"slug": "strangers-who-are-civil", "ep": false, "versions": [{"stem": "strangers-who-are-civil_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 9 Lyric Mine", "folder": "2026-10-09-Lyric-Mine", "title": "Strangers Who Are Civil", "lyrics": "[Intro: rain on a windshield, the piano loop, then the drums]\n\n[Verse 1]\nApril '25, the best day in a year was a day where nothing happened:\nNo fighting, no tension, nobody keeping score, nobody snapping.\n\"It felt impersonal yet respectful.\" Five stars. Write it down.\nBest night we'd had in a year: two adults being polite in my house.\n\"Partners ended, parents never will.\" I wrote that back in March,\nLike a treaty signed on a napkin with the war still in my heart.\n\"If you want me to answer quicker, ask the kids to tell me.\" Peace out.\nThat's an embassy with juice boxes, diplomats in braces. Keep it down.\nThat's diplomacy in our house: send the twelve-year-old with the message,\nAnd pray the courier don't read it, 'cause the courier's the one who gets it.\n[double-time] No pressure, no expectations, no fighting, no tension, no nothing to argue or be mad about, a silence so clean you could set it as a table and serve it with forks,\nA conversation like a hallway in a hospital at midnight, polished and quiet and empty and lit, with the colored lines guiding you down to the doors,\n[half-time] Nothing happened.\n[pause] Best day all year.\n\n[Hook: chanted low, doubled]\nStrangers who are civil. Civil.\nBetter than the war, better than the hostile.\nNod at the door, kids in the middle, keep it simple:\nI'd rather we be strangers who are civil.\nStrangers who are civil. Civil.\nBetter than the war, better than the hostile.\nNod at the door, kids in the middle, keep it simple:\nI'd rather we be strangers who are civil.\n\n[Verse 2]\nFebruary '26, I started therapy to learn to be around you.\nNot for us. For the kids. For the doorway and the driveway, the drop-off. Found you\nTough to stand near; I'm not proud of that. I'm saying it plain.\nAsked to be spoken to like a person, not an enemy. That's the whole campaign.\nBasic respect. That's the list. One item. No fine print.\nFelt like a lot to ask, and that should tell you where the time went.\nI still carry a lot of hurt; I get guarded when you're near,\nLike a hand that touched a stove once, flinching at the kitchen. Here,\nI'm learning how to stand still in a room that used to burn,\nHow to say \"hi\" like a word and not a weapon. Still learning.\n[double-time] Breathe in for four, hold it for four, let it go for four, in a waiting room reading the posters on anger and grief and the stages, I'm stuck between three and four,\nPracticing sentences out loud in the car like a speech at the UN, \"Hi, how are you, the girls got a concert on Friday, okay, have a good night,\" then I'm out the door,\n[half-time] Hi. How are you.\n[pause] Took a therapist to say that.\n\n[Hook: chanted low, doubled]\nStrangers who are civil. Civil.\nBetter than the war, better than the hostile.\nNod at the door, kids in the middle, keep it simple:\nI'd rather we be strangers who are civil.\n\n[Verse 3: horns drop out, piano and rain only]\nMay, I put it plain: no pressure. You want it how it is? I'll respect it.\n\"I'd rather we feel like strangers who are civil than hostile.\" I meant it.\n\"I'd rather stay in my lane.\" A lane. A highway with a median wall:\nTwo cars doing seventy in the same direction, never touching at all.\nWe started out as strangers. Gonna finish as strangers too.\nOnly difference: now the strangers share three kids and a calendar view.\nAugust, I wrote it final: we're the parents of three children,\nSo there will always be things to talk about. \"I will do that.\" Bill it.\nNot a love song. Not a hate song. Something rarer than the both:\nA song about two people keeping one unspoken oath.\n[double-time] A nod at the door, a wave from the car, a text about pickup, a thumbs-up, a \"thanks,\" and a \"got it,\" a \"see you on Sunday,\" as polite as a priest at a funeral he wasn't invited to,\nThat's the whole marriage now, a couple of sentences, signed and delivered and civil and quiet, and nobody yelling, and honestly that is the most I can do,\n[half-time] Civil.\n[pause] It's not nothing.\n\n[Final Hook: chanted low, doubled, drums thin out]\nStrangers who are civil. Civil.\nBetter than the war, better than the hostile.\nStarted out as strangers. We'll finish as strangers. Simple.\nI'd rather we be strangers who are civil.\nStrangers who are civil. Civil.\nBetter than the war, better than the hostile.\nNod at the door, kids in the middle, keep it simple:\nI'd rather we be strangers who are civil.", "suno": {"title": "Strangers Who Are Civil", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 86 BPM, steady dusty drum break, soft dry snare, somber minor-key piano and muted horn swell loop, warm low upright bass, distant rain texture, vinyl crackle, restrained mature mix; male mid-low rap, calm measured confessional delivery with dry wit, dense internal rhymes, smooth double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 9, 2026. Writer: Cue (Claude). Concept and hook phrase: Scatta (\"I'd rather we feel like strangers who are civil than hostile,\" #080658, May 4, 2026; Lyric Mine). Status: written listening candidate, unauditioned and unapproved.", "chars": 4342}], "title": "Strangers Who Are Civil", "session": "Oct 9 Lyric Mine", "latest": "strangers-who-are-civil_v01_Cue"}, {"slug": "the-bennys", "ep": false, "versions": [{"stem": "the-bennys_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 9 Lyric Mine", "folder": "2026-10-09-Lyric-Mine", "title": "The Bennys", "lyrics": "[Intro: a music box winds down, out of tune, then the drums]\n\n[Verse 1]\nTwenty-two, December: \"If u see benny pls get.\"\nA plush Bigfoot named Benny, and a grown man's new obsession. Bet.\nStarted as a thing with my daughter, me and her against the shelves,\nTwo collectors on a mission, hunting stuffed cryptids for ourselves.\nWalmart, Aldi, the mall, a link to a store I'll never visit;\n\"Orange Benny.\" Two words in a text at three fifty-one. Exquisite.\nShe'd light up when we found one; I'd light up 'cause she did.\nThat's the whole collection: a reason to be a kid with my kid.\nShelf in the bedroom lined with Bigfoots like a jury of soft monsters,\nEvery one of 'em a Saturday, a parking lot, a \"Dad, you got this?\" Conquer.\n[double-time] The hunt was the gift, the drive was the gift, the aisle and the giggle, the \"there's one, there's one,\" and the race to the bin and the high five, the receipt in the bag on the floor of the van,\nAnd the plush was a souvenir, nothing but stuffing and fabric and tags, what I wanted was the hour with her in the store, and I didn't know that was the point till I lost it, my man,\n[half-time] Benny the Bigfoot.\n[pause] Easy to find, back then.\n\n[Hook: chanted low, doubled]\nHours and hours hunting Bigfoot,\nEvery store in Michigan, every shelf, every nook.\nI was home with the kids. Easier to find than a myth.\nI don't want the Benny. I want the time it took. That's it.\nHours and hours hunting Bigfoot,\nEvery store in Michigan, every shelf, every nook.\nI was home with the kids. Easier to find than a myth.\nI don't want the Benny. I want the time it took. That's it.\n\n[Verse 2]\nJuly thirtieth, '24, three thirty-six a.m., I tried to explain:\n\"My comment about gifts had nothing to do with gifts.\" Plain.\n\"It was about the time you spent getting people stuff,\"\nThe time spent looking, driving, dropping off. Not the stuff. Enough.\n\"My love language was zero percent gifts.\" Zero. I did the math.\nYou were out hunting Bigfoot; I was home running the kids' bath.\n\"I remember there were days that you would spend hours and hours looking for one,\"\nWhile I'm at the house with three kids and a TV and a microwave and nobody. Done.\n\"I know that maybe in your heart you felt like you were buying them to show me you loved me.\"\nI believe that. I still do. That's the part that makes it ugly.\n[double-time] You were giving me Bigfoots, I wanted the hours, you gave me the hours in the shape of a Bigfoot, the love was translated and lost in the mail like a package delivered to the wrong address,\nAnd I'm holding a plush in the doorway at night like a man with a gift card for something he doesn't want, from someone who meant it, and that is the saddest receipt in the nest,\n[half-time] Thank you.\n[pause] But stay.\n\n[Hook: chanted low, doubled]\nHours and hours hunting Bigfoot,\nEvery store in Michigan, every shelf, every nook.\nI was home with the kids. Easier to find than a myth.\nI don't want the Benny. I want the time it took. That's it.\n\n[Verse 3: music box returns, drums thin]\n\"Did you not notice I stopped collecting them?\" That's the line.\nI quit the hunt, and nobody noticed. That's a sign.\n\"I did it more for\" my daughter \"and that connection we had,\"\nAnd the connection outgrew the Bennys like she's outgrowing her dad.\nNow they're in a box with a question mark, the Bigfoot jury, all retired,\nFifteen soft monsters staring at the tape like they got fired.\nFunny thing about a Bigfoot: everybody swears it's out there;\nPeople spend their whole life looking, blurry photos, in the woods, despair.\nI was looking for a marriage like the blurry photo in a tabloid,\nAnd the realest thing in the woods was the kid holding my hand. Avoid\n[double-time] The lesson, I don't want a lesson, I want the girls on a Saturday, any store, any aisle, any parking lot, any excuse for a drive, and the time, just the time, and the time,\nAnd if I ever buy another Benny it'll be for the hour it takes to find it with her, not the plush, not the shelf, not the tag, not the gift, just the hunt, just the hunt, and that's mine,\n[half-time] The gift was time.\n[pause] It always was.\n\n[Final Hook: chanted low, doubled, music box alone at the end]\nHours and hours hunting Bigfoot,\nEvery store in Michigan, every shelf, every nook.\nStopped collecting. Did you notice? Nobody looked.\nI don't want the Benny. I want the time it took. That's it.\nHours and hours hunting Bigfoot,\nEvery store in Michigan, every shelf, every nook.\nI was home with the kids. Easier to find than a myth.\nI don't want the Benny. I want the time it took. That's it.", "suno": {"title": "The Bennys", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 88 BPM, dusty drum break, soft dry snare, detuned minor-key music box melody over a dark piano loop, low warm bass, store aisle hum and car door textures, vinyl crackle, melancholy raw mix; male mid-low rap, gentle wry confessional delivery, dense internal rhymes, smooth double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 9, 2026. Writer: Cue (Claude). Concept: Scatta (Seed Bank, \"The Bennys\"; your idea card \"The Gift Was Time\"; #068051, July 30, 2024). Status: written listening candidate, unauditioned and unapproved.", "chars": 4558}], "title": "The Bennys", "session": "Oct 9 Lyric Mine", "latest": "the-bennys_v01_Cue"}, {"slug": "the-pod", "ep": false, "versions": [{"stem": "the-pod_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 9 Lyric Mine", "folder": "2026-10-09-Lyric-Mine", "title": "The Pod", "lyrics": "[Intro: a muffled podcast voice, a pause click, a rewind, the break]\n\n[Verse 1]\nFourth of July, '24: Independence Day. The irony's thick.\nDoing bills, I type \"improve your marriage podcast.\" Click.\n\"Halfway through now, but this is amazing.\" I'm a convert. Baptized in the earbuds.\n\"I think I found a new hobby to replace my bag addiction.\" Word up.\nStarted that pod before nine a.m. Finished my notes at one.\nTwenty-eight-minute episode; took me over an hour for the second half. Done?\nNah. Back to the first half. Paused it, replayed it, made an outline in Word,\nBullet points on how to love you, indented, bolded, every third.\n\"This is life-altering, soul finding stuff.\" I meant it. Still do.\nUsed to quit every podcast in ten minutes. This one I listened through.\n[double-time] Pause it, rewind it, type it, highlight it, bullet it, bold it, a heading, a subheading, a quote from the host and a note to myself in the margin in red,\nA man with a degree in fixing machines going back to the classroom at forty with a laptop, a headset, a marriage on life support, and a syllabus inside his head,\n[half-time] This is wonderful.\n[pause] Listen to it with me.\n\n[Hook: chanted, doubled]\nThree hundred episodes. Paused it, rewound it, took notes in Word.\nTwenty-eight minutes took me four hours. Study hall. Absurd.\nHighlighter on the whole damn thing, every line underlined.\nStudying for the final in a class you dropped a long time.\nThree hundred episodes. Paused it, rewound it, took notes in Word.\nTwenty-eight minutes took me four hours. Study hall. Absurd.\nHighlighter on the whole damn thing, every line underlined.\nStudying for the final in a class you dropped a long time.\n\n[Verse 2]\nJuly nineteenth: \"I listened to three pods today.\" Teacher's pet.\nJuly twentieth: \"Omg I think he is talking about us!\" Not yet\nDid I know that every couple thinks the host is talking about them;\nEvery horoscope's a mirror if you're desperate. Read it. Count 'em.\nSent you links like homework: Spotify, YouTube, \"listen when you get time.\"\n\"You and your stupid podcast!\" Ouch. \"There are 300+ episodes.\" Fine.\nBut here's the part that ain't funny, the part I typed and meant:\n\"A lot of his pods prove you were right.\" I said it. Look. It's sent.\nAnd the fish bowl, the chase: \"Every time I tried, I looked more desperate,\nSeemed more needy, and this only caused you to pull further away.\" Accept it.\n[double-time] The more that I studied, the more that I chased, and the more that I chased it, the farther you swam to the side of the bowl, and I'm pressing my face to the glass with a pod in my ear,\nLearning the term for the thing I was doing while doing the thing, like a man in a fire reading a pamphlet on fire, and the smoke's getting thick, and the pamphlet is clear,\n[half-time] Pursuer. Distancer.\n[pause] Got an A in the chapter.\n\n[Hook: chanted, doubled]\nThree hundred episodes. Paused it, rewound it, took notes in Word.\nTwenty-eight minutes took me four hours. Study hall. Absurd.\nHighlighter on the whole damn thing, every line underlined.\nStudying for the final in a class you dropped a long time.\n\n[Verse 3: piano drops out, the clock ticks louder]\nDecember: \"I have never tried harder at anything in my entire life.\"\nEight months straight. Never studied that hard for the Air Force. Never for a wife\nBefore. \"I've tried self-help, I've tried podcasts about saving marriages,\nYoutube, books, reddit, google,\" individual and couples. Carriages\nPulling a hearse. Every step, I failed. That's the transcript. That's the grade.\nValedictorian of a school that closed the semester that I paid.\nApril '25, the honest line, the scariest, the one that bites:\n\"All the books, pods, therapy, trying to improve myself, trying to figure out how to solve you.\" Right?\nSolve you. Like an equation. Like a fault code on a monitor.\nYou can't troubleshoot a person into wanting you. I'm a slow learner.\n[double-time] A fight I could never win, a final I couldn't pass, a test with the answers in somebody else's handwriting, and I studied the wrong book for a year in the wrong room,\nSo I closed the laptop, and saved the doc, and I backed it up, of course I backed it up, it's in a folder called \"us\" on a drive in a box, like a dissertation for an empty tomb,\n[half-time] Class dismissed.\n[pause] I still have the notes.\n\n[Final Hook: chanted, doubled, the clock stops]\nThree hundred episodes. Paused it, rewound it, took notes in Word.\nTwenty-eight minutes took me four hours. Study hall. Absurd.\nLearned how to love somebody better. Learned it word for word.\nGraduated with honors in a class that only one of us heard.\nThree hundred episodes. Paused it, rewound it, took notes in Word.\nTwenty-eight minutes took me four hours. Study hall. Absurd.\nHighlighter on the whole damn thing, every line underlined.\nStudying for the final in a class you dropped a long time.", "suno": {"title": "The Pod", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 91 BPM, hard dusty drum break, dry snare, eerie minor-key piano and ticking clock loop, podcast-style muffled talking voice texture under the beat, pen scratches, deep dusty bass, vinyl crackle, raw mix; male mid-low rap, wry self-aware delivery turning raw, dense internal rhymes, rapid double-time bursts, chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 9, 2026. Writer: Cue (Claude). Concept: Scatta (Seed Bank, \"The Pod\" and \"A Fight I Could Never Win\"; #064074, #064077, #067590, #067351, #072652, #078635). Status: written listening candidate, unauditioned and unapproved.", "chars": 4857}], "title": "The Pod", "session": "Oct 9 Lyric Mine", "latest": "the-pod_v01_Cue"}, {"slug": "the-scattabrain-genius", "ep": false, "versions": [{"stem": "the-scattabrain-genius_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 9 Lyric Mine", "folder": "2026-10-09-Lyric-Mine", "title": "The ScattaBrain Genius", "lyrics": "[Intro: tape stutters, a scratch on \"scatter,\" then the break slams in]\n\n[Verse 1]\nPicture a kid with a head like a jar of loose screws, shaken;\nTeacher's talking, I'm a radio between two stations.\nRead a page, get to the bottom, and the top's already vapor;\nBack to the top, read it again, like a printer jammed with paper.\nSwore I was a good reader. Few minutes at a time.\nThen the words slide off the margin like the rain on a windshield. Blind.\n\"Always scatter-brained,\" that's the file that followed me,\nSmart kid, lazy kid, \"If he'd only apply himself,\" the eulogy.\nSo I named myself before they could, half insult and half a dare:\nScattaBrain Genius. Wrote it on everything. Still there.\n[double-time] Scattered like a bag of marbles on a gym floor rolling under the bleachers, the lockers, the doors and the vents, never the same way twice in a row, and nobody catching 'em,\nBut give me a reason, a fire, a deadline, a puzzle, a motive, I'll sit and I'll process for days till it's taken apart on the table and put back together, and stacking 'em,\n[half-time] Scatter-brained.\n[pause] Then genius. Sometimes.\n\n[Hook: chanted hard, doubled]\nAlways scatter-brained. ScattaBrain.\nSit me down with the motivation, I'm a genius. Same brain.\nI am no genius. I'm just smarter than I appear.\nScattaBrain Genius. Been him since a kid. I'm still here.\nAlways scatter-brained. ScattaBrain.\nSit me down with the motivation, I'm a genius. Same brain.\nI am no genius. I'm just smarter than I appear.\nScattaBrain Genius. Been him since a kid. I'm still here.\n\n[Verse 2]\nThirty years later: same brain, bigger mess, better lighting.\nPacked my lunch, left it by the trash can downstairs. Shrimp. I'm fighting\nBack tears over shrimp. Brewed a pot without the coffee in it;\nHot water, a filter and a grown man staring at it for a minute.\nTook a steak out of the freezer, put it somewhere. Never found it.\nIt's still out there thawing, free, a fugitive. I'm proud of it.\nCameras, then backpacks, then sling bags, then pouches for weeks;\n\"It's always something.\" Hyperfocus is a tunnel with no peak.\nPut a thing off for years, then it took me twenty seconds flat:\n\"Story of my life.\" \"I need a time and location or I'm lost.\" That's facts.\n[double-time] Reading reviews of a pouch at two a.m. for a pocket I don't even own, comparing the zippers, the stitching, the nylon, the weight and the clips and the loops for a pen,\nThen I lose it a week after buying it, find it in the van in a bag in a bag in a bag, and I'm back at the research for a better one, again, and again, and again,\n[half-time] It's always something.\n[pause] Story of my life.\n\n[Hook: chanted hard, doubled]\nAlways scatter-brained. ScattaBrain.\nSit me down with the motivation, I'm a genius. Same brain.\nI am no genius. I'm just smarter than I appear.\nScattaBrain Genius. Been him since a kid. I'm still here.\n\n[Verse 3: strings swell, drums hit harder]\nForty, give or take, reading 'bout ADHD on my phone,\nEvery video's a mirror: \"So that's why. My whole life.\" Alone\nIn the car outside the job, and the whole puzzle clicking in,\nThirty years of \"lazy\" getting overturned like a conviction.\nBut when the motivation hits, motherfucker, watch the lights dim:\nFixed a million-five machine so the patients ain't cancelled. Hymn.\nBuilt a family planner website with a login and a calendar;\nRead eighty-one thousand messages for this. Scatter? Nah. Scavenger.\nThe obstacle was always me: the opponent, the wall, the scatter,\nAnd the genius is the guy who sits down with it anyway. That's what matters.\n[double-time] Scattered like birdshot, a spread of a couple hundred pellets at once out the barrel, it looks like a mess on the paper, a cloud, a confusion, a scar,\nBut look at the target up close and the pattern is tight in the middle, and every one landed, and every one counted, and all of 'em making a heart,\n[half-time] ScattaBrain Genius.\n[pause] Smarter than I appear.\n\n[Final Hook: chanted hard, doubled]\nAlways scatter-brained. ScattaBrain.\nSit me down with the motivation, I'm a genius. Same brain.\nI am no genius. I'm just smarter than I appear.\nNamed myself before they could. Thirty years. I'm still here.\nAlways scatter-brained. ScattaBrain.\nSit me down with the motivation, I'm a genius. Same brain.\nI am no genius. I'm just smarter than I appear.\nScattaBrain Genius. Been him since a kid. I'm still here.", "suno": {"title": "The ScattaBrain Genius", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 93 BPM, hard slamming drum break, cracking snare, chopped dissonant minor-key piano stabs, scattered glitchy tape stutters, ominous low strings, deep distorted bass, vinyl grit, raw mix; male mid-low rap, aggressive technical delivery with sardonic humor, relentless dense multisyllabic rhymes, rapid double-time bursts, hard chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 9, 2026. Writer: Cue (Claude). Concept and hook phrases: Scatta (your name-origin message, #041926, February 8, 2023, and the Lyric Mine, \"The ScattaBrain Genius\"). Status: written listening candidate, unauditioned and unapproved. Possible intro or title track.", "chars": 4373}, {"stem": "the-scattabrain-genius_v02_Cue", "version": 2, "writer": "Cue", "session": "Oct 9 Lyric Mine", "folder": "2026-10-09-Lyric-Mine", "title": "The ScattaBrain Genius", "lyrics": "[Intro: tape stutters, a scratch on \"scatter,\" then the break slams in]\n\n[Verse 1]\nPicture a kid with a head like a jar of loose screws, shaken;\nTeacher's talking, I'm a radio between two stations.\nRead a page, get to the bottom, and the top's already vapor;\nBack to the top, read it again, like a printer jammed with paper.\nSwore I was a good reader. Few minutes at a time.\nThen the words slide off the margin like the rain on a windshield. Blind.\n\"Always scatter-brained,\" that's the file that followed me,\nSmart kid, lazy kid, \"If he'd only apply himself,\" the eulogy.\nSo I named myself before they could, half insult and half a dare:\nScattaBrain Genius. Wrote it on everything. Still there.\n[double-time] Scattered like a bag of marbles on a gym floor rolling under the bleachers, the lockers, the doors and the vents, never the same way twice in a row, and nobody catching 'em,\nBut give me a reason, a fire, a deadline, a puzzle, a motive, I'll sit and I'll process for days till it's taken apart on the table and put back together, and stacking 'em,\n[half-time] Scatter-brained.\n[pause] Then genius. Sometimes.\n\n[Hook: chanted hard, doubled]\nAlways scatter-brained. ScattaBrain.\nSit me down with the motivation, I'm a genius. Same brain.\nI am no genius. I'm just smarter than I appear.\nScattaBrain Genius. Been him since a kid. I'm still here.\nAlways scatter-brained. ScattaBrain.\nSit me down with the motivation, I'm a genius. Same brain.\nI am no genius. I'm just smarter than I appear.\nScattaBrain Genius. Been him since a kid. I'm still here.\n\n[Verse 2]\nThirty years later: same brain, bigger mess, better lighting.\nPacked my lunch, left it by the trash can downstairs. Shrimp. I'm fighting\nBack tears over shrimp. Brewed a pot without the coffee in it;\nHot water, a filter and a grown man staring at it for a minute.\nTook a steak out of the freezer, put it somewhere. Never found it.\nIt's still out there thawing, free, a fugitive. I'm proud of it.\nCameras, then backpacks, then sling bags, then pouches for weeks;\n\"It's always something.\" Hyperfocus: a tunnel, and the light's another tunnel. Bleak.\nPut a thing off for years, then it took me twenty seconds flat:\n\"Story of my life.\" \"I need a time and location or I'm lost.\" And that's that.\n[double-time] Reading reviews of a pouch at two a.m. for a pocket I don't even own, comparing the zippers, the stitching, the nylon, the weight and the clips and the loops for a pen,\nThen I lose it a week after buying it, find it in the van in a bag in a bag in a bag, and I'm back at the research for a better one, again, and again, and again,\n[half-time] It's always something.\n[pause] Story of my life.\n\n[Hook: chanted hard, doubled]\nAlways scatter-brained. ScattaBrain.\nSit me down with the motivation, I'm a genius. Same brain.\nI am no genius. I'm just smarter than I appear.\nScattaBrain Genius. Been him since a kid. I'm still here.\n\n[Verse 3: strings swell, drums hit harder]\nForty, give or take, reading 'bout ADHD on my phone,\nEvery video's a mirror: \"So that's why. My whole life.\" Alone\nIn the car outside the job, and the whole puzzle clicking in,\nThirty years of \"lazy\" getting overturned like a conviction.\nBut when the motivation hits, motherfucker, watch the lights dim:\nElbow-deep in a million-five machine so the patients don't cancel, limb by limb;\nBuilt a family planner website with a login and a calendar;\nRead eighty-one thousand messages for this. Scatter? Nah. Scavenger.\nThe obstacle was always me: the opponent, the wall, the scatter,\nAnd the genius is the guy who sits down with it anyway. That's what matters.\n[double-time] Scattered like birdshot, a spread of a couple hundred pellets at once out the barrel, it looks like a mess on the paper, a cloud, a confusion, a scar,\nBut look at the target up close and the pattern is tight in the middle, and every one landed, and every one counted, and all of 'em making a heart,\n[half-time] ScattaBrain Genius.\n[pause] Smarter than I appear.\n\n[Final Hook: chanted hard, doubled]\nAlways scatter-brained. ScattaBrain.\nSit me down with the motivation, I'm a genius. Same brain.\nI am no genius. I'm just smarter than I appear.\nNamed myself before they could. Thirty years. I'm still here.\nAlways scatter-brained. ScattaBrain.\nSit me down with the motivation, I'm a genius. Same brain.\nI am no genius. I'm just smarter than I appear.\nScattaBrain Genius. Been him since a kid. I'm still here.", "suno": {"title": "The ScattaBrain Genius", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 93 BPM, hard slamming drum break, cracking snare, chopped dissonant minor-key piano stabs, scattered glitchy tape stutters, ominous low strings, deep distorted bass, vinyl grit, raw mix; male mid-low rap, aggressive technical delivery with sardonic humor, relentless dense multisyllabic rhymes, rapid double-time bursts, hard chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v02. October 9, 2026. Writer: Cue (Claude). Concept and hook phrases: Scatta (your name-origin message, #041926, February 8, 2023, and the Lyric Mine, \"The ScattaBrain Genius\"). Status: written listening candidate, unauditioned and unapproved. Possible intro or title track.", "chars": 4413}], "title": "The ScattaBrain Genius", "session": "Oct 9 Lyric Mine", "latest": "the-scattabrain-genius_v02_Cue"}, {"slug": "twenty-four-hours", "ep": false, "versions": [{"stem": "twenty-four-hours_v01_Cue", "version": 1, "writer": "Cue", "session": "Oct 9 Lyric Mine", "folder": "2026-10-09-Lyric-Mine", "title": "Twenty-Four Hours", "lyrics": "[Intro: a stopwatch clicks on and ticks, then the drums]\n\n[Verse 1]\nDecember twentieth, two twenty-nine a.m., the house asleep but me:\n\"I was thinking about you all day.\" \"Falling head over heels\" again. See,\nI did everything you asked, and I'd have happily done more,\nWaited all night like a dog that hears the car door, by the door.\n\"All I asked for was a few minutes of your time last night.\"\nFew minutes. Not a weekend. Not a trip. Not a ring. Not a flight.\n\"I'm sleeping.\" Then the shoulder. Then the wall. Then the snore.\nI'm lying in the dark doing math like I'm studying for a board:\nSixty seconds in a minute, sixty minutes in an hour,\nTwenty-four of those, and I'd have given every one. Every flower.\n[double-time] Eighty-six thousand four hundred seconds in a day, I'd have handed you all of 'em, wrapped in a bow, in a box, with a card, with the timer still running, the battery new,\nAnd I asked for one, just one, a single tick of the clock, a blink, an exhale, a \"c'mere,\" a hand on the back of my neck, and the second went somewhere, not me, and not you,\n[half-time] Twenty-four hours for one second.\n[pause] Didn't get it.\n\n[Hook: chanted low, doubled]\nTwenty-four hours. I'd have given you the day.\nEighty-six thousand four hundred seconds. You couldn't give me one. Okay.\nAll I asked was a few minutes. Got a shoulder and a wall.\nTwenty-four hours for one second. Didn't get it at all.\nTwenty-four hours. I'd have given you the day.\nEighty-six thousand four hundred seconds. You couldn't give me one. Okay.\nAll I asked was a few minutes. Got a shoulder and a wall.\nTwenty-four hours for one second. Didn't get it at all.\n\n[Verse 2]\nOctober, a list of needs. \"Here's one for me. Respect.\"\n\"We should be equals in this relationship.\" Correct.\n\"If I tell you that your actions hurt me, please do not pour salt on my wounds,\"\nDon't drag the past into the room like it's evidence. It's monsoon\nSeason every time I bleed: I show a cut, you show a scar,\nAnd now we're comparing injuries in a parking lot instead of getting in the car.\nHospital rule: triage. One bed. Who's bleeding more?\n\"In that moment, I am the one who is injured, not you.\" That's the score.\nThen the line I'm proudest of, the one I'd tattoo on a wrist:\n\"Would you please try to help me heal instead of just showing me your scars?\" That's it.\n[double-time] Two patients on one gurney in a hallway with the monitors screaming and nobody in scrubs, and we're both pointing at the other one's chart, saying \"him first,\" \"her first,\" \"no, look at mine, it's worse,\"\nAnd the tech in me wants to hook up the leads and get a reading and prove whose rhythm is failing, but a heart isn't a contest, and the bleeding don't care who bled first,\n[half-time] Help me heal.\n[pause] Then I'll help you.\n\n[Hook: chanted low, doubled]\nTwenty-four hours. I'd have given you the day.\nEighty-six thousand four hundred seconds. You couldn't give me one. Okay.\nAll I asked was a few minutes. Got a shoulder and a wall.\nTwenty-four hours for one second. Didn't get it at all.\n\n[Verse 3: strings drop out, stopwatch and drums only]\nChristmas Eve, nine thirty-nine p.m., the tree lit, the presents wrapped:\n\"The more I fight, the more distant I get. The more I want, the more I lose.\" Trapped.\nLike a finger trap: the harder that I pull, the tighter it gets;\nLike quicksand, like a riptide: swim straight at the shore and you drown in regrets.\n\"I am doing my best to not fight, not argue and not care.\"\nThree nots. A man unplugging his own heart, wire by wire, from the chair.\n\"It's hard doing something I am programmed to do.\" That's the firmware:\nCaring's in the code. You can't uninstall it. Never could. Swear.\nSo I'm sitting by the tree, debugging my own instincts,\nCommenting out the lines that love you, one by one, in the dark, in silence.\n[double-time] Rem out the \"call her,\" rem out the \"wait up,\" rem out the \"text her good night,\" rem out the \"turn on location,\" rem out the \"please,\" and compile it, and run it, and watch it crash,\nBack to the top, back to the line from the summer, the one that was true before all of the rest of it, the one that still holds, like the last clean backup, before the glass,\n[half-time] \"I do not trust you like I did.\n[pause] But I trust you enough to let you go.\"\n\n[Final Hook: chanted low, doubled, the stopwatch stops]\nTwenty-four hours. I'd have given you the day.\nEighty-six thousand four hundred seconds. Now I'm keeping 'em. Okay.\nAll I asked was a few minutes. Now they're for the girls, the shop, the hall.\nTwenty-four hours, and they're mine now. Took the second back. That's all.\nTwenty-four hours. I'd have given you the day.\nEighty-six thousand four hundred seconds. You couldn't give me one. Okay.\nAll I asked was a few minutes. Got a shoulder and a wall.\nTwenty-four hours for one second. Didn't get it at all.", "suno": {"title": "Twenty-Four Hours", "lyrics": null, "style": "Dark gritty underground East Coast boom-bap, late 90s, 88 BPM, heavy dusty drum break, dry snare, ticking stopwatch and clock textures locked to the beat, cold minor-key piano loop, low mournful strings, ER hallway ambience in verse two, deep bass, vinyl crackle, raw mix; male mid-low rap, wounded precise delivery with dry dark wit, dense internal rhymes, rapid double-time bursts, low chanted hook, close dry vocal", "exclude": "comedic, playful, whimsical, upbeat, bouncy, bright, major key, brass, vibraphone, woodblock, synth blips, R&B singing, melismatic runs, auto-tune, trap, pop, EDM, choir, female vocals, polished mix"}, "header": "Version v01. October 9, 2026. Writer: Cue (Claude). Concept and hook: Scatta (\"I would have given you 24 hours of my day if you asked and I felt like you couldn't give me 1 second of your day.\" #073285, 2:29 a.m., December 20, 2024; plus #069252, #073782, #065536 from The 30 lines). Status: written listening candidate, unauditioned and unapproved.", "chars": 4828}], "title": "Twenty-Four Hours", "session": "Oct 9 Lyric Mine", "latest": "twenty-four-hours_v01_Cue"}];
